    #[test]
    fn whitespace_after_slash_closes_menu() {
        // Once the user types args, menu goes away so arrow keys don't
        // start navigating a stale palette.
        let reg = CommandRegistry::builtin();
        let custom = CustomCommandRegistry::empty();
        assert!(build_menu_items("/cd ", 0, &reg, &custom, None, None).is_none());
        assert!(build_menu_items("/cd /tmp", 0, &reg, &custom, None, None).is_none());
    }

    #[test]
    fn slash_with_no_matches_returns_none() {
        let reg = CommandRegistry::builtin();
        let custom = CustomCommandRegistry::empty();
        assert!(build_menu_items("/zzznomatch", 0, &reg, &custom, None, None).is_none());
    }

    #[test]
    fn at_directory_completion_can_build_child_menu() {
        let reg = CommandRegistry::builtin();
        let custom = CustomCommandRegistry::empty();
        let index = file_index::FileIndex::from_entries(
            std::path::PathBuf::from("/tmp"),
            vec![
                file_index::Entry {
                    rel_path: "crates/".into(),
                    is_dir: true,
                    depth: 1,
                },
                file_index::Entry {
                    rel_path: "crates/atomcode-bridge/".into(),
                    is_dir: true,
                    depth: 2,
                },
                file_index::Entry {
                    rel_path: "crates/atomcode-bridge/src/".into(),
                    is_dir: true,
                    depth: 3,
                },
                file_index::Entry {
                    rel_path: "crates/atomcode-bridge/Cargo.toml".into(),
                    is_dir: false,
                    depth: 3,
                },
            ],
        );
        let replacement = file_index::format_at_mention_replacement("crates/atomcode-bridge/");

        let items = build_menu_items(
            &replacement,
            replacement.len(),
            &reg,
            &custom,
            None,
            Some(&index),
        )
        .expect("directory completion should immediately show child entries");

        assert_eq!(
            items
                .iter()
                .map(|(path, _)| path.as_str())
                .collect::<Vec<_>>(),
            vec![
                "crates/atomcode-bridge/src/",
                "crates/atomcode-bridge/Cargo.toml",
            ]
        );
    }

    /// Guards the streaming-phase `@`-mention selection arm added to
    /// `handle_streaming_key` (mod.rs ~11386). That arm's trigger condition
    /// is `detect_at_mention_range(buf, cursor).is_some()`, so verifying
    /// these two boundary behaviours pins the arm's reach without spinning
    /// up a full App + ctx + renderer (the streaming handler's integration
    /// test would be disproportionate).
    #[test]
    fn streaming_at_mention_selection_arm_guard_boundaries() {
        // `@`-mention menu active: bare `@<partial>` token at cursor —
        // the new arm MUST match (Enter completes, not submits).
        let buf = "@crates";
        let cursor = buf.len();
        assert!(
            file_index::detect_at_mention_range(buf, cursor).is_some(),
            "@-mention token at cursor must satisfy the new arm guard"
        );
        // Cursor positioned INSIDE the token (mid-token Enter) also
        // matches — the arm should complete at any cursor within the
        // @-token, mirroring idle behaviour.
        assert!(
            file_index::detect_at_mention_range(buf, buf.len() - 2).is_some(),
            "cursor inside an @-token must still satisfy the guard"
        );

        // Slash command menu: buffer starts with `/` — the new arm
        // MUST NOT match, so slash selection falls through to the
        // existing commit arm's "slash commands are disabled while a
        // turn is running" hint. Bug would be silently swallowing slash
        // Enter mid-stream.
        let slash_buf = "/he";
        assert!(
            file_index::detect_at_mention_range(slash_buf, slash_buf.len()).is_none(),
            "slash command buffer must NOT satisfy the @-mention guard"
        );

        // Empty buffer / no `@` at all — arm must not match.
        assert!(
            file_index::detect_at_mention_range("", 0).is_none(),
            "empty buffer must not satisfy the @-mention guard"
        );
        assert!(
            file_index::detect_at_mention_range("plain text", 9).is_none(),
            "buffer with no @ must not satisfy the guard"
        );

        // Replacement format: directory selections keep the trailing
        // slash so the token stays drill-down-ready. This is the exact
        // shape the arm writes into the buffer on Enter/Tab.
        assert_eq!(
            file_index::format_at_mention_replacement("crates/atomcode-tuix/"),
            "@crates/atomcode-tuix/",
        );
        assert_eq!(
            file_index::format_at_mention_replacement("Cargo.toml"),
            "@Cargo.toml ",
        );
    }

    fn skill_fixture(
        name: &str,
        desc: &str,
        user_invocable: bool,
    ) -> atomcode_capabilities::skills::Skill {
        atomcode_capabilities::skills::Skill {
            name: name.to_string(),
            description: desc.to_string(),
            template: "do thing".to_string(),
            user_invocable,
            allowed_tools: vec![],
            skill_dir: std::path::PathBuf::new(),
            source_path: std::path::PathBuf::new(),
        }
    }

    #[test]
    fn top_level_hides_individual_skills() {
        // Regression for the two-level palette: typing /bra or any
        // bare-name prefix must NOT surface skills. They live behind
        // the `/skills` gateway so the top palette stays uncluttered.
        let reg = CommandRegistry::builtin();
        let custom = CustomCommandRegistry::empty();
        let mut skills = atomcode_capabilities::skills::SkillRegistry::new();
        skills.register(skill_fixture("skills:brainstorming", "Brainstorm", true));
        skills.register(skill_fixture("skills:web-access", "Web", true));
        let lock = std::sync::RwLock::new(skills);

        // /bra — no skill should appear; /bra falls through to "no
        // matches" since no built-in starts with bra either.
        assert!(
            build_menu_items("/bra", 0, &reg, &custom, Some(&lock), None).is_none(),
            "individual skills must not leak into the top-level menu"
        );

        // /skills — only the built-in gateway entry, never the
        // individual skills.
        let items = build_menu_items("/skills", 0, &reg, &custom, Some(&lock), None)
            .expect("/skills must include the built-in gateway");
        assert!(items.iter().any(|(n, _)| n == "skills"));
        for (n, _) in &items {
            assert!(
                !n.contains(':'),
                "namespaced skill leaked into top-level: {}",
                n
            );
        }
    }

    #[test]
    fn skills_sub_mode_lists_skills_under_bare_names() {
        // Once the user has typed `/skills ` (trailing space, normally
        // injected by the needs_args path on Enter), the palette
        // switches to second-level: bare skill names, ready to commit
        // as `/skills <name>`.
        let reg = CommandRegistry::builtin();
        let custom = CustomCommandRegistry::empty();
        let mut skills = atomcode_capabilities::skills::SkillRegistry::new();
        skills.register(skill_fixture("skills:brainstorming", "Brainstorm", true));
        skills.register(skill_fixture("skills:web-access", "Web", true));
        let lock = std::sync::RwLock::new(skills);

        let items = build_menu_items("/skills ", 0, &reg, &custom, Some(&lock), None)
            .expect("/skills (with space) must list skills");
        // Sub-mode lists BARE names (the dispatcher re-qualifies to `skills:<name>` on
        // submit) — matches build_skill_menu_items_lists_unique_bare_names + the documented design.
        assert!(items.iter().any(|(n, _)| n == "brainstorming"));
        assert!(items.iter().any(|(n, _)| n == "web-access"));
        for (n, _) in &items {
            assert!(!n.contains(':'), "sub-mode names are bare: {}", n);
        }
    }

    #[test]
    fn skills_sub_mode_filters_by_bare_prefix() {
        // /skills bra narrows to brainstorming. /skills web narrows
        // to web-access. /skills zz returns no menu at all.
        let reg = CommandRegistry::builtin();
        let custom = CustomCommandRegistry::empty();
        let mut skills = atomcode_capabilities::skills::SkillRegistry::new();
        skills.register(skill_fixture("skills:brainstorming", "Brainstorm", true));
        skills.register(skill_fixture("skills:web-access", "Web", true));
        let lock = std::sync::RwLock::new(skills);

        let bra = build_menu_items("/skills bra", 0, &reg, &custom, Some(&lock), None)
            .expect("filter must produce a result");
        assert_eq!(bra.len(), 1);
        assert_eq!(bra[0].0, "brainstorming");

        let web = build_menu_items("/skills web", 0, &reg, &custom, Some(&lock), None)
            .expect("filter must produce a result");
        assert_eq!(web.len(), 1);
        assert_eq!(web[0].0, "web-access");

        assert!(build_menu_items("/skills zz", 0, &reg, &custom, Some(&lock), None).is_none());
    }

    #[test]
    fn skills_sub_mode_hides_after_skill_name() {
        // /skills brainstorming why X — user is typing skill args now,
        // menu should disappear so arrow keys don't navigate stale entries.
        let reg = CommandRegistry::builtin();
        let custom = CustomCommandRegistry::empty();
        let mut skills = atomcode_capabilities::skills::SkillRegistry::new();
        skills.register(skill_fixture("skills:brainstorming", "Brainstorm", true));
        let lock = std::sync::RwLock::new(skills);

        assert!(build_menu_items(
            "/skills brainstorming why",
            0,
            &reg,
            &custom,
            Some(&lock),
            None
        )
        .is_none());
    }

    #[test]
    fn skills_sub_mode_excludes_hidden_skills() {
        // user_invocable=false skills must not surface in the sub-menu
        // either — they're LLM-only via the use_skill tool.
        let reg = CommandRegistry::builtin();
        let custom = CustomCommandRegistry::empty();
        let mut skills = atomcode_capabilities::skills::SkillRegistry::new();
        skills.register(skill_fixture("skills:visible", "shown", true));
        skills.register(skill_fixture("skills:hidden", "hidden", false));
        let lock = std::sync::RwLock::new(skills);

        let items = build_menu_items("/skills ", 0, &reg, &custom, Some(&lock), None)
            .expect("at least one visible skill should produce a menu");
        assert!(items.iter().any(|(n, _)| n == "visible"));
        assert!(
            !items.iter().any(|(n, _)| n == "hidden"),
            "user_invocable=false skill leaked into sub-menu"
        );
    }

    #[test]
    fn skills_sub_mode_multi_fragment_filters_then_closes_on_complete_skill() {
        let reg = CommandRegistry::builtin();
        let custom = CustomCommandRegistry::empty();
        let mut skills = atomcode_capabilities::skills::SkillRegistry::new();
        skills.register(skill_fixture("skills:atomcode-smoke-test", "smoke", true));
        skills.register(skill_fixture(
            "skills:delegating-to-atomcode",
            "delegate",
            true,
        ));
        let lock = std::sync::RwLock::new(skills);

        // `/skills atom smoke` keeps the menu OPEN and narrows to the one skill
        // matching both fragments — the reported bug (a space used to kill it).
        let items = build_menu_items("/skills atom smoke", 0, &reg, &custom, Some(&lock), None)
            .expect("multi-fragment filter must keep the menu open");
        assert_eq!(items.len(), 1);
        assert_eq!(items[0].0, "atomcode-smoke-test");

        // Once the first token is a COMPLETE skill followed by a space, the user
        // is typing task args — close the menu so Enter submits (and the accepted
        // `/skills <full-name> ` rewrite lands here after selection).
        assert!(
            build_menu_items(
                "/skills atomcode-smoke-test ",
                0,
                &reg,
                &custom,
                Some(&lock),
                None
            )
            .is_none(),
            "a complete skill + space must close the menu so Enter submits"
        );
    }

    #[test]
    fn effort_top_level_is_gateway_only() {
        // `/effort` at the top level surfaces the gateway entry, not the
        // individual high/max/off choices (those live behind `/effort `).
        let reg = CommandRegistry::builtin();
        let custom = CustomCommandRegistry::empty();
        let items = build_menu_items("/effort", 0, &reg, &custom, None, None)
            .expect("/effort gateway must appear");
        assert!(items.iter().any(|(n, _)| n == "effort"));
        assert!(!items
            .iter()
            .any(|(n, _)| matches!(n.as_str(), "low" | "medium" | "high" | "max" | "default")));
    }

    #[test]
    fn effort_sub_mode_lists_and_filters_choices() {
        let reg = CommandRegistry::builtin();
        let custom = CustomCommandRegistry::empty();
        // `/effort ` (trailing space) → every reasoning-effort choice.
        let all = build_menu_items("/effort ", 0, &reg, &custom, None, None)
            .expect("/effort sub-mode must list choices");
        let names: Vec<&str> = all.iter().map(|(n, _)| n.as_str()).collect();
        assert!(
            ["low", "medium", "high", "max", "default"]
                .iter()
                .all(|v| names.contains(v)),
            "got: {names:?}"
        );
        // Prefix narrows.
        let hi = build_menu_items("/effort hi", 0, &reg, &custom, None, None)
            .expect("`hi` must match high");
        assert_eq!(hi.len(), 1);
        assert_eq!(hi[0].0, "high");
        // No match → no menu.
        assert!(build_menu_items("/effort zz", 0, &reg, &custom, None, None).is_none());
        // A chosen value followed by a space (typing past) hides the menu.
        assert!(build_menu_items("/effort high ", 0, &reg, &custom, None, None).is_none());
    }

    #[test]
    fn effort_applicable_ignores_provider_type_and_matches_webui() {
        // Any endpoint with an explicitly configured effort is applicable — the
        // TUI must no longer hide the control behind a `{deepseek, openai}`
        // provider_type gate the webui/wire never applied.
        assert!(effort_applicable(
            Some("medium"),
            "internal-anthropic",
            "claude-x"
        ));
        assert!(effort_applicable(Some("high"), "internal-ollama", "qwen"));
        // Unconfigured custom endpoint → not applicable.
        assert!(!effort_applicable(None, "internal-glm", "glm-5.2"));
        // Built-in CodingPlan DeepSeek V4 Flash → applicable without a config value
        // (matches `models_from_config`); a codingplan name with another model is not.
        assert!(effort_applicable(
            None,
            "AtomGit-deepseek-v4-flash",
            "deepseek-v4-flash"
        ));
        assert!(!effort_applicable(
            None,
            "AtomGit-deepseek-v4-flash",
            "glm-5.2"
        ));
    }

