    #[test]
    fn plan_mode_block_reason_detects_gate_blocks() {
        // A PlanModeGate block → calm hint (reason without the `blocked: ` prefix).
        assert_eq!(
            plan_mode_block_reason(
                "blocked: plan mode is active — `write_file` would modify the workspace",
                false
            ),
            Some("plan mode is active — `write_file` would modify the workspace")
        );
        // Successes, non-block failures, and OTHER middleware blocks (e.g. approval
        // deny) are NOT plan-mode hints → normal ✗ result render.
        assert_eq!(plan_mode_block_reason("ok", true), None);
        assert_eq!(plan_mode_block_reason("Error: file not found", false), None);
        assert_eq!(
            plan_mode_block_reason("blocked: denied by approval policy: bash", false),
            None
        );
    }

    #[test]
    fn credential_policy_block_matches_only_the_stable_reason() {
        let result = format!(
            "blocked: {}",
            atomcode_capabilities::tools::credential_bash_gate::CREDENTIAL_BASH_DENIAL_REASON
        );
        assert!(credential_policy_blocked(&result, false));
        assert!(!credential_policy_blocked(
            "blocked: plugin supplied arbitrary reason",
            false
        ));
        assert!(!credential_policy_blocked(
            "blocked: plan mode is active",
            false
        ));
        assert!(!credential_policy_blocked(&result, true));
    }

    #[test]
    fn batched_edit_display_preserves_diff_and_stats() {
        let output = "Edited src/main.rs (1 replacement)\n@@ -1,2 +1,2 @@\n-old\n+new\n context";
        let display = batched_edit_display("edit_file", output, true).expect("edit display");

        assert_eq!(display.summary, "Edited src/main.rs");
        assert_eq!(display.diff_stats, (1, 1));
        assert_eq!(display.entries.len(), 3);
        assert!(batched_edit_display("read_file", output, true).is_none());
        assert!(batched_edit_display("edit_file", output, false).is_none());
        assert!(batched_edit_display("edit_file", "Edited src/main.rs", true).is_none());
    }

    #[test]
    fn approval_denial_label_detects_denials() {
        // Policy denial → calm label (non-empty).
        let label = approval_denial_label(
            "blocked: denied by approval policy: mcp__x__y {\"a\":1}",
            false,
        );
        assert!(label.is_some());
        assert!(!label.unwrap().is_empty());

        // User-interactive denial → calm label.
        let label2 = approval_denial_label("Tool 'bash' was denied by the user.", false);
        assert!(label2.is_some());
        assert!(!label2.unwrap().is_empty());

        // Success → None.
        assert_eq!(approval_denial_label("ok", true), None);

        // Non-denial failure → None (keeps normal ✗ render).
        assert_eq!(approval_denial_label("Error: file not found", false), None);
    }

