fn goal_terminal_is_met(terminal: Option<atomcode_coding::GoalTerminal>) -> bool {
    terminal == Some(atomcode_coding::GoalTerminal::Met)
}

/// Whether the per-turn stats separator should be DEFERRED (buffered) rather than
/// rendered now, on account of an active goal. It is deferred ONLY while the goal
/// is still `Pursuing` (a mid-goal round whose separator the next round banner or
/// the goal-end flush will render). Once the goal reaches a terminal/paused phase
/// (`Satisfied`/`PausedAtCap`/`Ended`) the round is over and the separator must
/// render immediately: a persistent goal keeps `goal_condition` set through the
/// terminal `TurnComplete`, and the goal-end `GoalChanged` (processed first) already
/// ran its flush against an empty buffer — deferring here would orphan the stats line.
fn goal_defers_turn_separator(goal_condition_set: bool, phase: atomcode_coding::GoalPhase) -> bool {
    goal_condition_set && matches!(phase, atomcode_coding::GoalPhase::Pursuing)
}

/// Whether the goal badge's elapsed clock should reset. It resets when the goal
/// (re-)enters `Pursuing` from a non-Pursuing state — a fresh `/goal`, or re-engaging
/// a `Satisfied`/`PausedAtCap` goal — or on the very first update (clock unset). It
/// deliberately does NOT reset on a mid-Pursuing update that also carries `round == 0`
/// (e.g. the async `AdjustGoalRounds` budget correction), which would otherwise rewind
/// a fresh goal's clock mid-first-turn. `entering_from_pursuing` = the badge was
/// already showing a Pursuing goal before this update.
fn goal_clock_should_reset(entering_from_pursuing: bool, clock_unset: bool) -> bool {
    !entering_from_pursuing || clock_unset
}

#[cfg(test)]
mod goal_end_tests {
    use super::{goal_clock_should_reset, goal_defers_turn_separator, goal_terminal_is_met};
    use atomcode_coding::{GoalPhase, GoalTerminal};

    #[test]
    fn goal_clock_resets_on_reengage_not_on_mid_pursuit_update() {
        // Fresh /goal (badge not yet Pursuing, clock unset) → reset.
        assert!(goal_clock_should_reset(false, true));
        // Re-engage a Satisfied/PausedAtCap goal (badge was not Pursuing) → reset.
        assert!(goal_clock_should_reset(false, false));
        // Mid-Pursuing update — AdjustGoalRounds (round==0) or a mid-goal round — must
        // NOT rewind the clock.
        assert!(!goal_clock_should_reset(true, false));
        // Defensive: already Pursuing but clock somehow unset → set it.
        assert!(goal_clock_should_reset(true, true));
    }

    #[test]
    fn only_explicit_met_terminal_is_successful() {
        assert!(goal_terminal_is_met(Some(GoalTerminal::Met)));
        assert!(!goal_terminal_is_met(Some(GoalTerminal::Failed)));
        assert!(!goal_terminal_is_met(Some(GoalTerminal::Stopped)));
        assert!(!goal_terminal_is_met(Some(GoalTerminal::Cancelled)));
        assert!(!goal_terminal_is_met(None));
    }

    // Regression: a persistent goal keeps `goal_condition` set through the
    // terminal TurnComplete. The stats separator must only be DEFERRED while the
    // goal is still Pursuing; once it reaches Satisfied/PausedAtCap/Ended the round
    // is over and the separator must render immediately (deferring orphans it,
    // because the goal-end flush already ran empty before this TurnComplete).
    #[test]
    fn separator_defers_only_while_pursuing() {
        assert!(goal_defers_turn_separator(true, GoalPhase::Pursuing));
        assert!(!goal_defers_turn_separator(true, GoalPhase::Satisfied));
        assert!(!goal_defers_turn_separator(true, GoalPhase::PausedAtCap));
        assert!(!goal_defers_turn_separator(true, GoalPhase::Ended));
        // No goal at all → never defer (render directly).
        assert!(!goal_defers_turn_separator(false, GoalPhase::Pursuing));
    }
}

fn handle_agent_event(
    ev: AgentEvent,
    state: &mut UiState,
    think: &mut ThinkStripper,
    renderer: &mut dyn Renderer,
    pending_tools: &mut std::collections::HashMap<String, (String, String, bool)>,
    ctx: &mut LoopCtx,
    setup_pending: &mut bool,
    reasoning_buffer: &mut String,
    buf: &mut Buffer,
) {
    // Any foreground event means the stream is alive — refresh the stall clock so
    // the spinner only warns "network may be down" after genuine silence.
    state.note_stream_activity();

    // Whitelist which events should flush a buffered turn-end separator
    // BEFORE we handle them. The buffered separator was deferred at
    // `TurnComplete` precisely so that — if the goal is about to end —
    // the `✓ Goal met` banner can render ABOVE the line. So we only
    // flush on events that signal "a new action is starting" (next round
    // beginning, next tool call, next user-bound stream, etc.). Passive
    // events like `PhaseChange(Idle)` / `TokenUsage` come right after
    // `TurnComplete` but BEFORE the wrapper's `GoalUpdate(active=false)`;
    // flushing on them would render the line above the banner — the bug
    // this whitelist exists to prevent.
    //
    // `GoalUpdate(active=false)` is intentionally absent here — its
    // handler renders the banner and then flushes the separator itself
    // (with a stripped, stats-only label).
    let should_flush_now = matches!(
        &ev,
        AgentEvent::TextDelta(_)
            | AgentEvent::ReasoningDelta(_)
            | AgentEvent::ToolCallStreaming { .. }
            | AgentEvent::ToolCallStarted { .. }
            | AgentEvent::ApprovalNeeded { .. }
            | AgentEvent::PhaseChange(AgentPhase::Thinking)
            | AgentEvent::PhaseChange(AgentPhase::CallingTool(_))
            | AgentEvent::PhaseChange(AgentPhase::WaitingApproval)
            | AgentEvent::GoalUpdate { active: true, .. }
            // LoopUpdate(active=true) signals a new loop round beginning — flush any
            // buffered separator as `⚡ loop round N` before the round's first event.
            | AgentEvent::LoopUpdate { active: true, .. }
            | AgentEvent::TurnCancelled { .. }
            | AgentEvent::Error { .. }
    );
    if should_flush_now {
        flush_pending_separator(state, renderer, /* as_goal_end */ false);
    }

    match ev {
        AgentEvent::TextDelta(text) => {
            // Count streamed output for the spinner's `↑ N tokens` liveness
            // indicator (before `text` is moved into the renderer).
            state.turn_output_chars += text.chars().count();
            render_assistant_text(text, state, think, renderer);
        }
        AgentEvent::ReasoningDelta(text) => {
            // Record that reasoning was produced this turn REGARDLESS of
            // visibility — the blank-turn notice uses it to say "only reasoning,
            // press Ctrl+O" vs "no output at all".
            state.turn_saw_reasoning = true;
            // Reasoning counts as streamed output for the `↑ N tokens` indicator.
            state.turn_output_chars += text.chars().count();
            // Display reasoning/thinking content in verbose mode (Ctrl+O)
            // Only show when the user has enabled it
            if state.show_reasoning {
                reasoning_buffer.push_str(&text);
                // Flush on newline or when buffer gets large
                if reasoning_buffer.contains('\n') || reasoning_buffer.len() > 80 {
                    let output = std::mem::take(reasoning_buffer);
                    // Render as gray/dimmed text with automatic line wrapping
                    renderer.render(UiLine::ReasoningText(output));
                    renderer.flush();
                }
            }
        }
        AgentEvent::ToolCallStreaming {
            name, arg_chars, ..
        } => {
            // A turn that spends minutes emitting one huge tool call (e.g. a
            // giant script) would otherwise show no motion; count its argument
            // stream so `↑ N tokens` keeps ticking and it doesn't look hung.
            state.turn_output_chars += arg_chars;
            state.on_tool_call_streaming(&display_tool_name(&name));
        }
        AgentEvent::ToolCallStarted {
            id,
            name,
            arguments,
        } => {
            let detail = format_tool_detail(&name, &arguments);
            let detail = enrich_todo_detail(&name, &arguments, &detail, &state.todo_titles);
            let display = display_tool_name(&name);
            let projected_team = projected_team_action(&name, &arguments, ctx.is_plain_renderer);

            // The merged `todowrite` carries EITHER the full-list PLAN shape (`{todos:[…]}`) or
            // the incremental `{action}` shape; a resumed session may also carry legacy `todo`
            // calls. Distinguish by ARG SHAPE, not tool name.
            let is_todo_call = name == "todowrite" || name == "todo";
            if is_todo_call {
                stage_todo_call_preview(state, &id, &arguments);
            }
            let todo_plan = if is_todo_call {
                todo_progress_from_args(&arguments)
            } else {
                None
            };
            // Todo state is staged above but committed only by a successful
            // ToolCallResult. This keeps the live panel aligned with transcript
            // replay when middleware, cancellation, or validation rejects a call.

            // Task fan-out owns a fixed footer panel while it runs. Seed the
            // stable child rows from the call arguments before any batch /
            // approval early return; live ToolProgress events update this
            // projection in place and never enter transcript scrollback.
            let task_panel = if name == "task" && !ctx.is_plain_renderer {
                subtask_progress_from_args(&id, &arguments)
            } else {
                None
            };
            if let Some(progress) = task_panel.as_ref() {
                state.active_subtasks = Some(progress.clone());
                state.subagent_activity = None;
                if todo_panel_is_active(state) && !ctx.is_plain_renderer {
                    renderer.render(UiLine::AgentGroup {
                        progress: progress.clone(),
                        finished: false,
                    });
                    renderer.flush();
                }
            }

            // If this call is part of an active batch, the
            // ToolBatchStarted handler already rendered the group header
            // + child rows — skip the standalone ▸ ToolCallInFlight
            // line. Still record into `pending_tools` so the matching
            // ToolCallResult knows the display name + detail and skips
            // its own ▸ render too.
            // Preserve any existing entry (from ToolBatchStarted) which
            // carries the disambiguated detail — don't overwrite with
            // the raw basename (issue #439).
            if state.call_id_to_batch.contains_key(&id) {
                let entry = pending_tools
                    .entry(id)
                    .or_insert((display.clone(), detail, true));
                if let Some(action) = projected_team {
                    entry.1 = action;
                }
                state.on_tool_call_started(&display);
                return;
            }

            // The v2 kernel asks for approval from middleware BEFORE it emits
            // ToolStarted. ApprovalNeeded may therefore have already rendered the
            // static `● Tool(detail)` row for this same call id. In that case the
            // started event is only a state transition: rendering a fresh
            // ToolCallInFlight row would duplicate the tool line.
            if let Some((stored_display, stored_detail, true)) = pending_tools.get_mut(&id) {
                *stored_display = display.clone();
                *stored_detail = projected_team.unwrap_or_else(|| detail.clone());
                state.on_tool_call_started(&display);
                return;
            }

            // todowrite (non-batch, non-approval): a valid plan will be committed
            // to the persistent footer panel when its successful result arrives;
            // suppress the tool rows meanwhile. On a parse failure (`todo_plan` is
            // None), fall through so the eventual error remains visible.
            if todo_plan.is_some() {
                // call_rendered=true ⇒ ToolCallResult suppresses the result row.
                pending_tools.insert(id, (display.clone(), detail, true));
                state.on_tool_call_started(&display);
                return;
            }

            // Team has its own structured live projection. In the interactive
            // renderer, keep the action only as correlation metadata and avoid
            // painting a generic `Team` tool row whose JSON result would repeat
            // the dedicated panel. Plain/headless output remains unchanged.
            if let Some(action) = projected_team {
                pending_tools.insert(id, (display.clone(), action, false));
                state.on_tool_call_started(&display);
                return;
            }

            // A valid Task call is represented solely by the fixed Subtasks
            // panel until its terminal event. Keep the call metadata so the
            // result handler can append one compact permanent `Task(...)` row,
            // but do not create an animated body tool row or generic spinner.
            if task_panel.is_some() {
                pending_tools.insert(id, (display.clone(), detail, false));
                state.on_tool_call_started(&display);
                return;
            }

            // Emit the ▸ line immediately so users can see what command
            // is running, especially for long-running bash commands.
            renderer.render(UiLine::AssistantLineBreak);
            // Show hint for bash commands if real-time output is disabled, so
            // users see it WHILE the command runs (pressing Ctrl+O streams live
            // chunks). It rides INSIDE the ToolCallInFlight strip (renderer adds
            // the "○ " marker + muted style) — NOT as a standalone body row: a
            // separate row after the strip breaks the "strip = body tail"
            // invariant, so on commit the spinner glyph orphaned and lingered
            // next to the committed `●` (bash-only, since the hint is).
            let ctrl_o_hint = if should_show_ctrl_o_hint(&name, state.show_tool_output, &id) {
                Some("Press Ctrl+o to show real-time output while running".to_string())
            } else {
                None
            };
            renderer.render(UiLine::ToolCallInFlight {
                id: id.clone(),
                name: display.clone(),
                detail: detail.clone(),
                hint: ctrl_o_hint,
            });
            renderer.flush();

            // Mark as rendered so ToolCallResult doesn't emit it again.
            pending_tools.insert(id, (display.clone(), detail, true));
            state.on_tool_call_started(&display);
        }
        AgentEvent::ToolOutputChunk { call_id, chunk } => {
            let tool_display = pending_tools.get(&call_id).map(|(d, ..)| d.as_str());
            if state
                .active_subtasks
                .as_ref()
                .is_some_and(|progress| progress.call_id == call_id)
            {
                let (terminal_line, agent_progress) = {
                    let progress = state.active_subtasks.as_mut().expect("checked above");
                    let terminal_line = update_subtask_progress(progress, &chunk);
                    (terminal_line, progress.clone())
                };
                if let Some(terminal_line) = terminal_line {
                    // Running activity belongs to the fixed panel, but a terminal
                    // child is historical information. Commit it once so completed
                    // and failed children remain visible above the live panel.
                    renderer.render(UiLine::CommandOutput(terminal_line));
                }
                if todo_panel_is_active(state) && !ctx.is_plain_renderer {
                    renderer.render(UiLine::AgentGroup {
                        progress: agent_progress,
                        finished: false,
                    });
                }
                state.subagent_activity = None;
                renderer.flush();
                return;
            }
            // Marker-prefixed child activity is EPHEMERAL: latest wins in the footer spinner,
            // never append it to scrollback. Scope the convention to known sub-agent tools so
            // an unrelated command that emits U+001E cannot hijack the UI.
            if let Some(activity) = ephemeral_tool_activity(tool_display, &chunk) {
                state.subagent_activity = Some(activity.to_string());
                renderer.flush();
                return;
            }
            // Display real-time tool output (e.g., bash stdout/stderr). Normally
            // gated behind Ctrl+O verbose mode, but user-invoked `!` shell commands
            // and the dispatch tool's per-child progress always stream (see
            // `streams_tool_output_by_default`).
            if streams_tool_output_by_default(state.show_tool_output, &call_id, tool_display) {
                // Append to the scrollback as command output
                renderer.render(UiLine::CommandOutput(chunk));
                renderer.flush();
            }
        }
        AgentEvent::ToolCallResult {
            call_id,
            name,
            output,
            success,
            duration,
        } => {
            let todo_owned_footer_before_result = todo_panel_is_active(state);
            commit_todo_call_result(state, &call_id, &name, success);
            if todo_owned_footer_before_result
                && !todo_panel_is_active(state)
                && !ctx.is_plain_renderer
            {
                // Todo no longer owns the footer. Freeze every conversation
                // Agent block at its latest snapshot; normal Task/Team footer
                // projection resumes on the next frame.
                renderer.render(UiLine::AgentGroupsFreeze);
            }
            let credential_policy_block = credential_policy_blocked(&output, success);
            // A result for this call arrived while an approval prompt is still up ⇒ the
            // approval was resolved WITHOUT the user answering (headless timeout fail-close,
            // a displaced second approval, or a cancel). Retract the orphaned "Waiting for
            // approval" row first so it doesn't linger above the result.
            retract_stale_approval(state);
            // The `task` fan-out finished — drop its live spinner activity so a
            // completed subtask's last action doesn't linger while the parent
            // agent keeps working the rest of the turn.
            if name == "task" || name == "code_review" {
                state.subagent_activity = None;
                if state
                    .active_subtasks
                    .as_ref()
                    .is_some_and(|progress| progress.call_id == call_id)
                {
                    if todo_panel_is_active(state) && !ctx.is_plain_renderer {
                        let mut progress = state.active_subtasks.clone().expect("checked above");
                        for item in &mut progress.items {
                            if matches!(
                                item.status,
                                crate::render::SubtaskStatus::Pending
                                    | crate::render::SubtaskStatus::Running
                            ) {
                                item.status = if success {
                                    crate::render::SubtaskStatus::Completed
                                } else {
                                    crate::render::SubtaskStatus::Failed
                                };
                                item.activity = if success { "done" } else { "failed" }.into();
                            }
                        }
                        progress.completed = progress
                            .items
                            .iter()
                            .filter(|item| item.status == crate::render::SubtaskStatus::Completed)
                            .count();
                        renderer.render(UiLine::AgentGroup {
                            progress,
                            finished: true,
                        });
                    }
                    state.active_subtasks = None;
                }
            }
            // Title cache (id → content, for `todo update #N` row names) is maintained by
            // `sync_todo_titles` from `active_todos` at every panel mutation. This legacy parse
            // stays as a harmless backstop: it only INSERTS from a full-list-shaped result and
            // never clears, so it can't clobber the derived titles (a delta result yields no
            // matching lines and is a no-op).
            if name == "todo" || name == "todowrite" {
                parse_todo_titles_into(&mut state.todo_titles, &output);
            }
            // If this call belongs to an active batch, the group header
            // already accounts for it; emit a single-line `  ↳ ✓ / ✗`
            // child completion and skip the full ▸ + ⎿ body render.
            // The model still gets the full output via the ToolResult
            // message in the conversation. Task 1.3 will upgrade this
            // to in-place checkmarks on the existing child rows instead
            // of appending new lines.
            if let Some(batch_id) = state.call_id_to_batch.get(&call_id).cloned() {
                if let Some(display) = batched_edit_display(&name, &output, success) {
                    if let Some(batch) = state.active_tool_batches.get_mut(&batch_id) {
                        batch.edit_displays.insert(call_id.clone(), display);
                    }
                }
                // CC-style result-data update: `⎿ Read(mod.rs) → 200 lines`.
                // The result snippet is generic line count of the
                // output (works across read/grep/glob/bash without
                // per-tool extraction). Failure shows `→ ✗` so the
                // user can spot the broken child without reading
                // bytes-of-output.
                //
                // Renderer's ToolGroupChildUpdate finds the row by
                // call_id and CUPs to its terminal position. Falls
                // back to no-op if the group has been frozen —
                // model still gets the full ToolResult through the
                // conversation.
                // └ (U+2514 Box Drawing), → (U+2192 Arrows), ✗ (U+2717
                // Dingbats), ● (U+25CF Geometric Shapes): all in WGL4 so
                // every Windows monospace font (Consolas, NSimSun,
                // Cascadia, Microsoft YaHei) ships them. Hardcoded —
                // no `unicode_symbols` ASCII fallback — matching the
                // single-tool-call ● treatment for visual parity
                // between batched and single tool-call paths.
                let child_glyph = "\u{2514}";
                let arrow = "\u{2192}";
                // web_search shows the result SOURCE domains (e.g. `→ eol.cn,
                // gaokao.com +3`) so the user can see which sites the data came
                // from; every other tool (and a link-less search result) falls
                // back to the generic line count.
                let web_sources = (name == "web_search" && success)
                    .then(|| web_search_result_suffix(&output))
                    .flatten();
                let team_action = (name == "team" && !ctx.is_plain_renderer)
                    .then(|| {
                        pending_tools
                            .get(&call_id)
                            .map(|(_, detail, _)| detail.clone())
                    })
                    .flatten();
                let suffix = if !success {
                    format!(" {} \u{2717}", arrow)
                } else if let Some(team) = team_action
                    .as_deref()
                    .and_then(|action| team_batch_result_suffix(action, &output))
                {
                    format!(" {} {}", arrow, team)
                } else if let Some(srcs) = web_sources {
                    format!(" {} {}", arrow, srcs)
                } else {
                    let n = output.lines().count().max(1);
                    let unit = if n == 1 { "line" } else { "lines" };
                    format!(" {} {} {}", arrow, n, unit)
                };
                // Reuse the original Tool(arg) prefix the
                // ToolBatchStarted handler painted. pending_tools
                // holds (display, detail) — strip the previous "name
                // detail" join and rebuild as Short(detail) for
                // visual consistency with the initial child row.
                let prefix = pending_tools
                    .remove(&call_id)
                    .map(|(_, det, _)| {
                        if name.eq_ignore_ascii_case("bash") {
                            format!("{} {}", display_tool_name_short(&name), det)
                        } else {
                            format!("{}({})", display_tool_name_short(&name), det)
                        }
                    })
                    .unwrap_or_else(|| display_tool_name_short(&name));
                renderer.render(UiLine::ToolGroupChildUpdate {
                    batch_id,
                    call_id: call_id.clone(),
                    new_text: format!("  {} {}{}", child_glyph, prefix, suffix),
                });
                // Batch children normally collapse failures to a compact `✗`.
                // A local security denial is different: hiding its reason leaves
                // a blank-looking termination with no actionable explanation.
                if credential_policy_block {
                    render_credential_policy_error(state, renderer);
                } else if name == "team" && !success {
                    // The compact batch child still needs an actionable error;
                    // unlike successful JSON, failures have no structured panel
                    // equivalent and must remain visible.
                    renderer.render(UiLine::Error(summarise(&output)));
                } else if team_action.as_deref() == Some("result") && success {
                    if let Some(report) = team_success_notice("result", &output) {
                        renderer.render(UiLine::CommandOutput(report));
                    }
                }
                renderer.flush();
                return;
            }

            // Successful Team calls are already represented by the structured
            // Team projection. Replace raw JSON with at most one short lifecycle
            // acknowledgement. Failures deliberately fall through to the normal
            // red error path, and plain/headless renderers keep the full payload.
            if name == "team" && success && !ctx.is_plain_renderer {
                let action = pending_tools
                    .remove(&call_id)
                    .map(|(_, detail, _)| detail)
                    .unwrap_or_default();
                if let Some(notice) = team_success_notice(&action, &output) {
                    renderer.render(UiLine::AssistantLineBreak);
                    renderer.render(UiLine::CommandOutput(notice));
                }
                renderer.flush();
                return;
            }

            // Close any in-flight assistant line before emitting the pair.
            renderer.render(UiLine::AssistantLineBreak);
            // Freeze the animated in-flight tool-call row to its final
            // static `▸` icon before the `⎿ result` body row lands beneath
            // it. Pass the call_id so we only freeze if the inflight_tool matches.
            // This prevents freezing a different tool's spinner when multiple
            // tools are in flight (e.g., WriteFile result arrives while Bash spinner is active).
            renderer.render(UiLine::ToolCallCommit {
                call_id: Some(call_id.clone()),
            });

            // Prefer the display-name we stored at ToolCallStarted time;
            // fall back to converting the raw name if we missed the Start
            // (e.g. protocol surfaced a Result without a matching Start).
            let (display_name, mut detail, call_rendered) = pending_tools
                .remove(&call_id)
                .unwrap_or_else(|| (display_tool_name(&name), String::new(), false));
            if name == "task" && output.contains("<task ") && !call_rendered {
                detail = completed_task_detail(&detail, &output, success, duration);
            }

            // Filter empty tool names (model occasionally emits malformed
            // tool calls with "" as the name; agent surfaces the error via
            // a ToolCallResult but there's no useful ▸ line to render).
            let safe_name = if display_name.is_empty() {
                "(invalid)".to_string()
            } else {
                display_name
            };

            // ParallelEditFiles already streamed a per-task line tree
            // and an aggregate summary line via the SubAgentDispatch*
            // events — the ToolResult body would just repeat the same
            // info as a markdown table, doubling vertical space and
            // truncating mid-word at terminal boundaries. Skip both
            // the ▸ tool-call line and the ⎿ result line; the model
            // still receives full output via the ToolResult message
            // in the conversation.
            // todowrite: the glyph list block was already rendered at ToolCallStarted
            // (call_rendered=true); suppress both ToolCall + ToolResult lines to avoid
            // printing the raw JSON echo a second time.
            // Only suppress on SUCCESS — if the tool returned an error (bad args, etc.)
            // the user must see the error result even though the call was rendered.
            let suppress_body_echo = name == "parallel_edit_files"
                || (name == "todowrite" && call_rendered && success)
                // `task`: the per-subtask ↻/✓/✗ lines already streamed live (see
                // `streams_tool_output_by_default`), so re-rendering `summarise_task_result`
                // here would print each subtask's completion a second time. Only suppress when
                // the output is a real `<task>` result — a plan-mode block (no `<task ` blocks,
                // nothing streamed) must still show its hint.
                || (name == "task" && output.contains("<task "));

            // Only emit the tool-call line here if ApprovalNeeded didn't
            // already render it — otherwise we'd print it twice.
            if !call_rendered
                && (!suppress_body_echo || (name == "task" && output.contains("<task ")))
                && !(credential_policy_block && safe_name == "(invalid)")
            {
                renderer.render(UiLine::ToolCall {
                    name: safe_name.clone(),
                    detail: detail.clone(),
                });
            }
            if !suppress_body_echo {
                if credential_policy_block {
                    render_credential_policy_error(state, renderer);
                // A plan-mode interception isn't a failure — render it as a calm `○`
                // hint (with the gate's reason) instead of a ✗ error, so the user
                // sees WHY the tool didn't run and that they should review the plan.
                } else if is_incomplete_review_result(&name, &output, success) {
                    renderer.render(UiLine::Warning(summarise(&output)));
                } else if let Some(reason) = plan_mode_block_reason(&output, success) {
                    renderer.render(UiLine::CommandOutput(format!("  ○ {reason}\n")));
                } else if let Some(label) = approval_denial_label(&output, success) {
                    // A denial is the user's choice, not an error — render a calm `○ denied`
                    // (muted, like plan-mode blocks), dropping the verbose tool+args repeat.
                    renderer.render(UiLine::CommandOutput(format!("  ○ {label}\n")));
                } else {
                    // A single web_search call gets the same source-domain
                    // summary as the parallel child rows (`sources: eol.cn,
                    // gaokao.com +3`); fall back to the generic snippet when no
                    // links are present or on failure.
                    let summary = if name == "web_search" && success {
                        web_search_result_suffix(&output)
                            .map(|s| format!("sources: {s}"))
                            .unwrap_or_else(|| summarise(&output))
                    } else if name == "task" {
                        // Clean per-subtask lines (id · model · status) instead of the
                        // raw <task ...> block.
                        summarise_task_result(&output)
                    } else if name == "read_file" && success {
                        // Collapse the `{line}\t{indented content}` preview so a
                        // deeply-indented line doesn't render as a big left gap.
                        summarise_read_result(&output)
                    } else {
                        summarise(&output)
                    };
                    // The inline colored `(+N -N)` is the edit result's only
                    // metadata. Drop the tool's older parenthesized replacement
                    // label so the count sits directly after the file name.
                    let summary = if name == "edit_file" && success {
                        summary
                            .split_once(" (")
                            .map(|(file, _)| file.to_string())
                            .unwrap_or(summary)
                    } else {
                        summary
                    };
                    let diff_entries = if matches!(
                        name.as_str(),
                        "edit_file" | "write_file" | "create_file" | "search_replace"
                    ) {
                        let entries = crate::render::diff::parse_unified_diff(&output, 120);
                        (!entries.is_empty()).then_some(entries)
                    } else {
                        None
                    };
                    let diff_stats = diff_entries.as_ref().map(|entries| {
                        let added = entries
                            .iter()
                            .filter(|entry| entry.kind == crate::render::DiffKind::Add)
                            .count();
                        let removed = entries
                            .iter()
                            .filter(|entry| entry.kind == crate::render::DiffKind::Del)
                            .count();
                        (added, removed)
                    });
                    renderer.render(UiLine::ToolResult {
                        success,
                        summary,
                        diff_stats,
                    });
                    if let Some(entries) = diff_entries {
                        renderer.render(UiLine::EditDiffBlock(entries));
                    }
                }
            }
            // Collect diff lines into a single batch — N individual
            // DiffLine renders each trigger a full footer redraw and
            // tens of KB of ANSI, which blocks the event loop long
            // enough to stall the spinner during edit tool results.
            //
            // Gated on edit-class tools because the `+ ` / `- ` line
            // detection is purely textual: markdown bullet lists
            // (`- item`) inside non-edit tool outputs trip the same
            // pattern. The deepseek-v4-flash screenshot symptom was a
            // 162-line `UseSkill(brainstorming)` template — every `- `
            // bullet got rendered as a removed-diff line and the whole
            // skill body leaked into the scrollback. Restricting to
            // tools that actually emit diff payloads (`edit_file`,
            // `write_file`, `create_file`, `search_replace`) closes
            // that without losing the diff render where it's wanted.
            // Flush any pending diff renders before the next event.
            renderer.flush();
            let _ = name;
        }
        AgentEvent::ApprovalNeeded {
            tool_name,
            call,
            snapshot,
            ..
        } => {
            let cache_key = get_approval_cache_key(&tool_name, &call.arguments);
            let already_allowed = {
                let guard = ctx.allowed_always.lock().unwrap();
                guard.contains(&cache_key)
            };
            if already_allowed {
                deliver_approval(ctx, ApprovalChoice::AllowAlways);
                return;
            }
            // BYPASS mode (`--dangerously-skip-permissions`): auto-approve and
            // skip the prompt. The response goes through the hub when shared, so
            // all views observe the same pending request lifecycle.
            if state.agent_mode.is_auto() {
                deliver_approval(ctx, bypass_approval_choice());
                return;
            }
            // Persist mid-turn messages to session so /bg can recover
            // the conversation even when the turn hasn't finished yet.
            if !snapshot.messages.is_empty() {
                apply_session_snapshot(&mut ctx.current_session, snapshot);
                ctx.bg_manager
                    .set_foreground_session(ctx.current_session.clone(), ctx.working_dir.clone());
            }

            // Emit the `▸ Tool(detail)` row BEFORE the approval prompt
            // so the user sees what they're approving.
            let display = display_tool_name(&tool_name);
            // Prefer the disambiguated detail from `pending_tools` (populated
            // by ToolBatchStarted for parallel batches) over the raw basename
            // from format_tool_detail. Without this, parallel batch approvals
            // show "ReadFile(SKILL.md)" for every call, making it impossible
            // to tell which file is being approved (issue #439).
            let detail = pending_tools
                .get(&call.id)
                .map(|(_, det, _)| det.clone())
                .unwrap_or_else(|| format_tool_detail(&tool_name, &call.arguments));
            let defer_task_row = should_defer_task_approval_row(
                &tool_name,
                &call.id,
                &call.arguments,
                ctx.is_plain_renderer,
            );
            let projected_team =
                projected_team_action(&tool_name, &call.arguments, ctx.is_plain_renderer);

            // Check if ToolCallStarted already rendered this tool call as a
            // dynamic ToolCallInFlight spinner. If so, we need to freeze it
            // to a static `▸` row before showing the approval prompt.
            if let Some(action) = projected_team {
                // The approval panel itself names the risky Team delegation.
                // Defer its transcript row exactly like Task: once approved,
                // structured Team events own the visual lifecycle; if denied,
                // the normal failed ToolResult still renders the reason.
                pending_tools.insert(call.id.clone(), (display.clone(), action, false));
            } else if defer_task_row {
                // The approval panel already names the Task being approved.
                // Keep its transcript row deferred so ToolCallResult can append
                // exactly one permanent `Task(... completed · duration)` row.
                pending_tools.insert(call.id.clone(), (display.clone(), detail.clone(), false));
            } else if let Some(entry) = pending_tools.get_mut(&call.id) {
                let (disp, det, rendered) = entry;
                if *rendered {
                    // ToolCallInFlight is animating — commit it to a static row
                    // so the approval prompt appears below a frozen `▸ Bash(...)`.
                    // Pass the call_id to ensure we only freeze the matching tool.
                    renderer.render(UiLine::ToolCallCommit {
                        call_id: Some(call.id.clone()),
                    });
                } else {
                    // Not yet rendered, emit it now
                    renderer.render(UiLine::ToolCall {
                        name: disp.clone(),
                        detail: det.clone(),
                    });
                    *rendered = true;
                }
            } else {
                // No entry from ToolCallStarted, render and insert
                renderer.render(UiLine::ToolCall {
                    name: display.clone(),
                    detail: detail.clone(),
                });
                pending_tools.insert(call.id.clone(), (display.clone(), detail.clone(), true));
            }

            // Warn when the command about to be approved would trip the credential
            // guard: allowing it may forward secrets/sensitive content to the provider.
            let note = (call.name == "bash"
                && atomcode_capabilities::tools::bash_command_may_expose_credentials(
                    &call.arguments,
                ))
            .then(|| crate::i18n::t(crate::i18n::Msg::CredentialApprovalNote).into_owned());
            state.approval_panel = Some(crate::state::ApprovalPanel {
                tool: display.clone(),
                detail: detail.clone(),
                options: build_approval_options(&display),
                selected: 0,
                cache_key,
                note,
            });
            renderer.flush();
            atomcode_capabilities::notify::notify(
                &ctx.config.notifications,
                atomcode_capabilities::notify::NotificationEvent::ApprovalNeeded(
                    atomcode_capabilities::notify::ApprovalNotification {
                        tool_name: &display_tool_name(&tool_name),
                        detail: Some(&format_tool_detail(&tool_name, &call.arguments)),
                        working_dir: Some(&ctx.working_dir),
                    },
                ),
            );
            // `display` is the already-PascalCased name (e.g. "Bash",
            // "ReadFile"); on_approval_needed stashes the current
            // "Running X" label so on_approval_resolved can restore it.
            state.on_approval_needed(&display);
            // Redraw the footer (input box) so the user can type
            // Y/A/N in response. Without this, a prior
            // on_approval_resolved() transition to Streaming may
            // have left the footer stale — especially when
            // runtime dispatches the second approval before any
            // spinner tick fires (issue #455: "待审批输入 Y 后，
            // 输入框没了"). Use redraw_idle_plain instead of
            // draw_spinner_now because the spinner label may be
            // stale/misleading in the approval phase (mirrors the
            // /bg resume path).
            redraw_idle_plain(buf, state, ctx, renderer);
        }
        AgentEvent::PhaseChange(AgentPhase::Thinking) => {
            state.footer_persistence_warning = None;
            state.on_thinking();
        }
        AgentEvent::PhaseChange(AgentPhase::CallingTool(name)) => {
            state.on_tool_call_streaming(&display_tool_name(&name));
        }
        AgentEvent::PhaseChange(_) => {}
        AgentEvent::PolicyIntervention(intervention) => {
            state.pending_policy_intervention = Some(intervention);
            state.pending_policy_resolution = None;
        }
        AgentEvent::TurnComplete {
            duration,
            total_tokens,
            turn_count,
            tool_call_count,
            stop_reason,
            snapshot,
        } => {
            // Seal the assistant-reply buffer so `/copy` reads this completed
            // reply until the next turn's first delta starts a fresh one.
            state.response_finalized = true;
            atomcode_capabilities::notify::notify(
                &ctx.config.notifications,
                atomcode_capabilities::notify::NotificationEvent::TurnFinished(
                    atomcode_capabilities::notify::TurnNotification {
                        duration,
                        turn_count,
                        tool_call_count,
                        total_tokens: Some(total_tokens),
                        stop_reason: notify_stop_reason(stop_reason),
                        working_dir: Some(&ctx.working_dir),
                    },
                ),
            );
            // A turn that finished NATURALLY but produced no visible answer
            // (reasoning-only / `<think>`-only) would otherwise render as a
            // blank bubble — surface a notice so the user isn't left staring at
            // an empty reply with a big token count (the "怎么不给我结果" case).
            if let Some(notice) = empty_completion_notice(
                state.turn_rendered_visible_text,
                tool_call_count,
                state.turn_saw_reasoning,
                state.show_reasoning,
                stop_reason,
            ) {
                renderer.render(UiLine::Warning(notice));
            }
            renderer.render(UiLine::AssistantLineBreak);
            pending_tools.clear();
            clear_pending_todo_calls(state);
            // Footer token count: bill output + UNCACHED input (re-reading the
            // cached prefix each round is near-free). The event's `total_tokens`
            // is the v2 gross sum (prompt+completion per round) which overstates
            // usage ~10-100× on long multi-round turns — recompute from the
            // per-turn tallies instead. Falls back to the event value if no
            // per-round usage arrived (turn_prompt 0).
            let (total_tokens, cached_pct) = if state.turn_prompt_tokens > 0 {
                crate::state::turn_token_summary(
                    state.turn_prompt_tokens,
                    state.turn_completion_tokens,
                    state.turn_cached_tokens,
                )
            } else {
                (total_tokens, None)
            };
            if goal_defers_turn_separator(state.goal_condition.is_some(), state.goal_phase) {
                // A /goal is actively PURSUING more rounds: DEFER the separator so
                // the next event can choose its form — a `✓ Goal met` banner ABOVE a
                // stats-only line when the goal ends (GoalUpdate active=false), or the
                // `↻ goal round N` banner mid-goal (flushed by should_flush_now).
                // Once the goal is Satisfied/PausedAtCap/Ended the round is over, so
                // we fall through to render the separator directly (persistence keeps
                // `goal_condition` set, but the goal-end flush already ran empty).
                // `errored` rides along as a defensive fallback.
                state.pending_separator = Some(crate::state::PendingSeparator {
                    duration,
                    turn_count,
                    tool_call_count,
                    total_tokens,
                    was_goal_round: true,
                    was_loop_round: false,
                    stop_reason,
                    error_line_shown: state.turn_error_line_shown,
                    policy_denial_reason: state.last_policy_denial_reason.take(),
                    cached_pct,
                });
            } else if state.loop_label.is_some() {
                // A /loop is active: DEFER the separator. The next event can be
                // a new LLM turn start (flushed by should_flush_now as
                // `⚡ loop round N · stats`) or a LoopUpdate(active=false) that
                // signals the loop ended (handled by the LoopUpdate branch itself).
                state.pending_separator = Some(crate::state::PendingSeparator {
                    duration,
                    turn_count,
                    tool_call_count,
                    total_tokens,
                    was_goal_round: false,
                    was_loop_round: true,
                    stop_reason,
                    error_line_shown: state.turn_error_line_shown,
                    policy_denial_reason: state.last_policy_denial_reason.take(),
                    cached_pct,
                });
            } else {
                // No active goal or loop: render the turn summary immediately.
                let dur = crate::render::fmt_dur(duration);
                let label = turn_summary_label(
                    state,
                    stop_reason,
                    turn_count,
                    tool_call_count,
                    total_tokens,
                    cached_pct,
                    &dur,
                );
                renderer.render(UiLine::TurnSeparator { label });
            }
            renderer.flush();
            complete_turn_presentation(state, renderer);
            if matches!(stop_reason, ui_event::UiTurnStopReason::PolicyDenied) {
                if ctx.caps.tty {
                    activate_policy_intervention(state);
                } else if state.pending_policy_intervention.take().is_some() {
                    // A pipe/CI consumer cannot answer an interactive choice panel.
                    // Emit fixed local guidance and remain idle instead of hanging.
                    renderer.render(UiLine::CommandOutput(
                        crate::i18n::t(crate::i18n::Msg::PolicyRecoverySafeInstructions)
                            .into_owned(),
                    ));
                }
                redraw_idle_plain(buf, state, ctx, renderer);
            } else {
                // A persistence/runtime failure may replace the kernel's policy
                // terminal after the intervention event was forwarded. Never
                // carry that recovery contract into an unrelated later turn.
                state.pending_policy_intervention = None;
                state.pending_policy_resolution = None;
            }

            // Reset the think stripper between turns. If the previous turn
            // left an unclosed `<think>` in flight (cancelled mid-stream,
            // model never emitted `</think>`, provider switch that doesn't
            // use `<think>` tags like Kimi thinking-mode via reasoning_content),
            // the stripper stays `inside=true` and silently swallows every
            // TextDelta of the NEXT turn — user sees blank assistant bubbles
            // while datalog proves the model did return text.
            think.reset();

            // Clear reasoning buffer between turns
            reasoning_buffer.clear();

            // Record this turn's stats (anchored by message count) so /resume
            // can re-render the same `✓ … 工具 · tokens` divider between turns —
            // sessions persist only `messages`, so without this the per-turn
            // token/duration numbers are lost on reload and turns butt together.
            // Snapshot the context gauge (prompt occupancy + window) so `/resume`
            // can rehydrate the footer + `/context` without waiting for a new
            // live turn — see `UiState::restore_context`. Reads the same
            // `last_context.sent_tokens` the live gauge shows, for exact symmetry.
            let (last_used, last_window) = state
                .last_context
                .as_ref()
                .map(|c| (c.sent_tokens, c.ctx_window))
                .unwrap_or((0, 0));
            ctx.current_session
                .turn_stats
                .push(crate::session::TurnStat {
                    after_message: snapshot.messages.len(),
                    position_valid: true,
                    turn_count,
                    tool_call_count,
                    duration_ms: duration.as_millis() as u64,
                    total_tokens,
                    errored: turn_is_incomplete(stop_reason),
                    used_tokens: last_used,
                    ctx_window: last_window,
                });
            // Persist session after every completed turn so /resume can
            // find it after a clean exit — the whole point of sessions.
            persist_current_session(ctx, snapshot, renderer);

            // CodingPlan usage refresh — fire after each completed turn
            // (with cooldown) so the right-aligned hint reflects the
            // tokens the turn just consumed. Gated to CodingPlan users
            // only; non-CodingPlan paths skip all network activity.
            if monitor::is_codingplan_provider(&resolved_provider_and_model(&ctx.config).0) {
                let cooled = ctx
                    .usage_last_check_at
                    .map(|t| t.elapsed() >= usage_monitor::USAGE_COOLDOWN)
                    .unwrap_or(true);
                if cooled {
                    ctx.usage_last_check_at = Some(std::time::Instant::now());
                    usage_monitor::spawn_check(ctx.usage_slot.clone(), ctx.wake_tx.clone());
                }
            }

            // setup post-run side effects — only on successful TurnComplete.
            // Reload skills/commands so newly-created skills become visible
            // to the LLM immediately.
            let setup_was_pending = std::mem::take(setup_pending);
            if setup_was_pending && should_run_setup_post_turn(stop_reason) {
                let (skills_loaded, warnings) = reload_plugins(ctx);
                let warn_count = warnings.len();
                renderer.render(UiLine::CommandOutput(
                    crate::i18n::t(crate::i18n::Msg::SetupAutoReloaded {
                        skills: skills_loaded,
                        warnings: warn_count,
                    })
                    .into_owned(),
                ));
                if !warnings.is_empty() {
                    for w in &warnings {
                        renderer.render(UiLine::Error(w.clone()));
                    }
                }
                renderer.flush();
            }
        }
        AgentEvent::TurnCancelled { snapshot } => {
            // Seal the reply buffer (partial reply still copyable via `/copy`).
            state.response_finalized = true;
            if todo_panel_is_active(state) && !ctx.is_plain_renderer {
                if let Some(mut progress) = state.active_subtasks.clone() {
                    for item in &mut progress.items {
                        if matches!(
                            item.status,
                            crate::render::SubtaskStatus::Pending
                                | crate::render::SubtaskStatus::Running
                        ) {
                            item.status = crate::render::SubtaskStatus::Stopped;
                            item.activity = "cancelled".into();
                        }
                    }
                    renderer.render(UiLine::AgentGroup {
                        progress,
                        finished: true,
                    });
                }
            }
            clear_pending_todo_calls(state);
            atomcode_capabilities::notify::notify(
                &ctx.config.notifications,
                atomcode_capabilities::notify::NotificationEvent::TurnFinished(
                    atomcode_capabilities::notify::TurnNotification {
                        duration: state.turn_elapsed().unwrap_or_default(),
                        turn_count: 0,
                        tool_call_count: pending_tools.len(),
                        total_tokens: None,
                        stop_reason: atomcode_capabilities::notify::NotifyStopReason::Cancelled,
                        working_dir: Some(&ctx.working_dir),
                    },
                ),
            );
            // Render any in-flight tool calls that never got a result
            // as "(cancelled)" so the user sees what was mid-flight.
            for (_id, (name, detail, call_rendered)) in pending_tools.drain() {
                let safe_name = if name.is_empty() {
                    "(invalid)".into()
                } else {
                    name
                };
                if !call_rendered {
                    renderer.render(UiLine::ToolCall {
                        name: safe_name,
                        detail,
                    });
                }
                renderer.render(UiLine::ToolResult {
                    success: false,
                    summary: "(cancelled)".into(),
                    diff_stats: None,
                });
            }
            renderer.render(UiLine::TurnCancelled);
            renderer.flush();
            cancel_turn_presentation(state, renderer);
            *setup_pending = false;
            // Same reset rationale as TurnComplete: a cancelled turn is the
            // single most common way for `<think>` to go unclosed, so this
            // branch is even more important for the stripper's hygiene.
            think.reset();
            // Save what we did have — a user who Ctrl+C'd mid-stream
            // should still be able to /resume the cleaned conversation.
            persist_current_session(ctx, snapshot, renderer);
        }
        AgentEvent::ConversationTruncated {
            snapshot,
            restored_prompt,
            target_n,
            prompts_before,
        } => {
            handle_undo_success(
                snapshot,
                restored_prompt,
                target_n,
                prompts_before,
                state,
                renderer,
                ctx,
                buf,
            );
        }
        AgentEvent::UndoFailed {
            requested,
            available,
        } => {
            handle_undo_failure(requested, available, renderer);
        }
        AgentEvent::Error { error, snapshot } => {
            // A `reasoning_effort` rejection (openai_compat's
            // `effort_unsupported_error`) auto-disables the field at the provider
            // for the rest of the session. Clear the footer indicator so it stops
            // showing e.g. `[max]` for a value that is no longer being sent. The
            // config value is untouched (a fresh session re-syncs it and re-heals).
            // Coupled to the token in that error message; must be checked BEFORE
            // `error` is moved into the render below.
            if error.contains("reasoning_effort") {
                ctx.reasoning_effort = None;
            }
            // Capture the reason so the errored turn-summary can carry it: the
            // standalone red line below is rendered mid-turn (Streaming, spinner
            // active) and can be clobbered by the physical Streaming→Idle redraw
            // on a real terminal — the `✗ 已中断` summary renders cleanly at Idle,
            // so binding the reason to it guarantees the user sees the cause.
            state.last_turn_error = Some(error.clone());
            // The cause is now visible in a committed red line above, so the
            // errored turn-summary renders bare (`✗ 已中断 · …`) instead of
            // folding the same reason a second time.
            state.turn_error_line_shown = true;
            renderer.render(UiLine::Error(error));
            renderer.flush();
            // Diagnostic only. The runtime emits the authoritative
            // `TurnFinished` after kernel errors such as MaxRounds, RepeatLoop and
            // ToolLoopDetected; that terminal owns phase, buffer and setup
            // cleanup. Ending the turn here races queued input into the still
            // active runtime.
            state.on_error();
            // Preserve a non-empty diagnostic snapshot without treating it as
            // a terminal. Native kernel diagnostics currently carry an empty
            // snapshot, so this is normally a no-op.
            persist_current_session(ctx, snapshot, renderer);
        }
        AgentEvent::Warning(w) => {
            // Non-fatal — flush a yellow advisory line and let the turn
            // continue. Don't touch state/think/buffers; the warning is
            // purely informational. Used today for the OpenAI provider's
            // truncation detector (`prompt_tokens` reported by the proxy
            // is implausibly low for the body we sent).
            renderer.render(UiLine::Warning(w));
            renderer.flush();
        }
        AgentEvent::StreamRecovery {
            attempt,
            max_attempts,
            recovered,
        } => {
            if recovered {
                state.spinner_label = state.current_thinking().to_string();
                renderer.render(UiLine::Muted(
                    crate::i18n::t(crate::i18n::Msg::StreamRecoverySucceeded).into_owned(),
                ));
            } else {
                state.spinner_label = crate::i18n::t(crate::i18n::Msg::StreamRecoveryRunning {
                    attempt,
                    max_attempts,
                })
                .into_owned();
            }
            // Keep the running state transient in the existing streaming row;
            // only the recovered marker enters scrollback.
            renderer.flush();
        }
        AgentEvent::HookWarningHint(msg) => {
            if let Ok(mut slot) = ctx.hook_warning_hint.lock() {
                *slot = Some(msg);
            }
        }
        AgentEvent::VisionPreprocessSuccess {
            vl_model,
            char_count,
        } => {
            // Format here (not in agent) so we can localize / restyle
            // without bumping the AgentEvent contract. Char count helps
            // users notice degenerate near-zero VL outputs that would
            // mislead the main model into "image failed" responses.
            let msg = crate::i18n::t(crate::i18n::Msg::VisionPreprocessSuccess { char_count })
                .into_owned();
            renderer.render(UiLine::VisionPreprocessSuccess {
                msg,
                model: vl_model,
            });
            renderer.flush();
        }
        AgentEvent::RestorePendingImages { images, markers } => {
            // VL preprocessing failed — re-attach the user's images to
            // the input state so they can retry without re-pasting from
            // clipboard.
            //
            // Restore the full original message text (including the text
            // between [Image #N] markers) from `last_submitted_message`.
            // Without this, only markers get re-inserted into the cleared
            // buffer and the user's caption text is silently lost — the
            // user sees blank space where their text should be (bug report:
            // "多张图片发送后丢失文字，只保留了最后一张").
            if let Some(restore) = state.last_submitted_message.take() {
                buf.replace_all_text(restore);
            }
            //
            // Hash table is rebuilt as best-effort: we hash the base64
            // payload (not raw RGBA), which means a fresh clipboard copy
            // of the same image won't dedupe against this restored entry.
            // Minor UX nit, not a correctness issue.
            use std::collections::hash_map::DefaultHasher;
            use std::hash::{Hash, Hasher};
            // markers length should match images length (agent passed them
            // back); zip is best-effort if it doesn't (truncates).
            for (img, marker) in images.into_iter().zip(markers.into_iter()) {
                let mut hasher = DefaultHasher::new();
                img.data.hash(&mut hasher);
                let h = hasher.finish();
                cache_write_image(ctx.history.cache_dir(), &img, h);
                state.pending_image_hashes.push(h);
                state.pending_images.push(img);
                state.pending_image_markers.push(marker);
                // Only insert the marker if it's NOT already in the
                // restored message text — `last_submitted_message` above
                // already carries the original markers in the correct
                // positions alongside the user's text.
                let marker_text = format!("[Image #{}]", marker);
                if !buf.text.contains(&marker_text) {
                    buf.insert_at_cursor(&marker_text);
                }
            }
            // Don't redraw — TUI is in Streaming phase here (turn isn't
            // over yet); the next idle/streaming redraw picks up the new
            // pending state on its own.
        }
        AgentEvent::TokenUsage {
            tokens: u,
            used_tokens,
            ctx_window,
        } => {
            state.on_token_usage(used_tokens, ctx_window);
            state.prompt_tokens += u.prompt as usize;
            state.completion_tokens += u.completion as usize;
            state.cached_tokens += u.cached as usize;
            state.total_tokens += u.completion as usize;
            // Per-turn tallies for the footer's billable count + cache annotation
            // (reset in on_turn_complete / on_turn_cancelled).
            state.turn_prompt_tokens += u.prompt as usize;
            state.turn_completion_tokens += u.completion as usize;
            state.turn_cached_tokens += u.cached as usize;
        }
        AgentEvent::WorkingDirChanged(new_dir) => {
            // Fires when a tool (change_dir / bash cd) or
            // CodingRuntime changed the shared cwd. Sync the footer's view so the status row
            // reflects the new directory on the next redraw (spinner tick if
            // streaming, idle redraw after turn complete). Without this the
            // footer is stuck on the old path until the user types `/cd` or
            // restarts the session.
            //
            // Strip the Windows `\\?\` verbatim prefix: the emitter (runtime / kernel
            // turn runner) canonicalizes the target, so `new_dir` can arrive as
            // `\\?\C:\…` and would otherwise re-verbatim `ctx.working_dir` (and
            // recent_dirs) after `apply_cd` just stripped it. The shared projection
            // helper normalizes this event and updates every path-sensitive sink.
            commit_working_dir_projection(ctx, new_dir);
            ctx.bg_manager
                .set_foreground_session(ctx.current_session.clone(), ctx.working_dir.clone());
        }
        AgentEvent::ProjectSwitched(new_dir) => {
            // A webui /cd switched the project directory (delivered via the
            // bound native runtime in sync mode). ChangeDirectory already means
            // "fresh session in the target directory" at the runtime boundary;
            // issuing a second FreshSession here would race two replacements.
            if !commands::paths_same(&ctx.working_dir, &new_dir) {
                // Silent on success (fast transition); status only via guards.
                if let Err(error) = commands::apply_cd(ctx, new_dir) {
                    renderer.render(UiLine::Error(error));
                }
                renderer.flush();
            }
        }
        AgentEvent::RemoteSlashCommand(line) => {
            // Goal is the one stateful command exposed to the mobile App. It
            // must go through the normal TUI command handler so the TUI's
            // local goal_condition/phase state and the shared CodingRuntime
            // are updated together. Keep the other remote slash commands
            // read-only below.
            let remote = line.trim().trim_start_matches('/');
            let (remote_name, remote_arg) = remote
                .split_once(char::is_whitespace)
                .map(|(name, arg)| (name, arg.trim()))
                .unwrap_or((remote, ""));
            if remote_name.eq_ignore_ascii_case("goal") {
                let mut active_modal = None;
                if let Err(error) = commands::execute_slash_command(
                    "goal",
                    remote_arg,
                    state,
                    ctx,
                    renderer,
                    &mut active_modal,
                    setup_pending,
                ) {
                    renderer.render(UiLine::Error(format!("Goal 执行失败：{error}")));
                    renderer.flush();
                }
                return;
            }
            // 手机端发来的斜杠命令：只放行只读信息类白名单（status/cost/whoami/
            // diff），在桌面同样渲染一份（让桌面用户知道手机做了什么），输出经
            // CommandOutput 广播回手机。交互式/桌面专属命令礼貌拒绝。
            let display = format!("/{}", line.trim().trim_start_matches('/'));
            match commands::run_remote_command(ctx, state, &line) {
                Some(txt) => {
                    renderer.render(UiLine::CommandOutput(format!("（手机端执行 {display}）")));
                    renderer.render(UiLine::CommandOutput(txt.clone()));
                    renderer.flush();
                    if let Err(error) = atomcode_daemon::native_live::publish_command_output(
                        format!("{display}\n{txt}"),
                    ) {
                        renderer.render(UiLine::Error(format!(
                            "Remote command output synchronization failed: {error:?}"
                        )));
                        renderer.flush();
                    }
                }
                None => {
                    if let Err(error) =
                        atomcode_daemon::native_live::publish_command_output(format!(
                            "{display}\n  该命令需要在桌面端执行（手机端仅支持 \
                             /status /cost /whoami /diff）"
                        ))
                    {
                        renderer.render(UiLine::Error(format!(
                            "Remote command rejection synchronization failed: {error:?}"
                        )));
                        renderer.flush();
                    }
                }
            }
        }
        AgentEvent::ContextStats {
            system_tokens,
            sent_tokens,
            dropped_tokens: _,
            working_set_tokens: _,
            total_messages,
            tool_defs_tokens,
            cold_zone_tokens,
            ctx_window,
            ctx_name,
            system_prompt,
        } => {
            state.on_context_stats(
                system_tokens,
                sent_tokens,
                tool_defs_tokens,
                cold_zone_tokens,
                total_messages,
                ctx_window,
                &ctx_name,
                &system_prompt,
            );
            // If `/context` is waiting for fresh stats, the rich emission
            // (ctx_window > 0) is the signal to render. Narrow emissions
            // from the narrow runtime projection leave ctx_window at 0 and must not trigger
            // a report render (they'd race ahead of the pending refresh
            // and print partial data). Clears the flag on fire so a
            // single dispatch yields a single render even when multiple
            // rich emissions follow (e.g. inside a long multi-round turn).
            if ctx_window > 0 {
                if let Some(show_prompt) = state.pending_context_render.take() {
                    renderer.render(UiLine::CommandOutput(commands::render_context_report(
                        state,
                        ctx,
                        show_prompt,
                    )));
                    renderer.flush();
                }
            }
        }
        AgentEvent::ToolBatchStarted { batch_id, calls } => {
            // Header label: "Reading 4 files in parallel" when all calls
            // share a tool name (common case for batched read_file /
            // grep / glob); otherwise generic "Running 4 tools in
            // parallel". No tech-stack hardcoding — tool names come from
            // the model's own tool_calls.name.
            let count = calls.len();
            // A batch only runs CONCURRENTLY when ≥2 of its calls are parallel_safe
            // (read-only). Fewer than 2 (all bash, or 1 read + writes) run serially,
            // so "in parallel" would be a lie. `parallel_safe` is threaded from
            // Tool::parallel_safe() in the kernel so we never re-classify by name here.
            let concurrent = calls.iter().filter(|c| c.parallel_safe).count() >= 2;
            let unique_names: std::collections::HashSet<&str> =
                calls.iter().map(|c| c.name.as_str()).collect();
            // Generic header — no per-tool verb table inside the
            // framework. Same-name batches surface the model's own
            // tool name; mixed batches use "tools". This avoids
            // a `match tool_name { "bash" => "Running" ... }` table
            // that drifts whenever new tools land or models invent
            // names (mcp.foo, custom plugins).
            let label = match (unique_names.len() == 1, concurrent) {
                (true, true) => format!(
                    "Running {} {} calls in parallel",
                    count,
                    unique_names.iter().next().copied().unwrap_or("tool")
                ),
                (true, false) => format!(
                    "Running {} {} calls",
                    count,
                    unique_names.iter().next().copied().unwrap_or("tool")
                ),
                (false, true) => format!("Running {} tools in parallel", count),
                (false, false) => format!("Running {} tools", count),
            };
            // Header alone — child rows are NOT pre-rendered. Each
            // child surfaces as a `  ↳ ✓ name` line when its
            // ToolCallResult arrives. Trade-off:
            // - PRO: zero duplication; children "trickle in" as they
            //   complete, so user sees real progress on slow batches
            //   (4 reads finishing within 1s look near-atomic; a 4-call
            //   batch where 3 are fast + 1 is `cargo check` shows the
            //   slow tail clearly).
            // - PRO: avoids the retained-renderer's "in-place mutation
            //   of older body rows" problem (rows already scrolled into
            //   native terminal scrollback can't be modified).
            // - CON: user doesn't see batch contents until first child
            //   completes. Acceptable: footer spinner conveys "working",
            //   contents become visible immediately on first result.
            // Glyphs: ● (BLACK CIRCLE U+25CF) for batch header,
            // └ (BOX DRAWINGS LIGHT UP AND RIGHT U+2514) for each
            // child row. Picked over ⏺/⎿ because Cascadia Code
            // (Windows VSCode default) renders ⏺ as a flat oval and
            // ⎿ as a backslash-shaped fallback -- both are widely
            // supported monospace glyphs that survive the same fonts
            // where the dental-symbols block tofu's. Aligns with the
            // single-tool-call ● glyph (retained::ToolCall arm) so
            // batched and single calls share one visual anchor, and
            // with `└` for tool-result rows below the call. Both
            // glyphs are in WGL4 (Consolas, NSimSun, Cascadia, Microsoft
            // YaHei all ship them), so no `unicode_symbols` ASCII
            // fallback — matches the single-tool-call hardcoded ● for
            // visual parity between batched and single tool-call paths.
            let head_glyph = "\u{25cf}";
            let child_glyph = "\u{2514}";
            // Build header + child rows; renderer keeps the group
            // "live" while it's the bottom of body_lines, so each
            // ToolCallResult below can update the matching child row
            // in place (CC-style result data light-up).
            //
            // Child format: `⎿ Read(mod.rs)`. Tool name is the short
            // form (Read not ReadFile); detail is wrapped in parens
            // (Tool(arg) reads as a function call, mirroring CC).
            let header_text = format!("{} {}", head_glyph, label);
            // Build child rows with disambiguation: when multiple calls
            // produce the same detail (e.g. 3 × Read(SKILL.md) from
            // different directories), show enough parent path to tell
            // them apart (issue #437).
            let raw_details: Vec<String> = calls
                .iter()
                .map(|c| format_tool_detail(&c.name, &c.arguments))
                .collect();
            let disambiguated = disambiguate_batch_details(
                &calls.iter().map(|c| c.name.as_str()).collect::<Vec<_>>(),
                &calls
                    .iter()
                    .map(|c| c.arguments.as_str())
                    .collect::<Vec<_>>(),
                &raw_details,
            );
            // For todo add calls, prepend batch-sequential task numbers
            // (#1, #2, …) so users can see task ids at a glance in the
            // parallel batch display (issue #697).
            let mut todo_add_counter: usize = 0;
            let final_details: Vec<String> = calls
                .iter()
                .zip(disambiguated.iter())
                .map(|(c, detail)| {
                    // Merged `todowrite` carries `{action}` too (legacy `todo` still recognized).
                    if c.name == "todo" || c.name == "todowrite" {
                        // Parse the action from arguments JSON rather than
                        // string-matching, because model-generated JSON may
                        // contain whitespace around colons/commas.
                        let action = serde_json::from_str::<serde_json::Value>(&c.arguments)
                            .ok()
                            .and_then(|v| {
                                v.get("action").and_then(|a| a.as_str()).map(str::to_string)
                            });
                        match action.as_deref() {
                            Some("add") => {
                                todo_add_counter += 1;
                                return format!("#{} {}", todo_add_counter, detail);
                            }
                            // Upgrade `#4 → completed` to `#4 Write tests →
                            // completed` using the title learned from earlier
                            // todo results (issue: parallel updates showed no
                            // task name).
                            Some("update") => {
                                return enrich_todo_detail(
                                    &c.name,
                                    &c.arguments,
                                    detail,
                                    &state.todo_titles,
                                );
                            }
                            _ => {}
                        }
                    }
                    detail.clone()
                })
                .collect();
            let children: Vec<crate::render::ToolGroupChild> = calls
                .iter()
                .zip(final_details.iter())
                .map(|(c, detail)| crate::render::ToolGroupChild {
                    call_id: c.id.clone(),
                    text: format!(
                        "  {} {}({})",
                        child_glyph,
                        display_tool_name_short(&c.name),
                        detail
                    ),
                })
                .collect();
            renderer.render(UiLine::AssistantLineBreak);
            renderer.render(UiLine::ToolGroupRender {
                batch_id: batch_id.clone(),
                header: header_text,
                children,
            });
            renderer.flush();

            let call_ids: Vec<String> = calls.iter().map(|c| c.id.clone()).collect();
            for cid in &call_ids {
                state.call_id_to_batch.insert(cid.clone(), batch_id.clone());
            }
            // Pre-populate `pending_tools` with the final (potentially
            // todo-numbered) detail so that subsequent ToolCallStarted /
            // ApprovalNeeded events use the disambiguated / numbered
            // path (e.g. "a/SKILL.md", "#1 创建demo3") instead of the
            // raw basename ("SKILL.md", "创建demo3"). Without this,
            // parallel batch approvals show identical "ReadFile(SKILL.md)"
            // prompts and the user can't tell which file they're
            // approving (issue #439 / #697).
            for (c, detail) in calls.iter().zip(final_details.iter()) {
                pending_tools.insert(
                    c.id.clone(),
                    (display_tool_name_short(&c.name), detail.clone(), true),
                );
            }
            state.active_tool_batches.insert(
                batch_id.clone(),
                crate::state::ActiveToolBatch {
                    call_ids,
                    edit_displays: std::collections::HashMap::new(),
                },
            );
            // Anchor the spinner clock to the batch start. The interleaved
            // per-tool events that follow won't reset it (they no-op the reset
            // while a batch is active), so the elapsed-ms ticks steadily instead
            // of flickering 0→N→0.
            state.on_tool_batch_started();
        }
        AgentEvent::GoalUpdate {
            active,
            terminal,
            phase,
            round,
            condition,
            last_reason,
            ..
        } => {
            if active {
                // Whether the badge was ALREADY a live Pursuing goal before this
                // update — captured before we overwrite goal_phase below. `goal_phase`
                // defaults to Pursuing with no condition, so require goal_condition too.
                let entering_from_pursuing = state.goal_phase
                    == atomcode_coding::GoalPhase::Pursuing
                    && state.goal_condition.is_some();
                // Pursuing: update live badge state.
                state.goal_condition = Some(condition);
                state.goal_round = round;
                state.goal_phase = atomcode_coding::GoalPhase::Pursuing;
                // Reset the elapsed clock only when (re-)entering Pursuing from a
                // non-Pursuing state (fresh /goal, or re-engaging a Satisfied/PausedAtCap
                // goal) so the badge reads `round 1 · <fresh time>` — NOT on mid-Pursuing
                // updates that also carry round==0 (e.g. AdjustGoalRounds), which would
                // otherwise rewind a fresh goal's clock mid-first-turn.
                if goal_clock_should_reset(entering_from_pursuing, state.goal_started_at.is_none())
                {
                    state.goal_started_at = Some(std::time::Instant::now());
                }
            } else {
                match phase {
                    atomcode_coding::GoalPhase::Satisfied => {
                        // Goal met: render the banner once, but KEEP the badge
                        // visible so the user sees it was achieved.
                        if state.goal_condition.is_some() {
                            if let Some(reason) = last_reason.as_deref() {
                                renderer.render(UiLine::CommandOutput(format!(
                                    "  ✓ Goal met: {reason}\n"
                                )));
                                renderer.flush();
                            }
                        }
                        state.goal_phase = atomcode_coding::GoalPhase::Satisfied;
                        flush_pending_separator(state, renderer, /* as_goal_end */ true);
                    }
                    atomcode_coding::GoalPhase::PausedAtCap => {
                        // Round/time cap reached: render a paused note once using
                        // the authoritative last_reason set by pause_at_cap() so the
                        // scrollback banner, ControllerWarning, and badge stay
                        // consistent (mirrors Satisfied/Ended arms' pattern).
                        // KEEP the badge — it will resume on the next Submit.
                        if state.goal_condition.is_some() {
                            if let Some(reason) = last_reason.as_deref() {
                                renderer.render(UiLine::CommandOutput(format!(
                                    "  ⏸ Goal stopped: {reason}\n"
                                )));
                                renderer.flush();
                            }
                        }
                        state.goal_phase = atomcode_coding::GoalPhase::PausedAtCap;
                        flush_pending_separator(state, renderer, /* as_goal_end */ true);
                    }
                    atomcode_coding::GoalPhase::Paused => {
                        if state.goal_condition.is_some() {
                            renderer.render(UiLine::CommandOutput(
                                "  ⏸ Goal paused; continue the conversation to resume, or use /goal stop to end.\n".into(),
                            ));
                            renderer.flush();
                        }
                        state.goal_phase = atomcode_coding::GoalPhase::Paused;
                        flush_pending_separator(state, renderer, /* as_goal_end */ true);
                    }
                    atomcode_coding::GoalPhase::Ended
                    // Pursuing with active==false is unreachable by invariant
                    // (active == (phase == Pursuing)), but listed here to keep
                    // the match exhaustive and prevent silent falls-through if a
                    // future phase variant is added.
                    | atomcode_coding::GoalPhase::Pursuing => {
                        // Ended (cancel / fail / clear / supersede): render a
                        // verdict banner (if applicable) then tear down the badge.
                        // Render order: banner ABOVE the stats separator so the
                        // user reads top-down: assistant output → verdict → ─── line.
                        if state.goal_condition.is_some() {
                            if let Some(reason) = last_reason.as_deref() {
                                let banner =
                                    if terminal == Some(atomcode_coding::GoalTerminal::Cancelled) {
                                        // Cancel already gets its own UiLine via
                                        // TurnCancelled — skip to avoid double banner.
                                        None
                                    } else if goal_terminal_is_met(terminal) {
                                        Some(format!("  ✓ Goal met: {reason}\n"))
                                    } else {
                                        Some(format!("  ⚠ Goal stopped: {reason}\n"))
                                    };
                                if let Some(line) = banner {
                                    renderer.render(UiLine::CommandOutput(line));
                                    renderer.flush();
                                }
                            }
                        }
                        state.goal_condition = None;
                        state.goal_armed = false;
                        state.goal_round = 0;
                        state.goal_started_at = None;
                        // Reflect the true terminal state (not a lying "Pursuing").
                        // The next goal's active=true update resets this to Pursuing;
                        // `goal_defers_turn_separator` gates on goal_condition first, so
                        // this only guards future readers of goal_phase.
                        state.goal_phase = atomcode_coding::GoalPhase::Ended;
                        flush_pending_separator(state, renderer, /* as_goal_end */ true);
                    }
                }
            }
        }
        AgentEvent::LoopUpdate {
            active,
            round,
            label,
            last_reason,
            ..
        } => {
            if active {
                state.loop_label = Some(label);
                state.loop_round = round;
                if state.loop_started_at.is_none() {
                    state.loop_started_at = Some(std::time::Instant::now());
                }
            } else {
                if state.loop_label.is_some() {
                    if let Some(reason) = last_reason.as_deref() {
                        let silent =
                            reason.contains("cancelled") || reason.contains("cleared by user");
                        if !silent {
                            renderer.render(UiLine::CommandOutput(
                                crate::i18n::t(crate::i18n::Msg::LoopEnded { reason }).into_owned(),
                            ));
                            renderer.flush();
                        }
                    }
                }
                state.loop_label = None;
                state.loop_round = 0;
                state.loop_started_at = None;
                // Flush any buffered separator as a bare stats line — the
                // loop-end banner above already conveyed what happened, the
                // separator just visually closes the last turn.
                flush_pending_separator(state, renderer, /* as_goal_end */ true);
            }
        }
        AgentEvent::ToolBatchCompleted {
            batch_id,
            ok: _,
            total: _,
            elapsed_ms: _,
        } => {
            // CC-style: NO standalone batch-summary row. Each child
            // row already shows its own `→ N lines` / `→ ✗`, so an
            // aggregate `batch 4/4 ok · Xs wall` line would just be
            // visual noise repeating what's already visible above.
            //
            // SubAgentDispatchEnd (different code path) STILL emits
            // its `▸ ParallelEditFiles · ...` summary because sub-agent
            // turns/elapsed per-task is hidden by Task 3's collapse —
            // that summary is the only place the user can see how
            // long it took.
            //
            // Just clear batch state so subsequent per-call events
            // fall back to the standard single-tool render path.
            if let Some(mut b) = state.active_tool_batches.remove(&batch_id) {
                for cid in &b.call_ids {
                    state.call_id_to_batch.remove(cid);
                }
                // Appending permanent diff rows while the group is live would
                // freeze it and make later child updates disappear. Completion
                // is the first safe point: every child is terminal, so render
                // cached edit results now in the model's original call order.
                for cid in b.call_ids {
                    let Some(display) = b.edit_displays.remove(&cid) else {
                        continue;
                    };
                    renderer.render(UiLine::ToolResult {
                        success: true,
                        summary: display.summary,
                        diff_stats: Some(display.diff_stats),
                    });
                    renderer.render(UiLine::EditDiffBlock(display.entries));
                }
                renderer.flush();
            }
        }
        AgentEvent::SubAgentDispatchStart { tasks } => {
            // Header line: announce the dispatch. The model gets this
            // same fact in the ToolResult; the UI line tells the user
            // "the wait is intentional, not a hang". Per-task running/
            // done lines are suppressed (Task 3 — CC alignment); the
            // footer spinner conveys mid-flight progress, the
            // DispatchEnd summary lands the final count.
            renderer.render(UiLine::CommandOutput(format!(
                "Dispatching {} sub-agents in parallel...",
                tasks.len()
            )));
            renderer.flush();
            state.on_sub_agent_dispatch_start(tasks);
        }
        AgentEvent::SubAgentTaskStarted { index: _ } => {
            // Per-task running lines suppressed for CC-style collapsed
            // view. State tracking still happens via DispatchStart's
            // task list. Nothing to render here.
        }
        AgentEvent::SubAgentTaskDone {
            index: _,
            elapsed_ms: _,
            turns: _,
            summary: _,
        } => {
            // Per-task done lines suppressed — final count shows in
            // DispatchEnd summary. Still tick the counter so the
            // aggregate `N/M ok` reflects this completion.
            state.on_sub_agent_task_done();
        }
        AgentEvent::SubAgentTaskFailed {
            index,
            elapsed_ms,
            turns: _,
            reason,
        } => {
            // Failures KEEP their per-task line. Rationale: the user
            // needs to know which sub-agent failed for diagnosis;
            // collapsing into "1 fail" leaves them blind. Successes
            // collapse silently (no actionable info per success).
            state.on_sub_agent_task_failed();
            if let Some(info) = state.sub_agent_tasks.get(index) {
                let cross = "\u{2717}";
                let short_reason = reason.lines().next().unwrap_or("").trim();
                renderer.render(UiLine::CommandOutput(format!(
                    "  {} {}{} — {} · {}",
                    cross,
                    info.path,
                    info.dedup_suffix,
                    fmt_elapsed(elapsed_ms),
                    if short_reason.is_empty() {
                        "failed"
                    } else {
                        short_reason
                    }
                )));
                renderer.flush();
            }
        }
        AgentEvent::SubAgentDispatchEnd => {
            // Compute the aggregate before clearing state. This is the
            // single line that replaces the old multi-row pipe-table
            // result block — the model still sees the full breakdown
            // in the ToolResult content, but the UI only needs the
            // bottom line.
            let total = state.sub_agent_total;
            let failed = state.sub_agent_failed;
            let ok = total.saturating_sub(failed);
            let elapsed = state
                .sub_agent_started_at
                .map(|t| t.elapsed().as_millis() as u64)
                .unwrap_or(0);
            if total > 0 {
                let arrow = "\u{25cf}";
                let summary = if failed == 0 {
                    format!(
                        "{} ParallelEditFiles · {}/{} ok · {} wall",
                        arrow,
                        ok,
                        total,
                        fmt_elapsed(elapsed)
                    )
                } else {
                    format!(
                        "{} ParallelEditFiles · {} ok · {} fail · {} wall",
                        arrow,
                        ok,
                        failed,
                        fmt_elapsed(elapsed)
                    )
                };
                renderer.render(UiLine::ToolGroupSummary { text: summary });
                renderer.flush();
            }
            state.on_sub_agent_dispatch_end();
        }
        AgentEvent::MessagesSync { snapshot } => {
            // Persist an explicitly synchronized presentation snapshot so /bg can
            // recover the conversation state. A correlated native restore has its
            // own completion event; ignore a stale generic sync while that handoff
            // owns the session boundary.
            // A kernel snapshot carries cold-summary synthetics inline in
            // `messages`, so a non-empty `messages` is the only presence check.
            if !snapshot.messages.is_empty() {
                apply_session_snapshot(&mut ctx.current_session, snapshot);
                ctx.bg_manager
                    .set_foreground_session(ctx.current_session.clone(), ctx.working_dir.clone());
            }
        }
        AgentEvent::ConversationRestored { .. } | AgentEvent::ConversationRestoreFailed { .. } => {}
        AgentEvent::UserEcho(text) => {
            let markers = image_markers_in_order(&text);
            renderer.render(UiLine::UserWithAttachments {
                text,
                attachments: markers,
            });
            renderer.flush();
        }
        AgentEvent::SharedRequestResolved { request_id, kind } => {
            // The live hub publishes this only after the runtime accepted a peer's
            // response. Correlate by id so a delayed terminal from an older prompt
            // cannot dismiss a newer request already displayed by this TUI.
            if ctx.pending_runtime_request_id != Some(request_id) {
                return;
            }
            ctx.pending_runtime_request_id = None;
            if kind == atomcode_capabilities::tools::request_user_input::REQUEST_USER_INPUT_KIND {
                state.on_user_input_resolved();
                redraw_idle_plain(buf, state, ctx, renderer);
            } else if kind == atomcode_capabilities::tools::APPROVAL_KIND {
                state.on_approval_resolved();
                redraw_idle_plain(buf, state, ctx, renderer);
            }
        }
        AgentEvent::PeerBusy(running) => {
            // Live-sync: mirror the peer's busy state so TUI input is
            // visually disabled while the other side's turn is running.
            if running {
                state.on_submit();
            } else {
                // 对端轮次结束:把流式累积的助手行收尾落地(等价本地 TurnComplete
                // 的第一步 AssistantLineBreak),否则短回复(如"在的!")一直挂在
                // 流式当前行不提交,要等下一轮才一起刷出 —— sync 模式下的空助手气泡
                // bug。同时 reset think-stripper,避免上一轮残留吞掉下一轮文本。
                complete_peer_turn_presentation(state, renderer, think);
            }
        }
        AgentEvent::ProviderChanged(provider) => {
            // Live-sync: another view (webui dropdown) switched the model —
            // mirror the already-committed runtime state into the TUI without
            // persisting it as the shared default. Sending another reload here
            // would create an untracked second transition and break single-flight
            // ordering.
            if let Some(generation) = ctx.runtime.current_generation() {
                stage_provider_projection(ctx, generation, provider, None);
                if ctx.pending_provider_reload.is_none()
                    && retry_pending_provider_projection(ctx, state, renderer)
                {
                    renderer.flush();
                }
            }
        }
        AgentEvent::ModeChanged { plan, bypass } => {
            let mode = if bypass {
                crate::state::AgentMode::Auto
            } else if plan {
                crate::state::AgentMode::Plan
            } else {
                crate::state::AgentMode::Build
            };
            state.agent_mode = mode;
            if mode == crate::state::AgentMode::Build {
                state.build_badge_visible = true;
            }
            let _ = ctx
                .runtime
                .dispatch(atomcode_coding::DriverCommand::SetMode(runtime_mode(mode)));
            renderer.render(UiLine::CommandOutput(format!(
                "  Switched to {} mode.\n",
                mode.label()
            )));
            renderer.flush();
        }
        AgentEvent::SessionRenamed { name } => {
            // AI session-namer renamed the active session (fire-and-forget after
            // the first turn, or mirrored from a daemon session). Apply only if
            // the session is still auto-named and the user hasn't renamed it —
            // never clobber an explicit `/rename`. The next loop iteration's
            // `sync_terminal_title` picks up the new name for the tab title.
            crate::tuix_trace!("TUI", "SessionRenamed: name={}", name);
            apply_ai_session_name(ctx, name, renderer);
        }
        AgentEvent::RateLimited {
            reset_at_display,
            reset_label,
            secs_until_reset,
            auto_resuming,
            server_message,
        } => {
            // Non-error pause line: dim/plain body row, never red.
            // auto_resuming=true (WaitAndRetry): "⏳ 限流，Ns 后自动继续…"
            // auto_resuming=false + CodingPlan window data (reset time and/or label):
            //   "⏸ 5小时窗口已用尽，约 HH:MM 恢复…" / "…稍后恢复…"
            // auto_resuming=false + NO window data (external-model / generic 429):
            //   "⏸ 限流（HTTP 429）[：<provider reason>]…" — not a CodingPlan quota.
            // UiLine::Muted: theme-aware muted gray (legible on dark AND light),
            // no forced prefix, non-bold. Rate-limit is a pause, not an
            // error/warning — it must not render with the yellow `! ` prefix
            // that Warning applies.
            let line = format_rate_limited_line(
                &reset_at_display,
                &reset_label,
                secs_until_reset,
                auto_resuming,
                server_message.as_deref(),
            );
            // A `Pause` (auto_resuming=false) ENDS the turn with
            // `StopReason::RateLimited` → the errored `✗ 已中断` summary. Bind the
            // pause reason to that summary too (same rationale as the Error arm),
            // so a 429 the user can't act on still shows WHY. A WaitAndRetry
            // (auto_resuming=true) is not terminal — the turn continues — so it
            // must NOT be captured as a turn-ending reason.
            if !auto_resuming {
                state.last_turn_error = Some(line.clone());
                // The pause reason is now visible in the muted line rendered just
                // below, so the errored summary won't fold it a second time.
                state.turn_error_line_shown = true;
            }
            renderer.render(UiLine::Muted(line));
            renderer.flush();
        }
        AgentEvent::Steered { count: _, inputs } => {
            let confirmed = state.on_steered(&inputs);
            if ctx.live_binding.is_none() {
                for pending in confirmed {
                    renderer.render(UiLine::UserWithAttachments {
                        text: pending.message.text,
                        attachments: pending.message.image_markers,
                    });
                }
                renderer.flush();
            }
        }
    }
}

/// Apply an AI-generated session name if the session is still auto-named and
/// not user-renamed. Saves directly (NOT via `apply_session_snapshot`, which
/// would re-truncate the name). Auto-name semantics: does NOT set
/// `user_renamed`, so a later explicit `/rename` still wins.
fn apply_ai_session_name(ctx: &mut LoopCtx, name: String, renderer: &mut dyn Renderer) {
    if !atomcode_coding::session_title::should_accept_ai_name(
        ctx.current_session.user_renamed,
        ctx.current_session.ai_named,
    ) {
        return;
    }
    let project_bucket = commands::active_session_project_bucket(&ctx.working_dir);
    match atomcode_daemon::legacy_convert::apply_ai_catalog_name_in_project(
        &project_bucket,
        ctx.current_session.id.as_str(),
        &name,
    ) {
        Ok(true) => {}
        Ok(false) => return,
        Err(e) => {
            renderer.render(UiLine::Error(format!("session save failed: {e}")));
            renderer.flush();
            return;
        }
    }
    ctx.current_session.name = name;
    ctx.current_session.ai_named = true;
    ctx.current_session.touch();
    ctx.bg_manager
        .set_foreground_session(ctx.current_session.clone(), ctx.working_dir.clone());
}

/// Keep the transitional UI projection in sync. Durable persistence belongs to
/// the native runtime hooks; this function must never write core JSON.
fn persist_current_session(
    ctx: &mut LoopCtx,
    snapshot: atomcode_kernel::message::SessionSnapshot,
    renderer: &mut dyn Renderer,
) -> bool {
    // Cold summaries live inline as synthetics in a kernel snapshot, so an empty
    // `messages` is the empty-working-set signal.
    if snapshot.messages.is_empty() {
        return true;
    }
    apply_session_snapshot(&mut ctx.current_session, snapshot);
    ctx.bg_manager
        .set_foreground_session(ctx.current_session.clone(), ctx.working_dir.clone());
    let _ = renderer;
    true
}

pub(crate) fn apply_session_snapshot(
    session: &mut crate::session::Session,
    snapshot: atomcode_kernel::message::SessionSnapshot,
) {
    // A kernel snapshot carries cold-summary synthetics INLINE in `messages`, so
    // an empty `messages` is the empty-working-set signal (the old core snapshot
    // split cold_summaries out into a separate field, hence the two-part check).
    if snapshot.messages.is_empty() {
        return;
    }
    session.update_from_conversation_snapshot(snapshot);
    session.touch();
    // Triggers for renaming:
    //   * `default` / `session-<ts>` — never renamed yet
    //   * leading `[` — previous rename grabbed a synthetic system-meta
    //     marker (`[System meta · not a user message]`,
    //     `[You are stuck — ...]`, etc.) that the agent injects as a
    //     Role::User message for plumbing reasons. Re-derive from the
    //     next non-synthetic user turn so the /resume picker stops
    //     showing those as session titles.
    //   * `user_renamed` — if the user explicitly renamed (via /rename),
    //     never auto-name, regardless of name format.
    let should_rename = !session.user_renamed
        && (session.name == "default"
            || session.name.starts_with("session-")
            || session.name.trim_start().starts_with('['));
    if should_rename {
        use atomcode_kernel::message::Role;
        // Primary signal: `Message.synthetic` field (accurate for sessions
        // saved after the field landed). Secondary signal: bracket-prefix
        // legacy heuristic for sessions saved before the field existed
        // and so default-loaded as `synthetic = false`.
        let first_real_user = session
            .messages
            .iter()
            .filter(|m| matches!(m.role, Role::User) && !m.synthetic)
            .map(|m| m.text.as_str())
            .find(|t| !is_synthetic_user_text(t));
        if let Some(text) = first_real_user {
            let name: String = text.lines().next().unwrap_or("").chars().take(40).collect();
            if !name.is_empty() {
                session.name = name;
            }
        }
        // Else: leave the existing default/session-<ts>/[...]-marker
        // name. Better to keep a generic placeholder than to commit to
        // a synthetic injection as the title.
    }
}

/// True when `text` looks like a synthetic user-channel injection
/// (atomcode plumbs system-meta control signals through `add_user_message`
/// and tags them with a leading `[...]` bracket marker on the first line:
/// `[System meta · not a user message]`, `[You are stuck — ...]`, etc.).
/// Used by session naming to skip these so `/resume` titles stay
/// human-meaningful.
fn is_synthetic_user_text(text: &str) -> bool {
    text.trim_start().starts_with('[')
}

#[cfg(test)]
mod session_naming_tests {
    use super::{apply_session_snapshot, is_synthetic_user_text};
    use crate::session::Session;
    use atomcode_kernel::message::{Message, Role, SessionSnapshot};

    fn user_msg(role: Role, text: &str) -> Message {
        let mut m = Message::user(text);
        m.role = role;
        m
    }

    /// Build a kernel snapshot whose messages carry cold-summary synthetics
    /// INLINE (mirrors `snapshot_to_kernel`), matching what the runtime emits.
    fn snapshot(cold_summaries: &[&str], messages: Vec<Message>) -> SessionSnapshot {
        use atomcode_kernel::message::{LEGACY_COLD_SUMMARY_ORIGIN, LEGACY_COLD_SUMMARY_PREFIX};
        let mut all = Vec::new();
        for summary in cold_summaries {
            let mut m = Message::user(format!("{LEGACY_COLD_SUMMARY_PREFIX}{summary}"));
            m.synthetic = true;
            m.internal_origin = Some(LEGACY_COLD_SUMMARY_ORIGIN.to_string());
            all.push(m);
        }
        all.extend(messages);
        SessionSnapshot::new(all)
    }

    #[test]
    fn apply_session_snapshot_renames_from_first_real_user() {
        let mut session = Session::default_session(std::path::PathBuf::from("/tmp/project"));
        let messages = vec![
            user_msg(Role::User, "[System meta · not a user message]\nread this"),
            user_msg(Role::User, "implement background sessions\nwith tests"),
        ];

        apply_session_snapshot(&mut session, snapshot(&[], messages));

        assert_eq!(session.name, "implement background sessions");
        assert_eq!(session.messages.len(), 2);
    }

    #[test]
    fn apply_session_snapshot_preserves_custom_name() {
        let mut session = Session::default_session(std::path::PathBuf::from("/tmp/project"));
        session.name = "manual name".to_string();

        apply_session_snapshot(
            &mut session,
            snapshot(&[], vec![user_msg(Role::User, "new task")]),
        );

        assert_eq!(session.name, "manual name");
    }

    #[test]
    fn apply_session_snapshot_preserves_cold_summaries() {
        let mut session = Session::default_session(std::path::PathBuf::from("/tmp/project"));

        apply_session_snapshot(
            &mut session,
            snapshot(
                &["compressed context"],
                vec![user_msg(Role::User, "new task")],
            ),
        );

        assert_eq!(session.cold_summaries, vec!["compressed context"]);
    }

    #[test]
    fn apply_session_snapshot_accepts_a_cold_only_working_set() {
        let mut session = Session::default_session(std::path::PathBuf::from("/tmp/project"));
        session.messages = vec![user_msg(Role::User, "stale recent turn")];

        apply_session_snapshot(
            &mut session,
            snapshot(&["all retained context"], Vec::new()),
        );

        assert!(session.messages.is_empty());
        assert_eq!(session.cold_summaries, vec!["all retained context"]);
    }

    #[test]
    fn synthetic_system_meta_is_detected() {
        assert!(is_synthetic_user_text(
            "[System meta · not a user message]\n12 calls..."
        ));
    }

    #[test]
    fn synthetic_stuck_warning_is_detected() {
        assert!(is_synthetic_user_text(
            "[You are stuck — read foo.rs repeatedly without making progress.]"
        ));
    }

    #[test]
    fn leading_whitespace_does_not_hide_synthetic_marker() {
        assert!(is_synthetic_user_text("   [System meta] body"));
    }

    #[test]
    fn real_user_message_is_not_synthetic() {
        assert!(!is_synthetic_user_text("Fix the auth bug in login.rs"));
        assert!(!is_synthetic_user_text("Continue."));
        assert!(!is_synthetic_user_text("(why does this break?)"));
    }

    #[test]
    fn ai_rename_applies_unless_user_renamed_or_already_ai_named() {
        use atomcode_coding::session_title::should_accept_ai_name;
        // Not user-renamed and not yet AI-named → accept (the AI title wins
        // over the first-turn truncation the auto-namer set).
        assert!(should_accept_ai_name(false, false));
        // A deliberate /rename is never overwritten.
        assert!(!should_accept_ai_name(true, false));
        // Already AI-named → don't re-name on reconnect/resume.
        assert!(!should_accept_ai_name(false, true));
    }
}

/// Build the persistent status line shown directly below the input box.
/// Pulls model name from ctx, cwd from ctx.working_dir (with $HOME
/// collapsed to `~`), and running token count from state.
/// Probe the system clipboard for an image, memoising the result inside
/// the supplied cache for `CLIPBOARD_HINT_TTL_MS`. `build_status` calls
/// this on every redraw, so without caching every spinner tick (~12/s
/// during streaming) would round-trip to the platform clipboard API.
const CLIPBOARD_HINT_TTL_MS: u64 = 1500;
const CLIPBOARD_HINT_DISPLAY_SECS: u64 = 6;

fn observe_clipboard_image(
    state: &mut ClipboardCheckState,
    image_hash: Option<u64>,
    now: std::time::Instant,
) {
    if state.image_hash == image_hash {
        return;
    }
    state.image_hash = image_hash;
    state.hint_hash = image_hash;
    state.hint_deadline =
        image_hash.map(|_| now + std::time::Duration::from_secs(CLIPBOARD_HINT_DISPLAY_SECS));
}

fn apply_clipboard_observation(
    state: &mut ClipboardCheckState,
    observation: Result<Option<u64>, ()>,
    now: std::time::Instant,
) {
    if let Ok(image_hash) = observation {
        observe_clipboard_image(state, image_hash, now);
    }
}

fn active_clipboard_hint(
    state: &mut ClipboardCheckState,
    pending_image_hashes: &[u64],
    now: std::time::Instant,
) -> Option<u64> {
    let hash = state.hint_hash?;
    if pending_image_hashes.contains(&hash)
        || state.hint_deadline.is_none_or(|deadline| now >= deadline)
    {
        state.hint_hash = None;
        state.hint_deadline = None;
        return None;
    }
    Some(hash)
}

fn publish_clipboard_hint(state: &mut ClipboardCheckState, hint_hash: Option<u64>) -> bool {
    let changed = state.published_hint_hash != hint_hash;
    state.published_hint_hash = hint_hash;
    changed
}

fn clipboard_image_hint_state(
    cache: &std::sync::Mutex<ClipboardCheckState>,
    pending_image_hashes: &[u64],
    probe_clipboard: bool,
) -> (Option<u64>, bool) {
    let mut state = cache.lock().unwrap_or_else(|e| e.into_inner());
    let now = std::time::Instant::now();
    let stale = state
        .last_checked
        .map(|t| t.elapsed() >= std::time::Duration::from_millis(CLIPBOARD_HINT_TTL_MS))
        .unwrap_or(true);
    if probe_clipboard && stale {
        let observation = match arboard::Clipboard::new() {
            Ok(mut clipboard) => match clipboard.get_image() {
                Ok(img) => Ok(Some(rgba_fingerprint(
                    img.width,
                    img.height,
                    img.bytes.as_ref(),
                ))),
                Err(arboard::Error::ContentNotAvailable) => Ok(None),
                Err(_) => Err(()),
            },
            Err(_) => Err(()),
        };
        apply_clipboard_observation(&mut state, observation, now);
        state.last_checked = Some(now);
    }
    let hint_hash = active_clipboard_hint(&mut state, pending_image_hashes, now);
    let changed = publish_clipboard_hint(&mut state, hint_hash);
    (hint_hash, changed)
}

fn clipboard_image_hint_hash(
    cache: &std::sync::Mutex<ClipboardCheckState>,
    pending_image_hashes: &[u64],
) -> Option<u64> {
    clipboard_image_hint_state(cache, pending_image_hashes, true).0
}

fn clipboard_image_hint_changed(
    cache: &std::sync::Mutex<ClipboardCheckState>,
    pending_image_hashes: &[u64],
) -> bool {
    // The idle tick exists to repaint an expired/consumed hint, not to copy
    // potentially tens of MB of RGBA clipboard data in the background.
    clipboard_image_hint_state(cache, pending_image_hashes, false).1
}

#[cfg(test)]
mod clipboard_hint_tests {
    use super::{
        active_clipboard_hint, apply_clipboard_observation, observe_clipboard_image,
        publish_clipboard_hint, rgba_fingerprint, ClipboardCheckState,
    };
    use std::time::{Duration, Instant};

    #[test]
    fn image_hint_is_one_shot_until_clipboard_content_changes() {
        let now = Instant::now();
        let mut state = ClipboardCheckState::default();

        observe_clipboard_image(&mut state, Some(7), now);
        assert_eq!(active_clipboard_hint(&mut state, &[], now), Some(7));
        assert_eq!(
            active_clipboard_hint(&mut state, &[], now + Duration::from_secs(7)),
            None
        );

        // The same image staying in the clipboard must not restart the hint.
        observe_clipboard_image(&mut state, Some(7), now + Duration::from_secs(8));
        assert_eq!(
            active_clipboard_hint(&mut state, &[], now + Duration::from_secs(8)),
            None
        );

        // A different image is a new clipboard event and gets its own window.
        observe_clipboard_image(&mut state, Some(8), now + Duration::from_secs(9));
        assert_eq!(
            active_clipboard_hint(&mut state, &[], now + Duration::from_secs(9)),
            Some(8)
        );
    }

    #[test]
    fn attaching_or_clearing_the_image_consumes_and_rearms_the_hint() {
        let now = Instant::now();
        let mut state = ClipboardCheckState::default();

        observe_clipboard_image(&mut state, Some(7), now);
        assert_eq!(active_clipboard_hint(&mut state, &[7], now), None);

        observe_clipboard_image(&mut state, None, now + Duration::from_secs(1));
        observe_clipboard_image(&mut state, Some(7), now + Duration::from_secs(2));
        assert_eq!(
            active_clipboard_hint(&mut state, &[], now + Duration::from_secs(2)),
            Some(7)
        );
    }

    #[test]
    fn transient_probe_failure_preserves_the_consumed_image_state() {
        let now = Instant::now();
        let mut state = ClipboardCheckState::default();

        apply_clipboard_observation(&mut state, Ok(Some(7)), now);
        assert_eq!(
            active_clipboard_hint(&mut state, &[], now + Duration::from_secs(7)),
            None
        );
        apply_clipboard_observation(&mut state, Err(()), now + Duration::from_secs(8));
        apply_clipboard_observation(&mut state, Ok(Some(7)), now + Duration::from_secs(9));

        assert_eq!(
            active_clipboard_hint(&mut state, &[], now + Duration::from_secs(9)),
            None,
            "a temporary ClipboardOccupied-style failure must not rearm the same image"
        );
    }

    #[test]
    fn fingerprint_samples_changes_between_matching_head_and_tail() {
        let mut first = vec![0u8; 16 * 1024];
        let mut second = first.clone();
        first[7 * 1024..9 * 1024].fill(1);
        second[7 * 1024..9 * 1024].fill(2);

        assert_ne!(
            rgba_fingerprint(64, 64, &first),
            rgba_fingerprint(64, 64, &second)
        );
    }

    #[test]
    fn published_hint_transitions_request_one_show_and_one_hide_redraw() {
        let mut state = ClipboardCheckState::default();

        assert!(publish_clipboard_hint(&mut state, Some(7)));
        assert!(!publish_clipboard_hint(&mut state, Some(7)));
        assert!(publish_clipboard_hint(&mut state, None));
        assert!(!publish_clipboard_hint(&mut state, None));
    }
}

fn status_context_usage(
    state: &UiState,
    configured_window: usize,
    provider_available: bool,
) -> (usize, usize) {
    if !provider_available {
        return (0, 0);
    }
    match state.last_context.as_ref() {
        Some(snap) => (
            snap.sent_tokens,
            if snap.ctx_window > 0 {
                snap.ctx_window
            } else {
                configured_window
            },
        ),
        None => (0, configured_window),
    }
}

/// Whether the footer should present the foreground as having no configured
/// provider.
///
/// Configuration has two supported schemas: legacy `[providers.*]` and native
/// `[provider_accounts.*]` + `[models.*]`. Checking `config.providers` directly
/// only sees the legacy half and makes a perfectly usable native model appear
/// as "(未配置)" whenever no CodingPlan auth is stored. Route through the same
/// active-provider resolution boundary used to build the runtime instead.
fn status_provider_unconfigured(
    unavailable_reason: Option<atomcode_coding::ProviderUnavailableReason>,
    config: &Config,
    has_stored_auth: bool,
) -> bool {
    match unavailable_reason {
        Some(atomcode_coding::ProviderUnavailableReason::NotConfigured) => true,
        Some(
            atomcode_coding::ProviderUnavailableReason::AuthenticationRequired
            | atomcode_coding::ProviderUnavailableReason::UnsupportedBuild,
        ) => false,
        None => config.active_provider(None).is_err() && !has_stored_auth,
    }
}

#[cfg(test)]
mod status_context_usage_tests {
    use super::{status_context_usage, status_provider_unconfigured};
    use crate::state::{ContextSnapshot, UiState};
    use atomcode_coding::ProviderUnavailableReason;
    use atomcode_config::Config;

    #[test]
    fn configured_model_window_fills_narrow_usage_snapshot() {
        let mut state = UiState::new();
        state.last_context = Some(ContextSnapshot {
            sent_tokens: 22_800,
            ctx_window: 0,
            ..ContextSnapshot::default()
        });

        assert_eq!(
            status_context_usage(&state, 128_000, true),
            (22_800, 128_000)
        );
    }

    #[test]
    fn authoritative_context_window_wins_over_config_fallback() {
        let mut state = UiState::new();
        state.last_context = Some(ContextSnapshot {
            sent_tokens: 22_800,
            ctx_window: 200_000,
            ..ContextSnapshot::default()
        });

        assert_eq!(
            status_context_usage(&state, 128_000, true),
            (22_800, 200_000)
        );
    }

    #[test]
    fn unavailable_provider_does_not_invent_a_context_window() {
        let mut state = UiState::new();
        state.last_context = Some(ContextSnapshot {
            sent_tokens: 22_800,
            ctx_window: 200_000,
            ..ContextSnapshot::default()
        });

        assert_eq!(status_context_usage(&state, 128_000, false), (0, 0));
    }

    #[test]
    fn native_model_configuration_is_not_reported_as_unconfigured() {
        let config: Config = serde_json::from_value(serde_json::json!({
            "default_model": "account/model",
            "provider_accounts": {
                "account": {
                    "provider": "openai",
                    "base_url": "https://api.example.test/v1"
                }
            },
            "models": {
                "account/model": {
                    "account": "account",
                    "model": "example-model",
                    "context_window": 128000
                }
            }
        }))
        .unwrap();

        assert!(config.providers.is_empty(), "legacy table stays empty");
        assert!(!status_provider_unconfigured(None, &config, false));
    }

    #[test]
    fn provider_reason_distinguishes_configuration_from_other_unavailability() {
        let config = Config::default();
        assert!(status_provider_unconfigured(None, &config, false));
        assert!(!status_provider_unconfigured(None, &config, true));
        assert!(status_provider_unconfigured(
            Some(ProviderUnavailableReason::NotConfigured),
            &config,
            true
        ));
        assert!(!status_provider_unconfigured(
            Some(ProviderUnavailableReason::AuthenticationRequired),
            &config,
            false
        ));
        assert!(!status_provider_unconfigured(
            Some(ProviderUnavailableReason::UnsupportedBuild),
            &config,
            false
        ));
    }
}

fn footer_command_output(state: &UiState) -> Option<String> {
    match (
        state.footer_command_output.as_deref(),
        state.footer_persistence_warning.as_deref(),
    ) {
        (None, None) => None,
        (Some(report), None) => Some(report.to_string()),
        (None, Some(warning)) => Some(warning.to_string()),
        (Some(report), Some(warning)) => Some(format!("{report}\n{warning}")),
    }
}

pub(crate) fn build_status(state: &UiState, ctx: &LoopCtx) -> crate::render::StatusLine {
    let cwd = crate::platform::collapse_home(&ctx.working_dir.to_string_lossy());
    // Priority:
    //   1. Provider unavailable at runtime (or absent from config/auth) — show
    //      the configure nudge. This wins over the upgrade hint because the
    //      app literally cannot answer any message; the user needs to know
    //      why before they're told to upgrade.
    //   2. Upgrade-available hint (existing behavior).
    //   3. None.
    let runtime_availability = ctx.runtime.ui_availability();
    let unavailable_reason = ctx.runtime.provider_unavailable_reason();
    let no_provider = status_provider_unconfigured(
        unavailable_reason,
        &ctx.config,
        atomcode_auth::get_stored_auth().is_some(),
    );
    let provider_waiting = matches!(
        runtime_availability,
        RuntimeUiAvailability::AwaitingProvider
    ) && !no_provider;
    let runtime_failed = matches!(runtime_availability, RuntimeUiAvailability::Failed);
    // Open-source build pointed at an AtomGit gateway: any chat will
    // fail-fast with `CpOfficialBuildRequired`. Surface that diagnosis
    // up front (red, beats every other hint) so the user doesn't have
    // to type a message to discover the dead-end — `/login` won't help,
    // only switching to the official build will.
    let active_base_url = ctx
        .config
        .active_provider(None)
        .ok()
        .and_then(|p| p.base_url.clone())
        .unwrap_or_default();
    let needs_official_build = !atomcode_capabilities::provider::signer_available()
        && atomcode_capabilities::provider::is_atomgit_gateway(&active_base_url);
    // Priority: needs-official-build (Warning red) > no-provider (Warning
    // red) > CodingPlan drift monitor (Warning red) > CodingPlan
    // token-usage hint (Info ≥80%, Warning ≥95%) > upgrade banner
    // (Info dim). Usage outranks upgrade because ">80% in this rolling
    // window" is more actionable than "new version available". Only one
    // hint renders at a time (right-aligned on the status row).
    let hint: Option<(String, crate::render::HintSeverity)> = if needs_official_build {
        Some((
            crate::i18n::t(crate::i18n::Msg::StatusOfficialBuildRequired).into_owned(),
            crate::render::HintSeverity::Warning,
        ))
    } else if no_provider {
        Some((
            crate::i18n::t(crate::i18n::Msg::StatusNoProvider).into_owned(),
            crate::render::HintSeverity::Warning,
        ))
    } else if provider_waiting {
        let message = match unavailable_reason {
            Some(atomcode_coding::ProviderUnavailableReason::AuthenticationRequired) => {
                crate::i18n::Msg::CmdWhoamiNotSignedIn
            }
            Some(
                atomcode_coding::ProviderUnavailableReason::UnsupportedBuild
                | atomcode_coding::ProviderUnavailableReason::NotConfigured,
            )
            | None => crate::i18n::Msg::CmdProviderUnavailable,
        };
        Some((
            crate::i18n::t(message).into_owned(),
            crate::render::HintSeverity::Warning,
        ))
    } else if runtime_failed {
        Some((
            crate::i18n::t(crate::i18n::Msg::StatusRuntimeUnavailable).into_owned(),
            crate::render::HintSeverity::Warning,
        ))
    } else if let Some(warning) =
        monitor::is_codingplan_provider(&resolved_provider_and_model(&ctx.config).0)
            .then(|| ctx.monitor_warning.lock().ok().and_then(|g| g.clone()))
            .flatten()
    {
        // Only surface the CodingPlan drift warning while a CodingPlan-managed
        // (AtomGit*) provider is active. A warning set on an AtomGit provider
        // must not linger after the user switches to a custom provider via a
        // path that doesn't clear the slot (e.g. `/provider`) — the hint is
        // meaningless for non-CodingPlan models.
        Some((warning.display_text(), crate::render::HintSeverity::Warning))
    } else if let Some(hook_msg) = ctx.hook_warning_hint.lock().ok().and_then(|g| g.clone()) {
        Some((hook_msg, crate::render::HintSeverity::Warning))
    } else if let Some(usage) =
        usage_monitor::build_usage_hint(&ctx.usage_slot, &ctx.config.default_provider)
    {
        Some(usage)
    } else if let Some(h) =
        clipboard_image_hint_hash(&ctx.clipboard_check, &state.pending_image_hashes)
    {
        // Transient cue — beats the upgrade banner because the action
        // window is "now" (the image is in the clipboard right now).
        // Suppressed when the clipboard's image fingerprint matches one
        // already in `pending_images`: the input box already shows
        // `[Image #N]`, prompting another paste of the same image would
        // just attach a dup. A NEW image (different fingerprint) appears
        // here as a fresh hint so the user can attach it too.
        let _ = h;
        // Windows Terminal / conhost swallow Ctrl+V (they bind it to
        // their own `paste` action that only forwards CF_UNICODETEXT,
        // so an image-only clipboard never reaches the in-app
        // handler). Surface the `/paste` fallback on Windows; macOS /
        // Linux terminals pass Ctrl+V through cleanly, so they keep
        // the snappier keybind hint.
        let hint_msg = if cfg!(target_os = "windows") {
            crate::i18n::Msg::StatusClipboardImageHintSlash
        } else {
            crate::i18n::Msg::StatusClipboardImageHint
        };
        Some((
            crate::i18n::t(hint_msg).into_owned(),
            crate::render::HintSeverity::Info,
        ))
    } else if let Some(v) = ctx.update_hint.lock().ok().and_then(|g| g.clone()) {
        let text = if atomcode_updater::is_package_managed() {
            crate::i18n::t(crate::i18n::Msg::StatusUpgradeHintPm { version: &v }).into_owned()
        } else {
            crate::i18n::t(crate::i18n::Msg::StatusUpgradeHint { version: &v }).into_owned()
        };
        Some((text, crate::render::HintSeverity::Info))
    } else {
        // No lowest-priority fallback: the welcome banner now surfaces the
        // getting-started tips (including /webui), so the footer hint slot stays
        // empty when idle instead of showing a persistent /webui nudge.
        None
    };
    // Pre-configure, `ctx.model_name` is a dummy from the startup fallback
    // (empty string or "not-configured") — showing that raw in the status
    // line reads as a glitch. Replace with an explicit placeholder so the
    // user sees the state, not a rendering artifact.
    let model = if no_provider {
        crate::i18n::t(crate::i18n::Msg::StatusModelNotConfigured).into_owned()
    } else {
        ctx.model_name.clone()
    };
    // Mode badge (`ModeBadge`): a single left-aligned badge that covers all
    // non-default modes. The badge carries both its label and its colour slot
    // (`BadgeColour`), so the renderer just maps the slot to a `CellStyle`.
    // `None` for the default Build startup so the status row stays clean.
    use crate::render::{BadgeColour, ModeBadge};
    let mode_indicator = match state.agent_mode {
        crate::state::AgentMode::Plan => {
            // `⏸ plan` — glyph downgrades to `||` on non-unicode terminals.
            Some(ModeBadge {
                label: if ctx.caps.unicode_symbols {
                    "\u{23f8} plan".to_string()
                } else {
                    "|| plan".to_string()
                },
                colour: BadgeColour::Plan,
            })
        }
        crate::state::AgentMode::AcceptEdits => {
            // `⏵ accept edits` — single play glyph (U+23F5, renders 1-cell text form),
            // downgrades to `>` on non-unicode terminals.
            Some(ModeBadge {
                label: if ctx.caps.unicode_symbols {
                    "\u{23f5} accept edits".to_string()
                } else {
                    "> accept edits".to_string()
                },
                colour: BadgeColour::Mode,
            })
        }
        crate::state::AgentMode::Build if state.build_badge_visible => {
            // `⏸ build` — only shown after the user explicitly switches to
            // Build via Shift+Tab or `/build`; the default startup stays
            // badge-less. Rendered in faint secondary style so it blends
            // into the status row naturally.
            Some(ModeBadge {
                label: if ctx.caps.unicode_symbols {
                    "\u{23f8} build".to_string()
                } else {
                    "|| build".to_string()
                },
                colour: BadgeColour::Secondary,
            })
        }
        // Auto's visual is the warning-colored left badge below (via bypass_indicator).
        crate::state::AgentMode::Build | crate::state::AgentMode::Auto => None,
    };
    // Auto mode badge: a single warning-colored LEFT badge `⏵⏵ auto` (rendered
    // in place of the PLAN badge, since Plan and Auto are mutually exclusive).
    // `--dangerously-skip-permissions` seeds `agent_mode = Auto` at startup, so
    // keying off the mode covers both the startup flag AND the runtime Shift+Tab /
    // `/auto` toggle. The `⏵⏵` glyph downgrades to `>>` on non-unicode terminals.
    let bypass_indicator = if matches!(state.agent_mode, crate::state::AgentMode::Auto) {
        Some(if ctx.caps.unicode_symbols {
            "\u{23f5}\u{23f5} auto".to_string()
        } else {
            ">> auto".to_string()
        })
    } else {
        None
    };
    // Pull current ctx usage from the last ContextStats emission. Before the
    // first turn, show zero usage against the configured provider window. When
    // no provider is available, suppress both values instead of exposing
    // Config's internal 128k fallback as an invented model capability.
    // Using `sent_tokens` (what was actually sent to the model on the
    // last turn) instead of cumulative `total_tokens` because the user
    // cares about "how close to overflow am I", not "how many tokens
    // has this session burned in total". See render::StatusLine docs.
    let (ctx_used, ctx_window) =
        status_context_usage(state, ctx.config.default_context_window(), !no_provider);
    // Session-name badge: surfaced only when the user has explicitly
    // renamed the conversation. Auto-named sessions (default /
    // session-* / first-message-derived) intentionally stay badge-less
    // so the chrome stays quiet on fresh conversations.
    let session_name = if ctx.current_session.user_renamed {
        let name = ctx.current_session.name.trim();
        if name.is_empty() {
            None
        } else {
            Some(name.to_string())
        }
    } else {
        None
    };
    // Active /goal → the dedicated footer goal row (width-truncated by the
    // renderer). Carries the condition text so the user can SEE what the goal
    // is, not just that one is running.
    let goal = state
        .goal_condition
        .as_ref()
        .map(|cond| crate::render::GoalStatus {
            condition: cond.clone(),
            // Display 1-based: the engine's round is 0 on the first attempt.
            round: state.goal_round + 1,
            elapsed_secs: state
                .goal_started_at
                .map(|t| t.elapsed().as_secs())
                .unwrap_or(0),
            phase: state.goal_phase,
        });
    // Active /loop → the dedicated footer loop row. Mirrors GoalStatus exactly,
    // using the loop label as the condition equivalent. Goal takes priority if
    // somehow both are active simultaneously (they shouldn't be).
    let loop_status = state
        .loop_label
        .as_ref()
        .map(|label| crate::render::LoopStatus {
            label: label.clone(),
            // Display 1-based: the engine's round is 0-based internally.
            round: state.loop_round + 1,
            elapsed_secs: state
                .loop_started_at
                .map(|t| t.elapsed().as_secs())
                .unwrap_or(0),
        });
    // Todo panel source: an in-flight presentation preview when present,
    // otherwise the persistent `active_todos` cache. The preview is discarded
    // on failure/cancel and never becomes session authority without success.
    let todo = effective_todo_progress(state)
        .cloned()
        .filter(|p| p.total > 0 && p.completed < p.total);
    let todo_owns_footer = todo.is_some();
    let approval = state
        .approval_panel
        .as_ref()
        .map(|p| crate::render::ApprovalPanelView {
            tool: p.tool.clone(),
            detail: p.detail.clone(),
            options: p.options.iter().map(|o| o.label.clone()).collect(),
            selected: p.selected,
            note: p.note.clone(),
        });
    // A pending batch takes precedence over a single panel (mutually exclusive in
    // practice). The view carries the CURRENT question's fields plus batch navigator
    // metadata; on the Submit stop the panel fields are a placeholder (the renderer
    // draws the submit screen and ignores them).
    let user_input = if let Some(b) = state.user_input_batch.as_ref() {
        let total = b.questions.len();
        let idx = b.current.min(total.saturating_sub(1));
        let p = &b.questions[idx];
        let answered = (0..total).map(|i| b.is_answered(i)).collect();
        let summaries = b
            .questions
            .iter()
            .enumerate()
            .map(|(i, question)| crate::render::UserInputAnswerSummary {
                header: question.header.clone(),
                question: question.question.clone(),
                answer: b.answer_summary(i),
            })
            .collect();
        Some(crate::render::UserInputPanelView {
            header: p.header.clone(),
            question: p.question.clone(),
            mode: p.mode.clone(),
            options: p.options.clone(),
            cursor: p.cursor,
            checked: p.checked.clone(),
            text: p.text.clone(),
            text_cursor_byte: p.text_cursor_byte,
            custom_text: p.custom_text.clone(),
            custom_text_cursor_byte: p.custom_text_cursor_byte,
            custom: p.custom,
            scroll_offset: if b.on_submit_stop() {
                b.submit_scroll_offset
            } else {
                p.scroll_offset
            },
            batch: Some(crate::render::UserInputBatchMeta {
                total,
                // 1-based current question; clamped so the Submit stop (current==total)
                // never reports total+1 (the renderer ignores it there, but keep the
                // contract honest).
                index: (b.current + 1).min(total),
                answered,
                summaries,
                on_submit: b.on_submit_stop(),
            }),
        })
    } else {
        state
            .user_input_panel
            .as_ref()
            .map(|p| crate::render::UserInputPanelView {
                header: p.header.clone(),
                question: p.question.clone(),
                mode: p.mode.clone(),
                options: p.options.clone(),
                cursor: p.cursor,
                checked: p.checked.clone(),
                text: p.text.clone(),
                text_cursor_byte: p.text_cursor_byte,
                custom_text: p.custom_text.clone(),
                custom_text_cursor_byte: p.custom_text_cursor_byte,
                custom: p.custom,
                scroll_offset: p.scroll_offset,
                batch: None,
            })
    };
    crate::render::StatusLine {
        model,
        cwd,
        pending_messages: state
            .pending_steers
            .iter()
            .map(|pending| pending.display_text.clone())
            .collect(),
        history: None,
        search: None,
        next_prompt_suggestion: None,
        command_output: footer_command_output(state),
        ctx_used,
        ctx_window,
        hint,
        mode_indicator,
        bypass_indicator,
        reasoning_effort: if reasoning_effort_applicable_on_provider(ctx) {
            ctx.reasoning_effort.clone()
        } else {
            None
        },
        session_name,
        goal,
        loop_status,
        todo,
        subtasks: if todo_owns_footer {
            None
        } else {
            state.active_subtasks.clone().or_else(|| state.team.panel())
        },
        approval,
        user_input,
        round_cap_panel: state.round_cap_panel.as_ref().map(|p| {
            crate::render::round_cap_view(p.cap, p.base, p.cursor, &round_cap_stats(state))
        }),
    }
}

/// Format the live stats string for the round-cap checkpoint panel.
/// Returns "Xh Ym Zs · N.NNK tokens" (time · tokens), or just one
/// component if the other is absent/zero.  Tool count is omitted —
/// no live in-turn tool accumulator exists (only the per-turn
/// completion count in `PendingSeparator`).
fn round_cap_stats(state: &crate::state::UiState) -> String {
    let mut parts: Vec<String> = Vec::new();
    if let Some(d) = state.turn_elapsed() {
        parts.push(crate::render::fmt_dur(d));
    }
    // Per-turn token total (matches the per-turn `turn_elapsed()` above) —
    // `total_tokens` is session-cumulative and would misreport the tokens spent
    // in THIS turn, which is what the checkpoint is asking about.
    let turn_tokens =
        state.turn_prompt_tokens + state.turn_completion_tokens + state.turn_cached_tokens;
    if turn_tokens > 0 {
        parts.push(format!(
            "{} tokens",
            atomcode_config::i18n::fmt_tokens(turn_tokens)
        ));
    }
    parts.join(" · ")
}

fn build_input_status(state: &UiState, ctx: &LoopCtx, buf: &Buffer) -> crate::render::StatusLine {
    let mut status = build_status(state, ctx);
    status.next_prompt_suggestion = if matches!(state.phase, UiPhase::Idle)
        && buf.text.is_empty()
        && state.pending_images.is_empty()
        && !buf.is_searching()
    {
        state.next_prompt_suggestion.clone()
    } else {
        None
    };
    if buf.is_searching() {
        // Ctrl+R reverse-i-search takes over the top-rule indicator;
        // the History N/N position is hidden while searching.
        status.search = input_search_state(buf, ctx.history.entries());
        status.history = None;
    } else {
        status.history = input_history_position(buf, ctx.history.entries().len());
    }
    status
}

/// Live reverse-i-search snapshot: current match position among all
/// matching entries, plus the query for the indicator label.
fn input_search_state(
    buf: &Buffer,
    history: &[crate::input::history::HistoryEntry],
) -> Option<crate::render::SearchState> {
    if !buf.is_searching() {
        return None;
    }
    let q = buf.search_query().to_lowercase();
    let matches: Vec<usize> = (0..history.len())
        .rev()
        .filter(|&i| history[i].text.to_lowercase().contains(&q))
        .collect();
    // history_idx() is the currently shown match; find its 1-based
    // position within the match list.
    let current = buf
        .history_idx()
        .and_then(|idx| matches.iter().position(|&m| m == idx))
        .map(|pos| pos + 1)
        .unwrap_or(0);
    Some(crate::render::SearchState {
        query: buf.search_query().to_string(),
        current,
        total: matches.len(),
        matched: buf.history_idx().is_some(),
    })
}

fn input_history_position(buf: &Buffer, total: usize) -> Option<crate::render::HistoryPosition> {
    buf.history_idx()
        .filter(|index| *index < total)
        .map(|index| crate::render::HistoryPosition {
            current: index + 1,
            total,
        })
}

#[cfg(test)]
mod input_history_position_tests {
    use super::{input_history_position, Buffer};

    #[test]
    fn visible_only_while_recalling_history() {
        let mut buf = Buffer::new();
        assert_eq!(input_history_position(&buf, 100), None);

        buf.history_idx = Some(99);
        let latest = input_history_position(&buf, 100).expect("history position");
        assert_eq!((latest.current, latest.total), (100, 100));

        buf.history_idx = Some(42);
        let older = input_history_position(&buf, 100).expect("history position");
        assert_eq!((older.current, older.total), (43, 100));

        buf.history_idx = None;
        assert_eq!(
            input_history_position(&buf, 100),
            None,
            "returning to the draft hides the indicator"
        );
    }

    #[test]
    fn stale_or_empty_index_is_hidden() {
        let mut buf = Buffer::new();
        buf.history_idx = Some(0);
        assert_eq!(input_history_position(&buf, 0), None);
        buf.history_idx = Some(3);
        assert_eq!(input_history_position(&buf, 2), None);
    }
}

/// Render one spinner frame. Used from both the interval-driven tick
/// path and the opportunistic "post-event" pump path that guards
/// against agent-event floods starving the interval tick.
///
/// When the type-ahead buffer starts with `/`, the slash-command palette
/// is attached so the user can see candidate commands mid-stream (the
/// renderer then shows the menu in place of the spinner).
fn draw_spinner_now(
    state: &mut UiState,
    buf: &Buffer,
    ctx: &LoopCtx,
    renderer: &mut dyn Renderer,
    queue_len: usize,
    menu_selected: usize,
) {
    sync_composer_selection(buf, &ctx.interaction_publisher);
    let frame = state.tick_spinner();
    // Same source + applicability gate as the status bar's `[high]`, so the
    // spinner's effort hint and the status line never disagree. (Reading
    // `state.reasoning_effort` here showed nothing when effort came from the
    // provider config / webui rather than a Ctrl+T cycle.)
    let effort = if reasoning_effort_applicable_on_provider(ctx) {
        ctx.reasoning_effort.as_deref()
    } else {
        None
    };
    let label = format_spinner_label(state, queue_len, effort);
    let status = build_input_status(state, ctx, buf);
    let menu = menu_for_display(buf, ctx).map(|items| {
        let selected = menu_selected.min(items.len().saturating_sub(1));
        let kind = if file_index::detect_at_mention_range(&buf.text, buf.cursor).is_some() {
            crate::render::MenuKind::AtMention
        } else if buf.text.starts_with('$') {
            crate::render::MenuKind::Skill
        } else {
            crate::render::MenuKind::SlashCommand
        };
        crate::render::MenuPayload {
            items,
            selected,
            kind,
        }
    });
    let attachments = compute_input_attachments(state, &buf.text);
    renderer.render(UiLine::StreamingBox {
        buf: buf.text.clone(),
        cursor_byte: buf.cursor,
        frame,
        label,
        status,
        menu,
        attachments,
    });
    renderer.flush();
}

/// Build the spinner line shown in the footer —
/// `"{label}… · {elapsed} · {N} queued"`. State stores only the bare
/// word (e.g. `Pondering`, `Running ReadFile`); ellipsis + elapsed +
/// queued suffixes are appended here so format is consistent across
/// every call site.
fn format_spinner_label(
    state: &UiState,
    queue_len: usize,
    reasoning_effort: Option<&str>,
) -> String {
    // Compaction takes over the spinner: show "Compacting…" (or a slow variant
    // past the stall threshold) with the phase elapsed appended, instead of a
    // thinking label. Unified for auto + manual /compact.
    if state.compacting {
        let base = if state.compaction_stalled() {
            crate::i18n::t(crate::i18n::Msg::CompactingSlow)
        } else {
            crate::i18n::t(crate::i18n::Msg::Compacting)
        };
        let mut out = base.into_owned();
        if let Some(d) = state.phase_elapsed() {
            out.push_str(&format!(" · {}", fmt_elapsed(d.as_millis() as u64)));
        }
        return out;
    }
    // `display_spinner_label` maps `Running X` / `Preparing X` back to the
    // thinking word so the footer never flashes tool names — tool progress is
    // carried by the body `▸ Tool(detail)` rows. Other labels pass through.
    //
    // While a `task` subagent fan-out is running, the parent agent is just
    // waiting on its children (a generic `Pondering…`). Replace that with the
    // children's latest live activity (`explore#4 · grep unwrap`) so the
    // otherwise-silent multi-minute fan-out shows what it's doing — in-place on
    // the spinner, so it coexists with the goal/todo footer rows for free.
    let base: &str = state
        .subagent_activity
        .as_deref()
        .unwrap_or_else(|| state.display_spinner_label());
    let mut out = format!("{}{}", base, state.ellipsis());
    // Order matters. The phase clock (`· 372ms`) ticks every frame, and any
    // segment AFTER a rapidly-changing field shifts on every redraw — which
    // read as flicker when the elapsed sat in the middle (user report:
    // `Cogitating… · 372ms · thinking with high effort` jittered the effort
    // text). So: static segments first, the ticking elapsed dead last.
    //
    // Reasoning-effort hint (deepseek-v4 high/max), mirroring CC's
    // `… · thinking with high effort`. The value comes from the caller (the
    // ctx-sourced, applicability-gated effort — the SAME source as the status
    // bar's `[high]`, so the two never disagree). Placed FIRST among the
    // metadata so `spinner_meta_suffix` can splice it out (a tool isn't
    // "thinking") while still forwarding the trailing time/queue anchors.
    if let Some(effort) = reasoning_effort {
        out.push_str(&format!(" · thinking with {} effort", effort));
    }
    if queue_len > 0 {
        out.push_str(&format!(" · {} queued", queue_len));
    }
    // (The mid-stream "· esc to cancel" stall hint was removed by request — esc
    // still cancels, it's just no longer advertised in the spinner. The stall
    // machinery (`stream_stalled`) stays for the compaction-slow variant.)
    // Phase elapsed + live output counter, grouped in parens at the very end —
    // `Noodling… (49m44s · ↑ 12.4k tokens)`, matching Claude Code. Phase elapsed
    // (NOT total turn) so the timer reads "this operation has run N seconds",
    // resetting on every phase transition. `fmt_elapsed` starts at whole seconds
    // (never `340ms`) so the clock doesn't flicker millisecond digits. The token
    // estimate is the liveness proof — it keeps ticking through a long single
    // generation (text / reasoning / tool-call args) so the turn never looks
    // hung. Shown only once output has started (no `↑ 0 tokens`). LAST, so its
    // per-frame width changes never shift anything before it.
    if let Some(d) = state.phase_elapsed() {
        let elapsed = fmt_elapsed(d.as_millis() as u64);
        let tokens = state.turn_output_token_estimate();
        if tokens > 0 {
            out.push_str(&format!(
                " ({elapsed} · \u{2191} {} tokens)",
                crate::i18n::fmt_tokens(tokens)
            ));
        } else {
            out.push_str(&format!(" ({elapsed})"));
        }
    }
    out
}

/// Convert a snake_case tool name to PascalCase for display. The agent
/// protocol uses `read_file`, `edit_file`, `web_fetch` etc.; the UI shows
/// `ReadFile`, `EditFile`, `WebFetch` — a CC-style convention that reads
/// more cleanly at a glance.
///
/// MCP tools arrive on the wire as `mcp__<server>__<tool>`. Naive
/// PascalCase collapses the three parts into `McpZouwuQueryRequirements`
/// where the server / tool boundary disappears. Render them with a
/// middle-dot separator so users can tell at a glance which part is the
/// server and which is the tool (#299).
pub fn display_tool_name(snake: &str) -> String {
    if let Some(rest) = snake.strip_prefix("mcp__") {
        if let Some((server, tool)) = rest.split_once("__") {
            return format!("mcp · {} · {}", server, tool);
        }
    }
    pascal_case(snake)
}

fn pascal_case(snake: &str) -> String {
    let mut out = String::with_capacity(snake.len());
    for word in snake.split('_') {
        let mut chars = word.chars();
        if let Some(c) = chars.next() {
            out.extend(c.to_uppercase());
            out.push_str(chars.as_str());
        }
    }
    out
}

/// CC-style short tool name. Strips the redundant `_file` /
/// `_directory` / `_files` suffixes (the noun is implicit from the
/// arg) before PascalCase conversion. Generic — no per-tool match
/// arms; works for any future tool that follows the
/// `<verb>_<noun>` convention.
///
/// Examples:
/// - `read_file` → `Read`
/// - `write_file` → `Write`
/// - `list_directory` → `List`
/// - `parallel_edit_files` → `ParallelEdit`
/// - `bash` → `Bash` (no suffix to strip)
/// - `search_replace` → `SearchReplace` (suffix `_replace` not in
///    strip list, kept verbatim → preserves disambiguation)
pub fn display_tool_name_short(snake: &str) -> String {
    // MCP wire names (`mcp__server__tool`) carry their suffix as part of the
    // real tool name — stripping `_file`/`_files`/`_directory` here would turn
    // `mcp__fs__read_file` into `mcp · fs · read`. Hand the full name to
    // display_tool_name so the `mcp · server · tool` split stays verbatim.
    if snake.starts_with("mcp__") {
        return display_tool_name(snake);
    }
    const STRIP_SUFFIXES: &[&str] = &["_files", "_file", "_directory"];
    let trimmed = STRIP_SUFFIXES
        .iter()
        .find_map(|s| snake.strip_suffix(s))
        .unwrap_or(snake);
    display_tool_name(trimmed)
}

/// Parse the full task list every `todo` result returns into `map`
/// (id → content). The list renders as `{icon} {id}. {content}` lines
/// (see `todo.rs::render`); we match that shape and ignore everything
/// else (the "Added task #N: …" / "Task #N '…' updated" preamble lines
/// don't match and are skipped). Both the core and capabilities todo
/// tools share this line format, so one parser covers both.
pub(crate) fn parse_todo_titles_into(
    map: &mut std::collections::HashMap<u64, String>,
    output: &str,
) {
    for line in output.lines() {
        let line = line.trim_start();
        // "[<icon>] <id>. <content>"
        let Some(rest) = line.strip_prefix('[') else {
            continue;
        };
        let Some((_icon, after)) = rest.split_once("] ") else {
            continue;
        };
        let Some((id_str, content)) = after.split_once(". ") else {
            continue;
        };
        let Ok(id) = id_str.trim().parse::<u64>() else {
            continue;
        };
        let content = content.trim();
        if !content.is_empty() {
            map.insert(id, content.to_string());
        }
    }
}

/// Splice the known task title into a `todo update` detail so the row
/// shows the NAME, not just the id: `#4 → completed` becomes
/// `#4 Write tests → completed`. Returns `base` unchanged for non-todo
/// tools, non-update actions, or ids whose title we haven't learned yet
/// (graceful fallback to the id-only form).
pub(crate) fn enrich_todo_detail(
    name: &str,
    args_json: &str,
    base: &str,
    titles: &std::collections::HashMap<u64, String>,
) -> String {
    // Merged `todowrite` carries update actions too; legacy `todo` name still recognized.
    if name != "todo" && name != "todowrite" {
        return base.to_string();
    }
    let repaired = atomcode_capabilities::tools::repair::repair_tool_args(name, args_json);
    let Ok(v) = serde_json::from_str::<serde_json::Value>(&repaired) else {
        return base.to_string();
    };
    if v.get("action").and_then(|a| a.as_str()) != Some("update") {
        return base.to_string();
    }
    let Some(id) = v.get("id").and_then(|x| x.as_u64()) else {
        return base.to_string();
    };
    let Some(title) = titles.get(&id) else {
        return base.to_string();
    };
    let title = crate::width::truncate_with_ellipsis(title, 80);
    // `base` is `#<id> → <status>` (or bare `#<id>`); insert the title
    // right after the id so the arrow keeps pointing at the status.
    match base.split_once(" \u{2192} ") {
        Some((head, tail)) => format!("{} {} \u{2192} {}", head, title, tail),
        None => format!("{} {}", base, title),
    }
}

pub(crate) fn format_tool_detail(name: &str, args_json: &str) -> String {
    let repaired_args = atomcode_capabilities::tools::repair::repair_tool_args(name, args_json);
    let Ok(v) = serde_json::from_str::<serde_json::Value>(&repaired_args) else {
        return String::new();
    };
    let get_str = |k: &str| v.get(k).and_then(|x| x.as_str()).map(str::to_string);
    let basename = |p: &str| p.rsplit('/').next().unwrap_or(p).to_string();

    match name {
        "read_file" | "edit_file" | "write_file" | "create_file" | "list_symbols" => {
            // Single-call path: basename only (compact). Batch disambiguation
            // is handled by `disambiguate_batch_details` which runs after
            // all child details are computed and can compare them.
            get_str("file_path")
                .map(|p| basename(&p))
                .unwrap_or_default()
        }
        "read_symbol" => {
            let sym = get_str("symbol").unwrap_or_default();
            let file = get_str("file_path")
                .map(|p| basename(&p))
                .unwrap_or_default();
            if sym.is_empty() {
                file
            } else if file.is_empty() {
                sym
            } else {
                format!("{} in {}", sym, file)
            }
        }
        "glob" => get_str("pattern")
            .map(|p| crate::width::truncate_with_ellipsis(&p, 100))
            .unwrap_or_default(),
        "grep" => get_str("pattern")
            .map(|p| crate::width::truncate_with_ellipsis(&p, 100))
            .unwrap_or_default(),
        "bash" => get_str("command")
            .map(|c| crate::width::truncate_with_ellipsis(&c, 500))
            .unwrap_or_default(),
        "list_directory" | "change_dir" => get_str("path").unwrap_or_else(|| ".".into()),
        "code_review" => {
            if let Some(scope) = v.get("scope") {
                return match scope.get("kind").and_then(|kind| kind.as_str()) {
                    Some("working_tree") => "working tree".to_string(),
                    Some("staged") => "staged changes".to_string(),
                    Some("range") => {
                        let base = scope
                            .get("base")
                            .and_then(|value| value.as_str())
                            .unwrap_or("");
                        let head = scope
                            .get("head")
                            .and_then(|value| value.as_str())
                            .unwrap_or("HEAD");
                        format!("{base}..{head}")
                    }
                    Some("commit") => scope
                        .get("rev")
                        .and_then(|value| value.as_str())
                        .map_or_else(String::new, |rev| format!("commit {rev}")),
                    _ => String::new(),
                };
            }
            let base = get_str("base");
            let staged = v.get("staged").and_then(|x| x.as_bool()).unwrap_or(false);
            match (base, staged) {
                (Some(b), true) => format!("base: \"{}\", staged: true", b),
                (Some(b), false) => format!("base: \"{}\"", b),
                (None, true) => "staged: true".to_string(),
                (None, false) => String::new(),
            }
        }
        "web_fetch" => get_str("url")
            .map(|u| crate::width::truncate_with_ellipsis(&u, 150))
            .unwrap_or_default(),
        "web_search" => get_str("query")
            .map(|q| crate::width::truncate_with_ellipsis(&q, 100))
            .unwrap_or_default(),
        "find_references" | "trace_callees" | "trace_callers" => {
            get_str("symbol").unwrap_or_default()
        }
        "trace_chain" => {
            // trace_chain takes `from`/`to`, not `symbol` — keep this branch
            // separate so the detail isn't blank. See trace_chain.rs Args.
            let from = get_str("from").unwrap_or_default();
            let to = get_str("to").unwrap_or_default();
            if from.is_empty() || to.is_empty() {
                String::new()
            } else {
                format!("{} → {}", from, to)
            }
        }
        "blast_radius" | "file_dependencies" => {
            // Same as above: basename for single-call; batch disambiguation
            // handled by `disambiguate_batch_details`.
            get_str("file").map(|p| basename(&p)).unwrap_or_default()
        }
        "search_replace" => {
            // SearchReplaceArgs uses search/replace/glob/path (not
            // file_path/file/pattern/old). Show "search → replace" so
            // the approval prompt tells the user WHAT will be replaced.
            let search = get_str("search");
            let replace = get_str("replace");
            let glob = get_str("glob");
            let path = get_str("path");
            match (&search, &replace) {
                (Some(s), Some(r)) => {
                    let arrow = format!(
                        "{} → {}",
                        crate::width::truncate_with_ellipsis(s, 60),
                        crate::width::truncate_with_ellipsis(r, 60)
                    );
                    let mut parts = vec![arrow];
                    if let Some(g) = &glob {
                        parts.push(format!("glob: {}", g));
                    }
                    if let Some(p) = &path {
                        if p != "." {
                            parts.push(format!("path: {}", basename(p)));
                        }
                    }
                    parts.join(", ")
                }
                (None, Some(r)) => crate::width::truncate_with_ellipsis(r, 100),
                (Some(s), None) => crate::width::truncate_with_ellipsis(s, 100),
                _ => String::new(),
            }
        }
        "parallel_edit_files" => {
            // Show the list of target file basenames so the user can see
            // WHAT will be edited at a glance in the approval prompt —
            // mirroring how Bash(rm -rf /path) tells the user exactly
            // which command needs approval. Without this, the approval
            // prompt just shows "ParallelEditFiles:" with no detail,
            // leaving the user blind to the scope of the dispatch.
            if let Some(files) = v.get("files").and_then(|f| f.as_array()) {
                let names: Vec<String> = files
                    .iter()
                    .filter_map(|entry| {
                        entry
                            .get("path")
                            .and_then(|p| p.as_str())
                            .map(|s| basename(s))
                    })
                    .collect();
                let detail = names.join(", ");
                crate::width::truncate_with_ellipsis(&detail, 200)
            } else {
                String::new()
            }
        }
        // Merged `todowrite` (legacy `todo` still recognized for resumed sessions): the shape
        // decides the detail — a full-list plan shows the count, an `{action}` shows what changed.
        "todowrite" | "todo" => {
            if let Some(arr) = v.get("todos").and_then(|t| t.as_array()) {
                match arr.len() {
                    0 => "0 tasks".to_string(),
                    1 => "1 task".to_string(),
                    n => format!("{} tasks", n),
                }
            } else {
                // Incremental action: show the description (add) or id+status (update).
                let action = get_str("action").unwrap_or_default();
                match action.as_str() {
                    "add" => get_str("content")
                        .map(|c| crate::width::truncate_with_ellipsis(&c, 100))
                        .unwrap_or_default(),
                    "update" => {
                        let id = v.get("id").and_then(|x| x.as_u64());
                        let status = get_str("status").unwrap_or_default();
                        match (id, status.as_str()) {
                            (Some(i), s) if !s.is_empty() => format!("#{} → {}", i, s),
                            (Some(i), _) => format!("#{}", i),
                            (None, s) if !s.is_empty() => s.to_string(),
                            _ => String::new(),
                        }
                    }
                    "list" => "list all".to_string(),
                    _ => String::new(),
                }
            }
        }
        "use_skill" => get_str("name").unwrap_or_default(),
        "task" => {
            // Header preview: a single subtask shows its description; a batch shows the
            // count. (Per-subtask model/status is on the RESULT line — see
            // `summarise_task_result`; the model isn't known until execution.)
            match v.get("tasks").and_then(|t| t.as_array()) {
                Some(arr) if arr.len() == 1 => arr[0]
                    .get("description")
                    .and_then(|d| d.as_str())
                    .map(|s| crate::width::truncate_with_ellipsis(s, 100))
                    .unwrap_or_default(),
                Some(arr) if !arr.is_empty() => format!("{} subtasks", arr.len()),
                _ => String::new(),
            }
        }
        _ => {
            // For MCP tools (name starts with mcp__), render the
            // arguments as key=value pairs so users can see what
            // parameters are being passed to the external server.
            if name.starts_with("mcp__") {
                if let Some(obj) = v.as_object() {
                    let pairs: Vec<String> = obj
                        .iter()
                        .filter_map(|(k, val)| {
                            let s = match val {
                                serde_json::Value::String(s) => s.clone(),
                                serde_json::Value::Number(n) => n.to_string(),
                                serde_json::Value::Bool(b) => b.to_string(),
                                serde_json::Value::Array(a) => {
                                    serde_json::to_string(a).unwrap_or_default()
                                }
                                serde_json::Value::Object(o) => {
                                    serde_json::to_string(o).unwrap_or_default()
                                }
                                _ => return None,
                            };
                            if s.is_empty() {
                                return None;
                            }
                            Some(format!("{}: \"{}\"", k, s.replace('"', "\\\"")))
                        })
                        .collect();
                    if !pairs.is_empty() {
                        return crate::width::truncate_with_ellipsis(&pairs.join(", "), 450);
                    }
                }
            }
            // Fallback: try common single-key args that make sense as detail.
            for key in [
                "file_path",
                "path",
                "file",
                "pattern",
                "query",
                "url",
                "name",
                "symbol",
                "command",
            ] {
                if let Some(s) = get_str(key) {
                    return crate::width::truncate_with_ellipsis(&s, 100);
                }
            }
            String::new()
        }
    }
}

/// Disambiguate parallel-batch child details when multiple calls produce
/// the same short display (e.g. 3 × `Read(SKILL.md)` from different dirs).
///
/// For each child whose `raw_detail` duplicates another, walks up the
/// path from basename toward the root until all duplicates are unique.
/// Non-duplicate entries are left unchanged.
///
/// Example:
///   paths: [skills/a/SKILL.md, skills/b/SKILL.md, skills/c/SKILL.md]
///   raw_details: [SKILL.md, SKILL.md, SKILL.md]
///   → [a/SKILL.md, b/SKILL.md, c/SKILL.md]
///
/// If paths can't be extracted from arguments (non-file tools), falls
/// back to appending `#2`, `#3` suffixes.
fn disambiguate_batch_details(
    names: &[&str],
    args_jsons: &[&str],
    raw_details: &[String],
) -> Vec<String> {
    // Fast path: no duplicates → return as-is.
    let mut seen = std::collections::HashMap::<&str, usize>::new();
    let mut has_dups = false;
    for d in raw_details {
        let count = seen.entry(d.as_str()).or_insert(0);
        *count += 1;
        if *count > 1 {
            has_dups = true;
        }
    }
    if !has_dups {
        return raw_details.to_vec();
    }

    // Extract full paths from args where possible.
    let extract_path = |name: &str, args_json: &str| -> Option<String> {
        let Ok(v) = serde_json::from_str::<serde_json::Value>(args_json) else {
            return None;
        };
        let get_str = |k: &str| v.get(k).and_then(|x| x.as_str()).map(str::to_string);
        match name {
            "read_file" | "edit_file" | "write_file" | "create_file" | "list_symbols"
            | "blast_radius" | "file_dependencies" => {
                get_str("file_path").or_else(|| get_str("file"))
            }
            "search_replace" => get_str("file_path").or_else(|| get_str("file")),
            "read_symbol" => get_str("file_path"),
            _ => None,
        }
    };

    let full_paths: Vec<Option<String>> = names
        .iter()
        .zip(args_jsons.iter())
        .map(|(n, a)| extract_path(n, a))
        .collect();

    // For each group of duplicates, progressively add parent path
    // components until unique within that group.
    let mut result = raw_details.to_vec();

    // Collect groups of indices that share the same raw_detail.
    let mut groups: std::collections::HashMap<&str, Vec<usize>> = std::collections::HashMap::new();
    for (i, d) in raw_details.iter().enumerate() {
        groups.entry(d.as_str()).or_default().push(i);
    }

    for (_detail, indices) in groups {
        if indices.len() < 2 {
            continue; // unique, no disambiguation needed
        }

        // Check if we have full paths for all in this group.
        let all_have_paths = indices.iter().all(|&i| full_paths[i].is_some());

        if all_have_paths {
            // Strategy: progressively add parent path components until
            // all entries are unique. Start with 1 parent component
            // (e.g. `a/SKILL.md`), then 2 (`b/a/SKILL.md`), etc.
            let paths: Vec<&str> = indices
                .iter()
                .map(|&i| full_paths[i].as_deref().unwrap())
                .collect();
            let mut depth = 1usize;
            let max_depth = paths
                .iter()
                .map(|p| p.matches('/').count())
                .max()
                .unwrap_or(0);

            loop {
                let candidates: Vec<String> = paths.iter().map(|p| tail_path(p, depth)).collect();

                let all_unique = {
                    let mut s = std::collections::HashSet::new();
                    candidates.iter().all(|c| s.insert(c.as_str()))
                };

                if all_unique || depth >= max_depth {
                    for (i, &idx) in indices.iter().enumerate() {
                        result[idx] = crate::width::truncate_with_ellipsis(&candidates[i], 100);
                    }
                    break;
                }
                depth += 1;
            }
        } else {
            // Fallback: append #2, #3, … suffixes to disambiguate.
            for (seq, &idx) in indices.iter().enumerate() {
                if seq > 0 {
                    let suffixed = format!("{} #{}", raw_details[idx], seq + 1);
                    result[idx] = crate::width::truncate_with_ellipsis(&suffixed, 100);
                }
            }
        }
    }

    result
}

/// Return the last `depth + 1` path components of `path`.
/// E.g. tail_path("a/b/c/SKILL.md", 1) → "c/SKILL.md"
///      tail_path("a/b/c/SKILL.md", 2) → "b/c/SKILL.md"
///      tail_path("a/b/c/SKILL.md", 3) → "a/b/c/SKILL.md"
fn tail_path(path: &str, depth: usize) -> String {
    if depth == 0 {
        return path.rsplit('/').next().unwrap_or(path).to_string();
    }
    // Walk backwards counting separators. To keep `depth + 1` components,
    // we need to find the separator that is `depth + 1`-th from the end,
    // then return everything after it.
    // For depth=1 in "a/b/c/SKILL.md": we need "c/SKILL.md",
    // so find the '/' between "b" and "c" (2nd from end), return after it.
    let mut seen = 0;
    for (i, ch) in path.char_indices().rev() {
        if ch == '/' {
            seen += 1;
            if seen == depth + 1 {
                return path[(i + ch.len_utf8())..].to_string();
            }
        }
    }
    // Fewer than `depth + 1` separators — return the whole path.
    path.to_string()
}

/// Render an `elapsed_ms` value as `XmYs` (over 60 s) or `Ts` (under).
/// Tens of milliseconds aren't useful for the UI; whole seconds match
/// what users see on a wall clock and align column-wise across rows.
pub(crate) fn fmt_elapsed(ms: u64) -> String {
    let total_secs = ms / 1000;
    if total_secs >= 60 {
        format!("{}m{}s", total_secs / 60, total_secs % 60)
    } else {
        format!("{}s", total_secs)
    }
}

/// Build the one-line preview shown under a tool call (`└ …`): the
/// output's first line, plus a ` (N lines)` suffix when it spans more.
///
/// No display-width budget here on purpose. The retained renderer wraps
/// this to the LIVE terminal width (`wrap_line_to_width(_, screen.width()
/// − …)` in the `UiLine::ToolResult` arm), so the preview fills whatever
/// width the screen has and re-fits on resize — and the ` (N lines)`
/// suffix is never lost because wrapping carries it to a continuation row.
/// We used to hard-cap at 80 cols (success) / 200 (failure), which baked a
/// `…` into the string and wasted the right half of wide screens. The
/// 512-col cap that remains is a pure safety bound: it only trips for a
/// pathological multi-KB single line (e.g. a minified file) so it can't
/// wrap into dozens of rows. Real first lines are far shorter.
/// Extract the unique result source domains from a `web_search` tool result.
///
/// Scans the output text for `http(s)://` URLs, keeps each host, strips a
/// leading `www.`, and dedupes preserving first-seen order. Works for the
/// DuckDuckGo backend (explicit `url` lines) and the Exa backend (URLs are
/// embedded in the LLM-ready text blob). Returns `[]` when the output carries
/// no URLs (an Exa blob without links, or an error message) so the caller can
/// fall back to the generic line count.
pub(crate) fn web_search_source_domains(output: &str) -> Vec<String> {
    let mut seen = std::collections::HashSet::new();
    let mut out = Vec::new();
    let mut rest = output;
    while let Some(pos) = rest.find("http") {
        let after = &rest[pos..];
        let scheme_len = if after.starts_with("https://") {
            8
        } else if after.starts_with("http://") {
            7
        } else {
            // "http" not part of a URL scheme — step past it (ASCII, so the
            // byte offset is a valid char boundary) and keep scanning.
            rest = &rest[pos + 4..];
            continue;
        };
        let host_part = &after[scheme_len..];
        // Host ends at the first path / query / port / delimiter byte. All
        // candidates are ASCII, so the split stays on a char boundary even if
        // the host itself contains non-ASCII (IDN) bytes.
        let end = host_part
            .find(|c: char| {
                matches!(
                    c,
                    '/' | '?' | '#' | ':' | ')' | ']' | '"' | '\'' | '>' | '<' | ','
                ) || c.is_whitespace()
            })
            .unwrap_or(host_part.len());
        let host = host_part[..end].trim_end_matches('.');
        let host = host.strip_prefix("www.").unwrap_or(host);
        if host.contains('.') && seen.insert(host.to_string()) {
            out.push(host.to_string());
        }
        rest = &host_part[end..];
    }
    out
}

/// Build the ` → src1, src2 +N` summary suffix for a completed `web_search`
/// call. Shows up to two source domains; any remainder collapses to `+N`.
/// Returns `None` when no domains could be extracted, so the caller keeps the
/// generic line-count suffix.
pub(crate) fn web_search_result_suffix(output: &str) -> Option<String> {
    const SHOWN: usize = 2;
    let domains = web_search_source_domains(output);
    if domains.is_empty() {
        return None;
    }
    let head = domains
        .iter()
        .take(SHOWN)
        .cloned()
        .collect::<Vec<_>>()
        .join(", ");
    let extra = domains.len().saturating_sub(SHOWN);
    Some(if extra > 0 {
        format!("{head} +{extra}")
    } else {
        head
    })
}

/// Rebuild a parallel tool-batch group (header + child rows) for the `/resume`
/// replay path, mirroring the live `AgentEvent::ToolBatchStarted` layout.
///
/// The saved transcript has no `parallel_safe` flag — batch metadata is a
/// live-only UI construct that is never persisted — so the header always uses
/// the non-"in parallel" form. That is exactly what non-read-only batches
/// (bash / write / todowrite) showed live anyway; only a pure read-only batch
/// loses the literal "in parallel" words after a resume.
///
/// Each child already carries its final `→ N lines` / `→ ✗` result suffix,
/// computed from the persisted tool results (`result_of`: call_id → (success,
/// output)), so the replayed group matches a *completed* live batch without any
/// in-place child updates. `todo_titles` enriches `todo update` child rows the
/// same way the live path does.
pub(crate) fn build_replay_tool_batch(
    calls: &[atomcode_kernel::tool::ToolCall],
    result_of: &std::collections::HashMap<String, (bool, String)>,
    todo_titles: &std::collections::HashMap<u64, String>,
) -> (
    String,
    Vec<crate::render::ToolGroupChild>,
    Vec<crate::state::BatchedEditDisplay>,
) {
    let count = calls.len();
    let unique_names: std::collections::HashSet<&str> =
        calls.iter().map(|c| c.name.as_str()).collect();
    let label = if unique_names.len() == 1 {
        format!(
            "Running {} {} calls",
            count,
            unique_names.iter().next().copied().unwrap_or("tool")
        )
    } else {
        format!("Running {} tools", count)
    };
    let head_glyph = "\u{25cf}";
    let child_glyph = "\u{2514}";
    let arrow = "\u{2192}";
    let header = format!("{} {}", head_glyph, label);

    let raw_details: Vec<String> = calls
        .iter()
        .map(|c| format_tool_detail(&c.name, &c.arguments))
        .collect();
    let disambiguated = disambiguate_batch_details(
        &calls.iter().map(|c| c.name.as_str()).collect::<Vec<_>>(),
        &calls
            .iter()
            .map(|c| c.arguments.as_str())
            .collect::<Vec<_>>(),
        &raw_details,
    );
    let mut todo_add_counter: usize = 0;
    let children = calls
        .iter()
        .zip(disambiguated.iter())
        .map(|(c, detail)| {
            // Mirror the live todo `#N` numbering / update enrichment.
            let detail = if c.name == "todo" || c.name == "todowrite" {
                let action = serde_json::from_str::<serde_json::Value>(&c.arguments)
                    .ok()
                    .and_then(|v| v.get("action").and_then(|a| a.as_str()).map(str::to_string));
                match action.as_deref() {
                    Some("add") => {
                        todo_add_counter += 1;
                        format!("#{} {}", todo_add_counter, detail)
                    }
                    Some("update") => {
                        enrich_todo_detail(&c.name, &c.arguments, detail, todo_titles)
                    }
                    _ => detail.clone(),
                }
            } else {
                detail.clone()
            };
            // Result suffix from the persisted result — matches the live
            // `ToolGroupChildUpdate`: `→ N lines` / `→ ✗` / web_search sources.
            let suffix = match result_of.get(&c.id) {
                Some((false, _)) => format!(" {} \u{2717}", arrow),
                Some((true, output)) => {
                    let web = (c.name == "web_search")
                        .then(|| web_search_result_suffix(output))
                        .flatten();
                    if let Some(srcs) = web {
                        format!(" {} {}", arrow, srcs)
                    } else {
                        let n = output.lines().count().max(1);
                        let unit = if n == 1 { "line" } else { "lines" };
                        format!(" {} {} {}", arrow, n, unit)
                    }
                }
                // No persisted result (e.g. a batch cut off mid-turn): leave the
                // child bare, exactly like a live child awaiting its result.
                None => String::new(),
            };
            // bash → `Short det` (no parens); others → `Short(det)`. Matches the
            // live completed-child (`ToolGroupChildUpdate`) formatting.
            let body = if c.name.eq_ignore_ascii_case("bash") {
                format!("{} {}", display_tool_name_short(&c.name), detail)
            } else {
                format!("{}({})", display_tool_name_short(&c.name), detail)
            };
            crate::render::ToolGroupChild {
                call_id: c.id.clone(),
                text: format!("  {} {}{}", child_glyph, body, suffix),
            }
        })
        .collect();
    let edit_displays = calls
        .iter()
        .filter_map(|call| {
            let (success, output) = result_of.get(&call.id)?;
            batched_edit_display(&call.name, output, *success)
        })
        .collect();
    (header, children, edit_displays)
}

pub(crate) fn summarise(output: &str) -> String {
    let first = output.lines().next().unwrap_or("(no output)");
    let n = output.lines().count();
    // `truncate_with_ellipsis` (not bare `truncate_to_width`) so that if
    // the safety bound ever does bite, the cut is visibly marked.
    let trimmed = crate::width::truncate_with_ellipsis(first, 512);
    if n > 1 {
        format!("{} ({} lines)", trimmed, n)
    } else {
        trimmed
    }
}

/// Collapse a `read_file` first-line preview into a tidy `{n}  {content}`.
///
/// `read_file` formats each line as `{n}\t{source line}` — the line number, a
/// tab, then the source line WITH its own indentation (legacy transcripts may
/// carry a `{n:>6}\t` 6-column-padded number, which the `trim` below still
/// handles). For a deeply-indented line the tab plus that indentation renders
/// as a big empty gap between the number and the text. Recognise the
/// `<digits>\t` prefix and collapse the tab + the content's leading whitespace to
/// two spaces; fall back to the raw first line for anything else (directory
/// listing, `[File skeleton…]` header, error message).
pub(crate) fn summarise_read_result(output: &str) -> String {
    let first = output.lines().next().unwrap_or("(no output)");
    let n = output.lines().count();
    let cleaned = match first.split_once('\t') {
        Some((lead, content))
            if !lead.trim().is_empty() && lead.trim().chars().all(|c| c.is_ascii_digit()) =>
        {
            format!("{}  {}", lead.trim(), content.trim_start())
        }
        _ => first.to_string(),
    };
    let trimmed = crate::width::truncate_with_ellipsis(&cleaned, 512);
    if n > 1 {
        format!("{} ({} lines)", trimmed, n)
    } else {
        trimmed
    }
}

/// 把 `s` 切成 (head, tail):head 是显示宽度 ≤ `max` 列的最长前缀,绝不从**字素簇**
/// 中间切开(ZWJ emoji/组合字/宽字整体挪到 tail)。按字素簇+`cluster_width` 度量,
/// 与调用方推进 `line_len` 用的 `display_width` 完全一致,避免宽度对不齐导致产出行
/// 反而超宽被 paint 层裁掉。保证前进:至少取一个字素簇,故调用方可循环折到穷尽不死循环。
/// 前置:`max` 应 ≥ 最宽单簇(2 列),否则单簇本身就超 `max`(仅在退化窄宽度下,生产
/// 调用方已把 width clamp 到 ≥8 故不触发)。
fn split_head_by_width(s: &str, max: usize) -> (&str, &str) {
    use unicode_segmentation::UnicodeSegmentation;
    let mut w = 0usize;
    for (i, g) in s.grapheme_indices(true) {
        let cw = crate::width::cluster_width(g);
        if i > 0 && w + cw > max {
            return (&s[..i], &s[i..]);
        }
        w += cw;
    }
    (s, "")
}

/// 把一条 shell 命令软折成多行,按续行边界优先断行,续行缩进 4 空格。
/// 优先在空格处断;当**单个 token 本身就比可用宽度还宽**(窄窗口下的长路径/长 URL)、
/// 空格断不开时,退化为按显示宽度**字符级折断**(CJK 安全),让整段可见而不被 paint
/// 层无省略地硬裁。绝不加省略/截断标记——命令必须看得全。
pub(crate) fn format_shell_command(cmd: &str, width: usize) -> Vec<String> {
    let cmd = cmd.trim_end();
    if cmd.is_empty() {
        return vec![String::new()];
    }
    // 1) 先在语义边界切成逻辑段:` \` 续行、` && `、` || `、` | `、` -e `。
    //    保留分隔符在段首(除了 `\` 始终段尾),让读者看清结构。
    let mut segments: Vec<String> = Vec::new();
    let mut cur = String::new();
    let tokens: Vec<&str> = cmd.split(' ').collect();
    let mut i = 0;
    while i < tokens.len() {
        let tok = tokens[i];
        if tok == "\\" {
            // 反斜杠续行留在段尾,断段。
            if !cur.is_empty() {
                cur.push(' ');
            }
            cur.push_str(tok);
            segments.push(std::mem::take(&mut cur));
        } else if tok == "&&" || tok == "||" || tok == "|" {
            // 这些分隔符留在段首(下一个逻辑段开头)。
            if !cur.is_empty() {
                segments.push(std::mem::take(&mut cur));
            }
            cur.push_str(tok);
        } else if tok == "-e" && !cur.is_empty() {
            // `-e` 起新段(sed 常见),留在段首。
            segments.push(std::mem::take(&mut cur));
            cur.push_str(tok);
        } else {
            if !cur.is_empty() {
                cur.push(' ');
            }
            cur.push_str(tok);
        }
        i += 1;
    }
    if !cur.is_empty() {
        segments.push(cur);
    }

    // 2) 每段再按 width 软折(优先空格断);续行缩进 4 空格。
    let indent = "    ";
    let mut out: Vec<String> = Vec::new();
    for (seg_idx, seg) in segments.iter().enumerate() {
        let lead = if seg_idx == 0 { "" } else { indent };
        let mut line = String::from(lead);
        let mut line_len = lead.len();
        for word in seg.split(' ') {
            let wlen = crate::width::display_width(word);
            // 单个 token 本身就比一个续行(去掉缩进)的可用宽度还宽 → 空格断不开,
            // 按显示宽度字符级折断,让整段可见而不被 paint 层无省略地硬裁。仅在
            // token 单独放不下时触发;放得下的 token 永不被切。
            if wlen > width.saturating_sub(indent.len()).max(1) {
                // 先把当前行冲掉,让超宽 token 从新行(可能是行 0 的空 lead)起。
                if line_len > lead.len() {
                    out.push(std::mem::take(&mut line));
                    line.push_str(indent);
                    line_len = indent.len();
                }
                let mut rest = word;
                loop {
                    let avail = width.saturating_sub(line_len).max(1);
                    let (head, tail) = split_head_by_width(rest, avail);
                    line.push_str(head);
                    line_len += crate::width::display_width(head);
                    rest = tail;
                    if rest.is_empty() {
                        break;
                    }
                    out.push(std::mem::take(&mut line));
                    line.push_str(indent);
                    line_len = indent.len();
                }
                continue;
            }
            let need = if line_len == lead.len() {
                wlen
            } else {
                wlen + 1
            };
            if line_len > lead.len() && line_len + need > width {
                out.push(std::mem::take(&mut line));
                line.push_str(indent);
                line_len = indent.len();
            }
            if line_len > lead.len() && !line.ends_with(' ') {
                line.push(' ');
                line_len += 1;
            }
            line.push_str(word);
            line_len += wlen;
        }
        // 跳过纯空白段(连续分隔符可能产生),不产出空行。
        if !line.trim().is_empty() {
            out.push(line);
        }
    }
    if out.is_empty() {
        out.push(String::new());
    }
    out
}

/// Render the `task` tool's `<task ...>` result blocks into clean per-subtask lines:
/// `id · model · ✓ done` (or `✗ failed (reason)`), one per subtask. A single subtask
/// drops its `#1` suffix and appends the result's line count. Falls back to the generic
/// `summarise` if no `<task>` blocks are found (defensive — the format is ours, but a
/// future change or an early error result shouldn't render blank).
pub(crate) fn summarise_task_result(output: &str) -> String {
    // Read a `key="value"` attribute from a `<task ...>` opening tag.
    fn attr<'a>(tag: &'a str, key: &str) -> Option<&'a str> {
        let needle = format!("{key}=\"");
        let s = tag.find(&needle)? + needle.len();
        let rest = &tag[s..];
        rest.find('"').map(|e| &rest[..e])
    }
    // Inner text between `<t>` and `</t>` within a block body.
    fn inner<'a>(body: &'a str, t: &str) -> Option<&'a str> {
        let open = format!("<{t}>");
        let close = format!("</{t}>");
        let s = body.find(&open)? + open.len();
        let e = body[s..].find(&close)? + s;
        Some(body[s..e].trim())
    }

    // Scan block-by-block. A block starts at a LINE-LEADING "<task " (start of output or
    // right after '\n' — render_task_block joins blocks with '\n') and ends at the NEXT
    // "</task>". Crucially we resume the search for the next block AFTER that "</task>",
    // so a "<task " that appears inside a block BODY (e.g. cat'd XML in a worker's output)
    // is never mistaken for a boundary (#3). The closing tag is searched AFTER the opening
    // tag's '>', so a stray '>' in an attribute value can never produce a reverse slice (#6).
    struct Parsed {
        id: String,
        model: String,
        ok: bool,
        reason: Option<String>,
        result_lines: usize,
    }
    let mut parsed: Vec<Parsed> = Vec::new();
    let mut rest = output;
    loop {
        let start = if rest.starts_with("<task ") {
            0
        } else if let Some(i) = rest.find("\n<task ") {
            i + 1 // point at '<'
        } else {
            break;
        };
        let block = &rest[start..]; // begins with "<task "
        let Some(gt) = block.find('>') else { break }; // end of opening tag
                                                       // Close is searched strictly AFTER the opening tag ⇒ close index > gt, no reverse slice.
        let Some(close_rel) = block[gt + 1..].find("</task>") else {
            break;
        };
        let close = gt + 1 + close_rel;
        let tag = &block[..gt];
        let body = &block[gt + 1..close];
        let ok = attr(tag, "state") == Some("completed");
        let reason = if ok {
            None
        } else {
            // Must match TaskTool's error-block emitter (task.rs): "subagent stopped early (Reason): …".
            body.find("subagent stopped early (").and_then(|i| {
                let r = &body[i + "subagent stopped early (".len()..];
                r.find(')').map(|j| r[..j].to_string())
            })
        };
        parsed.push(Parsed {
            id: attr(tag, "id").unwrap_or("subtask").to_string(),
            model: attr(tag, "model").unwrap_or("?").to_string(),
            ok,
            reason,
            result_lines: inner(body, "task_result")
                .map(|s| s.lines().count())
                .unwrap_or(0),
        });
        rest = &block[close + "</task>".len()..];
    }
    if parsed.is_empty() {
        // No parseable block (not a task result, or all malformed) → generic summary.
        return summarise(output);
    }
    let single = parsed.len() == 1;
    let mut lines: Vec<String> = Vec::with_capacity(parsed.len());
    for p in &parsed {
        // "worker#1" → "worker" when there's only one subtask.
        let id = if single {
            p.id.split('#').next().unwrap_or(&p.id)
        } else {
            p.id.as_str()
        };
        let mark = if p.ok {
            "\u{2713} done".to_string()
        } else {
            match &p.reason {
                Some(r) => format!("\u{2717} failed ({r})"),
                None => "\u{2717} failed".to_string(),
            }
        };
        let mut line = format!("{id} \u{b7} {} \u{b7} {mark}", p.model);
        if single && p.ok && p.result_lines > 1 {
            line.push_str(&format!(" ({} lines)", p.result_lines));
        }
        lines.push(line);
    }
    lines.join("\n")
}

/// A plan-mode interception surfaces as a failed tool result whose body is
/// `blocked: plan mode …` — the kernel prefixes every middleware block with `blocked: `,
/// and `PlanModeGate`'s reason starts with `plan mode is active`. Returns the human reason
/// (sans the `blocked: ` prefix) when the result is such a block, so the UI can render a
/// calm `○` hint instead of a ✗ error — plan-mode enforcement is EXPECTED, not a failure.
/// The model still receives the full `blocked: …` ToolResult via the conversation. The link
/// to the gate's wording is by string; if it ever drifts this returns `None` and the normal
/// ✗ result render is used (a harmless fallback, never a panic).
pub(crate) fn plan_mode_block_reason(output: &str, success: bool) -> Option<&str> {
    if success {
        return None;
    }
    let reason = output.strip_prefix("blocked: ")?;
    reason.starts_with("plan mode").then_some(reason)
}

/// Match only the stable, policy-authored credential denial. Do not classify an
/// arbitrary `blocked:` middleware reason as security-sensitive or reflect its
/// model/plugin-controlled text into a privileged-looking red error.
pub(crate) fn credential_policy_blocked(output: &str, success: bool) -> bool {
    !success
        && output.strip_prefix("blocked: ")
            == Some(
                atomcode_capabilities::tools::credential_bash_gate::CREDENTIAL_BASH_DENIAL_REASON,
            )
}

pub(crate) fn batched_edit_display(
    name: &str,
    output: &str,
    success: bool,
) -> Option<crate::state::BatchedEditDisplay> {
    if !success
        || !matches!(
            name,
            "edit_file" | "write_file" | "create_file" | "search_replace"
        )
    {
        return None;
    }
    let entries = crate::render::diff::parse_unified_diff(output, 120);
    if entries.is_empty() {
        return None;
    }
    let mut summary = summarise(output);
    if name == "edit_file" {
        if let Some((file, _)) = summary.split_once(" (") {
            summary = file.to_string();
        }
    }
    let added = entries
        .iter()
        .filter(|entry| entry.kind == crate::render::DiffKind::Add)
        .count();
    let removed = entries
        .iter()
        .filter(|entry| entry.kind == crate::render::DiffKind::Del)
        .count();
    Some(crate::state::BatchedEditDisplay {
        summary,
        diff_stats: (added, removed),
        entries,
    })
}

fn render_credential_policy_error(state: &mut UiState, renderer: &mut dyn Renderer) {
    let message = crate::i18n::t(crate::i18n::Msg::ToolBlockedBySecurityPolicy).into_owned();
    // Keep the sanitized, driver-owned message for the PolicyDenied terminal
    // separator. Never store the rejected command or raw middleware reason here.
    state.last_policy_denial_reason = Some(message.clone());
    state.turn_error_line_shown = true;
    renderer.render(UiLine::Error(message));
}

fn activate_policy_intervention(state: &mut UiState) {
    use atomcode_capabilities::tools::request_user_input::{
        UserInputMode, UserInputOption, UserInputRequest,
    };
    use atomcode_kernel::event::PolicyRecoveryAction;

    let Some(intervention) = state.pending_policy_intervention.as_ref() else {
        return;
    };
    let options = intervention
        .actions
        .iter()
        .map(|action| {
            let (label, description) = match action {
                PolicyRecoveryAction::CompleteExternally => (
                    crate::i18n::Msg::PolicyRecoveryComplete,
                    crate::i18n::Msg::PolicyRecoveryCompleteDesc,
                ),
                PolicyRecoveryAction::SkipStep => (
                    crate::i18n::Msg::PolicyRecoverySkip,
                    crate::i18n::Msg::PolicyRecoverySkipDesc,
                ),
                PolicyRecoveryAction::ViewSafeInstructions => (
                    crate::i18n::Msg::PolicyRecoveryInstructions,
                    crate::i18n::Msg::PolicyRecoveryInstructionsDesc,
                ),
                PolicyRecoveryAction::EndTask => (
                    crate::i18n::Msg::PolicyRecoveryEnd,
                    crate::i18n::Msg::PolicyRecoveryEndDesc,
                ),
                _ => (
                    crate::i18n::Msg::PolicyRecoveryEnd,
                    crate::i18n::Msg::PolicyRecoveryEndDesc,
                ),
            };
            UserInputOption {
                label: crate::i18n::t(label).into_owned(),
                description: Some(crate::i18n::t(description).into_owned()),
            }
        })
        .collect();
    let request = UserInputRequest {
        header: crate::i18n::t(crate::i18n::Msg::PolicyRecoveryHeader).into_owned(),
        question: crate::i18n::t(crate::i18n::Msg::PolicyRecoveryQuestion).into_owned(),
        mode: UserInputMode::Single,
        options,
        custom: false,
    };
    let mut panel = crate::state::UserInputPanel::new(0, &request);
    // Model-authored choice requests force an Other row. This is a driver-owned
    // closed recovery contract, so remove that escape hatch explicitly.
    panel.custom = false;
    panel.checked.truncate(panel.options.len());
    state.user_input_panel = Some(panel);
    state.phase = UiPhase::UserInput;
}

/// A tool result that is an approval/user DENIAL → a calm compact label
/// (localized "denied"), NOT the red ✗ error. Detects the deny messages from
/// approval.rs / write_approval.rs ("denied by approval policy: ...") and
/// runner.rs ("Tool 'X' was denied by the user."). Returns None for successes
/// and non-denial failures (those keep the normal ✗ result). The tool name +
/// args in the raw message are intentionally dropped — the `● Tool(...)` header
/// above already shows them (the redundancy the user complained about).
pub(crate) fn approval_denial_label(output: &str, success: bool) -> Option<String> {
    if success {
        return None;
    }
    if output.contains("denied by approval policy") || output.contains("was denied by the user") {
        Some(crate::i18n::t(crate::i18n::Msg::ToolDenied).into_owned())
    } else {
        None
    }
}

// SessionPicker tests moved alongside the struct in
// `crate::modals::session_picker::tests`.

/// Sync ctx.reasoning_effort from the current default provider's config.
fn sync_reasoning_effort_from_provider(ctx: &mut LoopCtx) {
    let applicable = reasoning_effort_applicable_on_provider(ctx);
    ctx.reasoning_effort = if applicable {
        let sel = ctx.config.effective_model_selection().unwrap_or_default();
        ctx.config
            .provider_config_for_selection(&sel)
            .and_then(|p| p.reasoning_effort)
            .filter(|effort| !effort.eq_ignore_ascii_case("auto"))
    } else {
        None
    };
}

fn apply_reasoning_effort_projection(
    ctx: &mut LoopCtx,
    provider: &str,
    effort: Option<atomcode_kernel::provider::ReasoningEffort>,
    applicable: bool,
) {
    project_reasoning_effort(
        &mut ctx.config,
        &ctx.provider_selection,
        &mut ctx.reasoning_effort,
        provider,
        effort,
        applicable,
    );
}

fn project_reasoning_effort(
    config: &mut Config,
    active_provider: &str,
    active_effort: &mut Option<String>,
    provider: &str,
    effort: Option<atomcode_kernel::provider::ReasoningEffort>,
    applicable: bool,
) {
    let runtime_effort = effort.map(|value| value.as_str().to_string());
    // Keep `/effort`, Ctrl+T and the footer on one local projection. `auto` is
    // the config sentinel for a supported endpoint using its API default.
    let persisted = if applicable {
        runtime_effort.clone().or_else(|| Some("auto".to_string()))
    } else {
        None
    };
    config.update_selection_reasoning(provider, |fields| {
        fields.reasoning_effort.clone_from(&persisted)
    });
    if active_provider == provider {
        *active_effort = runtime_effort;
    }
}

/// Persist the current reasoning_effort to config.toml
fn persist_reasoning_effort(ctx: &mut LoopCtx) {
    let selection = ctx.config.effective_model_selection().unwrap_or_default();
    let effort = ctx.reasoning_effort.clone();
    // Preserve capability when cycling back to API default. `None` in the
    // persisted model means unsupported; `auto` means supported but omitted.
    let persisted_effort = effort.clone().or_else(|| Some("auto".to_string()));
    // Schema-aware write (new-schema `[models.*]` or legacy `[providers.*]`).
    ctx.config.update_selection_reasoning(&selection, |r| {
        *r.reasoning_effort = persisted_effort.clone()
    });
    match ctx.config_store.update(|config| {
        if !config.update_selection_reasoning(&selection, |r| {
            *r.reasoning_effort = persisted_effort.clone()
        }) {
            anyhow::bail!("provider {selection:?} not found");
        }
        Ok(())
    }) {
        Ok(commit) => ctx.observed_config_revision = Some(commit.snapshot.revision),
        Err(e) => eprintln!("[reasoning_effort] failed to save config: {e}"),
    }
}

/// Whether the current selection exposes a reasoning-effort control. Mirrors the
/// daemon's `models_from_config` derivation EXACTLY (an explicitly configured
/// value declares the capability, plus the one built-in CodingPlan DeepSeek V4
/// Flash fallback) so the TUI `/effort`, the webui selector, and the wire gate
/// never disagree. Deliberately NOT gated on `provider_type`: the old
/// `{deepseek, openai}` restriction hid the control in the TUI for any other
/// endpoint the user had explicitly configured with an effort, while the webui
/// still showed it.
fn effort_applicable(reasoning_effort: Option<&str>, selection: &str, model: &str) -> bool {
    reasoning_effort.is_some()
        || (atomcode_config::config::is_codingplan_provider_name(selection)
            && model.eq_ignore_ascii_case("deepseek-v4-flash"))
}

pub(crate) fn reasoning_effort_applicable_on_provider(ctx: &LoopCtx) -> bool {
    let selection = ctx.config.effective_model_selection().unwrap_or_default();
    let Some(provider) = ctx.config.provider_config_for_selection(&selection) else {
        return false;
    };
    effort_applicable(
        provider.reasoning_effort.as_deref(),
        &selection,
        &ctx.model_name,
    )
}

/// The reasoning-effort levels the current selection exposes (canonical order),
/// from its `reasoning_effort_levels` declaration. `None`/empty ⇒ all levels. The
/// single source of truth the Ctrl+T cycle and `/effort` both consult so neither
/// offers a level the endpoint rejects.
pub(crate) fn selection_allowed_efforts(ctx: &LoopCtx) -> Vec<&'static str> {
    let selection = ctx.config.effective_model_selection().unwrap_or_default();
    let levels = ctx
        .config
        .provider_config_for_selection(&selection)
        .and_then(|p| p.reasoning_effort_levels);
    atomcode_config::config::allowed_effort_levels(levels.as_deref())
}

/// Install a [`crate::modals::password::PasswordModal`] as the active modal on
/// `app`. Called from the `askpass_rx` select! arm and from the test below.
#[cfg(unix)]
pub(crate) fn install_password_modal(
    app: &mut App,
    prompt: String,
    reply: tokio::sync::oneshot::Sender<Option<String>>,
) {
    app.active_modal = Some(Box::new(crate::modals::password::PasswordModal::new(
        prompt, reply,
    )));
}

/// Build footer todo progress (current task + completed/total) from a parsed
/// list. An empty list yields `total == 0`, which `build_status` filters out.
pub(crate) fn todo_progress_from_items(
    todos: &[atomcode_capabilities::tools::todo::TodoItem],
) -> crate::render::TodoProgress {
    use atomcode_capabilities::tools::todo::{todo_counts, TodoStatus};
    let (completed, in_progress, total) = todo_counts(todos);
    let current = todos
        .iter()
        .find(|t| t.status == TodoStatus::InProgress)
        .map(|t| t.content.clone());
    let items = todos
        .iter()
        .map(|t| (t.status, t.content.clone()))
        .collect();
    crate::render::TodoProgress {
        current,
        completed,
        in_progress,
        total,
        items,
    }
}

/// Todo progress for the list carried in a single `todowrite` call's args.
/// `Some(total=0)` when the call VALIDLY clears the list (the footer then hides
/// the row) — distinct from `None`, which means "unparseable, keep whatever the
/// footer already shows". The footer todo row is live-only (cleared at turn end),
/// so this is its sole source.
/// Rebuild the id→title cache from the live panel's current items (id = 1-based position), so a
/// `todo update #N` row can show the task NAME. DERIVED from `active_todos` (not accumulated from
/// tool outputs), so a re-plan or /resume that reassigns ids never splices a stale title.
pub(crate) fn sync_todo_titles(state: &mut crate::state::UiState) {
    state.todo_titles = state
        .active_todos
        .as_ref()
        .map(|p| {
            p.items
                .iter()
                .enumerate()
                .map(|(i, (_, content))| ((i + 1) as u64, content.clone()))
                .collect()
        })
        .unwrap_or_default();
}

fn commit_todo_call_result(
    state: &mut crate::state::UiState,
    call_id: &str,
    name: &str,
    success: bool,
) {
    if name != "todowrite" && name != "todo" {
        return;
    }
    if !state.pending_todo_calls.contains_key(call_id) {
        return;
    }
    state
        .pending_todo_results
        .insert(call_id.to_string(), success);
    rebuild_pending_todo_projections(state);
    if state
        .pending_todo_order
        .iter()
        .all(|id| state.pending_todo_results.contains_key(id))
    {
        clear_pending_todo_calls(state);
    }
}

fn stage_todo_call_preview(state: &mut crate::state::UiState, call_id: &str, args: &str) {
    if state.pending_todo_order.is_empty() {
        state.pending_todo_base = Some(todo_items_from_progress(state.active_todos.as_ref()));
    }
    if !state.pending_todo_calls.contains_key(call_id) {
        state.pending_todo_order.push(call_id.to_string());
    }
    state
        .pending_todo_calls
        .insert(call_id.to_string(), args.to_string());
    rebuild_pending_todo_projections(state);
}

fn todo_items_from_progress(
    progress: Option<&crate::render::TodoProgress>,
) -> Vec<atomcode_capabilities::tools::todo::TodoItem> {
    use atomcode_capabilities::tools::todo::TodoItem;
    progress
        .map(|progress| {
            progress
                .items
                .iter()
                .map(|(status, content)| TodoItem {
                    status: *status,
                    content: content.clone(),
                })
                .collect()
        })
        .unwrap_or_default()
}

fn apply_todo_mutation(items: &mut Vec<atomcode_capabilities::tools::todo::TodoItem>, args: &str) {
    if let Some(progress) = todo_progress_from_args(args) {
        *items = todo_items_from_progress(Some(&progress));
    } else {
        atomcode_capabilities::tools::todo::apply_new_todo_action(items, args);
    }
}

fn rebuild_pending_todo_projections(state: &mut crate::state::UiState) {
    let Some(base) = state.pending_todo_base.clone() else {
        state.pending_todo_preview = None;
        return;
    };
    let mut committed = base.clone();
    let mut preview = base;
    let mut has_unresolved = false;
    for call_id in &state.pending_todo_order {
        let Some(args) = state.pending_todo_calls.get(call_id) else {
            continue;
        };
        match state.pending_todo_results.get(call_id).copied() {
            Some(true) => {
                apply_todo_mutation(&mut committed, args);
                apply_todo_mutation(&mut preview, args);
            }
            Some(false) => {}
            None => {
                has_unresolved = true;
                apply_todo_mutation(&mut preview, args);
            }
        }
    }
    state.active_todos = (!committed.is_empty()).then(|| todo_progress_from_items(&committed));
    sync_todo_titles(state);
    state.pending_todo_preview = has_unresolved.then(|| todo_progress_from_items(&preview));
}

pub(crate) fn clear_pending_todo_calls(state: &mut crate::state::UiState) {
    state.pending_todo_calls.clear();
    state.pending_todo_order.clear();
    state.pending_todo_results.clear();
    state.pending_todo_base = None;
    state.pending_todo_preview = None;
}

pub(crate) fn todo_progress_from_args(args: &str) -> Option<crate::render::TodoProgress> {
    atomcode_capabilities::tools::todo::validate_new_todo_plan(args)
        .ok()
        .map(|todos| todo_progress_from_items(&todos))
}

/// Todo panel state derived from a full transcript — the last VALID `todowrite`
/// call wins (mirrors capabilities::derive_current_todos, but over the core
/// conversation message type held by `Session.messages`; tool calls live inside
/// `AssistantWithToolCalls`). `None` when the session never used todowrite, or
/// when the last valid call cleared the list. Used to seed the panel on
/// `/resume` / session switch with zero extra storage.
pub(crate) fn todo_progress_from_messages(
    messages: &[atomcode_kernel::message::Message],
) -> Option<crate::render::TodoProgress> {
    // Use the canonical transcript projection so a resumed panel reflects incremental
    // updates while excluding calls whose correlated tool result failed.
    let todos = atomcode_capabilities::tools::todo::derive_current_todos(messages);
    if todos.is_empty() {
        return None; // no list, or the last valid todowrite cleared it → hide panel
    }
    Some(todo_progress_from_items(&todos))
}

#[cfg(test)]
mod todo_block_tests {
    use super::*;

    #[test]
    fn failed_live_todo_result_discards_staged_mutation() {
        let mut state = crate::state::UiState::new();
        state.active_todos =
            todo_progress_from_args(r#"{"todos":[{"content":"keep","status":"in_progress"}]}"#);
        stage_todo_call_preview(
            &mut state,
            "failed",
            r#"{"action":"add","content":"must not appear"}"#,
        );

        commit_todo_call_result(&mut state, "failed", "todowrite", false);

        let progress = state.active_todos.expect("prior list remains");
        assert_eq!(progress.items.len(), 1);
        assert_eq!(progress.items[0].1, "keep");
        assert!(!state.pending_todo_calls.contains_key("failed"));
    }

    #[test]
    fn in_flight_todo_preview_updates_footer_without_committing_authoritative_state() {
        let mut state = crate::state::UiState::new();
        state.active_todos = todo_progress_from_args(
            r#"{"todos":[{"content":"done","status":"completed"},{"content":"run agents","status":"pending"}]}"#,
        );
        let args = r#"{"action":"update","id":2,"status":"in_progress"}"#;
        stage_todo_call_preview(&mut state, "preview", args);

        assert_eq!(state.active_todos.as_ref().unwrap().in_progress, 0);
        let preview = effective_todo_progress(&state).expect("preview drives live footer");
        assert_eq!(preview.in_progress, 1);
        assert_eq!(preview.current.as_deref(), Some("run agents"));
        assert!(todo_panel_is_active(&state));

        commit_todo_call_result(&mut state, "preview", "todowrite", false);
        assert!(state.pending_todo_preview.is_none());
        assert_eq!(state.active_todos.as_ref().unwrap().in_progress, 0);
    }

    #[test]
    fn successful_todo_preview_becomes_authoritative() {
        let mut state = crate::state::UiState::new();
        state.active_todos =
            todo_progress_from_args(r#"{"todos":[{"content":"run agents","status":"pending"}]}"#);
        let args = r#"{"action":"update","id":1,"status":"in_progress"}"#;
        stage_todo_call_preview(&mut state, "preview", args);

        commit_todo_call_result(&mut state, "preview", "todowrite", true);

        assert!(state.pending_todo_preview.is_none());
        assert_eq!(state.active_todos.as_ref().unwrap().in_progress, 1);
    }

    #[test]
    fn successful_live_todo_result_commits_full_plan_and_action() {
        let mut state = crate::state::UiState::new();
        stage_todo_call_preview(
            &mut state,
            "plan",
            r#"{"todos":[{"content":"first","status":"in_progress"}]}"#,
        );
        commit_todo_call_result(&mut state, "plan", "todowrite", true);
        assert_eq!(state.active_todos.as_ref().unwrap().items[0].1, "first");

        stage_todo_call_preview(&mut state, "add", r#"{"action":"add","content":"second"}"#);
        commit_todo_call_result(&mut state, "add", "todowrite", true);

        let progress = state.active_todos.expect("successful action is committed");
        assert_eq!(progress.items.len(), 2);
        assert_eq!(progress.items[1].1, "second");
    }

    #[test]
    fn concurrent_todo_previews_replay_in_call_order_and_exclude_failures() {
        let mut state = crate::state::UiState::new();
        state.active_todos =
            todo_progress_from_args(r#"{"todos":[{"content":"first","status":"pending"}]}"#);
        stage_todo_call_preview(
            &mut state,
            "a",
            r#"{"action":"update","id":1,"status":"in_progress"}"#,
        );
        stage_todo_call_preview(&mut state, "b", r#"{"action":"add","content":"second"}"#);

        let preview = effective_todo_progress(&state).unwrap();
        assert_eq!(preview.in_progress, 1);
        assert_eq!(preview.items.len(), 2);

        // Resolve out of order: b succeeds while a is still optimistic.
        commit_todo_call_result(&mut state, "b", "todowrite", true);
        let preview = effective_todo_progress(&state).unwrap();
        assert_eq!(preview.in_progress, 1);
        assert_eq!(preview.items.len(), 2);

        // a fails, so only b remains in the authoritative list.
        commit_todo_call_result(&mut state, "a", "todowrite", false);
        assert!(state.pending_todo_preview.is_none());
        let committed = state.active_todos.as_ref().unwrap();
        assert_eq!(committed.in_progress, 0);
        assert_eq!(committed.items.len(), 2);
        assert_eq!(committed.items[1].1, "second");
    }

    #[test]
    fn todo_progress_from_args_carries_current_and_distinguishes_clear() {
        let p = todo_progress_from_args(
            r#"{"todos":[{"content":"a","status":"completed"},{"content":"b","status":"in_progress"},{"content":"c","status":"pending"}]}"#,
        )
        .expect("valid list");
        assert_eq!((p.completed, p.total), (1, 3));
        assert_eq!(p.current.as_deref(), Some("b")); // the in_progress task
                                                     // No task in progress ⇒ current None, counts still populated.
        let done =
            todo_progress_from_args(r#"{"todos":[{"content":"a","status":"completed"}]}"#).unwrap();
        assert_eq!((done.completed, done.total, done.current), (1, 1, None));
        // A VALID clear ⇒ Some(total=0) so the footer suppresses the row rather
        // than falling back to the stale (uncommitted) transcript.
        assert_eq!(
            todo_progress_from_args(r#"{"todos":[]}"#).map(|p| p.total),
            Some(0)
        );
        // Unparseable ⇒ None ⇒ keep whatever the footer already shows.
        assert!(todo_progress_from_args("not json").is_none());
    }

    #[test]
    fn todo_progress_carries_full_items_in_order() {
        let p = todo_progress_from_args(
            r#"{"todos":[
                {"content":"a","status":"completed"},
                {"content":"b","status":"in_progress"},
                {"content":"c","status":"pending"}
            ]}"#,
        )
        .unwrap();
        use atomcode_capabilities::tools::todo::TodoStatus;
        assert_eq!(p.items.len(), 3);
        assert_eq!(p.items[0], (TodoStatus::Completed, "a".to_string()));
        assert_eq!(p.items[1], (TodoStatus::InProgress, "b".to_string()));
        assert_eq!(p.items[2], (TodoStatus::Pending, "c".to_string()));
        assert_eq!((p.completed, p.total), (1, 3));
    }

    #[test]
    fn todo_progress_from_messages_last_valid_wins() {
        use atomcode_kernel::message::Message;
        use atomcode_kernel::tool::ToolCall;
        let mk = |id: &str, args: &str| {
            Message::assistant(
                "",
                vec![ToolCall {
                    id: id.into(),
                    name: "todowrite".into(),
                    arguments: args.into(),
                }],
            )
        };
        let msgs = vec![
            mk("1", r#"{"todos":[{"content":"old","status":"pending"}]}"#),
            mk(
                "2",
                r#"{"todos":[{"content":"a","status":"completed"},{"content":"b","status":"in_progress"}]}"#,
            ),
        ];
        let p = todo_progress_from_messages(&msgs).expect("last valid todowrite → Some");
        assert_eq!((p.completed, p.total), (1, 2)); // LAST call wins
        assert_eq!(p.current.as_deref(), Some("b"));
        assert_eq!(p.items.len(), 2);
        assert!(todo_progress_from_messages(&[]).is_none()); // no todowrite → None
    }

    #[test]
    fn todo_progress_from_messages_folds_incremental_todo_events() {
        // Replay parity: a resumed session must reflect `todo` add/update events, not just the
        // last full-list todowrite (this was the gap the incremental tool introduced).
        use atomcode_kernel::message::Message;
        use atomcode_kernel::tool::ToolCall;
        let call = |id: &str, name: &str, args: &str| {
            Message::assistant(
                "",
                vec![ToolCall {
                    id: id.into(),
                    name: name.into(),
                    arguments: args.into(),
                }],
            )
        };
        let msgs = vec![
            call(
                "1",
                "todowrite",
                r#"{"todos":[{"content":"a","status":"pending"},{"content":"b","status":"pending"}]}"#,
            ),
            call(
                "2",
                "todo",
                r#"{"action":"update","id":1,"status":"completed"}"#,
            ),
            call("3", "todo", r#"{"action":"add","content":"c"}"#),
            call(
                "4",
                "todo",
                r#"{"action":"update","id":3,"status":"in_progress"}"#,
            ),
        ];
        use atomcode_capabilities::tools::todo::TodoStatus;
        let p = todo_progress_from_messages(&msgs).expect("Some");
        assert_eq!(p.total, 3, "the added task is counted");
        assert_eq!(p.completed, 1);
        assert_eq!(
            p.current.as_deref(),
            Some("c"),
            "the in_progress item is #3 'c'"
        );
        assert_eq!(p.items[0], (TodoStatus::Completed, "a".to_string()));
    }
}

#[cfg(test)]
mod task_render_tests {
    use super::*;

    #[test]
    fn header_single_shows_description() {
        let args = r#"{"tasks":[{"description":"create greet.py","prompt":"p","subagent_type":"worker"}]}"#;
        assert_eq!(format_tool_detail("task", args), "create greet.py");
    }

    #[test]
    fn header_multi_shows_count() {
        let args = r#"{"tasks":[{"description":"a","prompt":"p","subagent_type":"worker"},{"description":"b","prompt":"q","subagent_type":"explore"}]}"#;
        assert_eq!(format_tool_detail("task", args), "2 subtasks");
    }

    #[test]
    fn result_single_clean_line_with_model_and_count() {
        let out = "<task id=\"worker#1\" model=\"deepseek-v4-flash\" state=\"completed\">\n<summary>d</summary>\n<task_result>\nline1\nline2\n</task_result>\n</task>";
        let s = summarise_task_result(out);
        // single ⇒ "#1" dropped, model shown, line count appended
        assert_eq!(
            s,
            "worker \u{b7} deepseek-v4-flash \u{b7} \u{2713} done (2 lines)"
        );
    }

    #[test]
    fn result_multi_one_line_each_keeps_index() {
        let out = "<task id=\"worker#1\" model=\"deepseek-v4-flash\" state=\"completed\">\n<summary>a</summary>\n<task_result>\nx\n</task_result>\n</task>\n<task id=\"explore#2\" model=\"glm-5.2\" state=\"completed\">\n<summary>b</summary>\n<task_result>\ny\n</task_result>\n</task>";
        let s = summarise_task_result(out);
        let lines: Vec<&str> = s.lines().collect();
        assert_eq!(lines.len(), 2);
        assert_eq!(
            lines[0],
            "worker#1 \u{b7} deepseek-v4-flash \u{b7} \u{2713} done"
        );
        assert_eq!(lines[1], "explore#2 \u{b7} glm-5.2 \u{b7} \u{2713} done");
    }

    #[test]
    fn result_failure_shows_reason() {
        // Body format must match TaskTool's emitter: "subagent stopped early (Reason): …".
        let out = "<task id=\"worker#1\" model=\"deepseek-v4-flash\" state=\"error\">\n<summary>d</summary>\n<task_error>\nsubagent stopped early (Timeout): byte-idle\n</task_error>\n</task>";
        let s = summarise_task_result(out);
        assert_eq!(
            s,
            "worker \u{b7} deepseek-v4-flash \u{b7} \u{2717} failed (Timeout)"
        );
    }

    #[test]
    fn result_non_task_output_falls_back() {
        // Defensive: not a task block ⇒ generic summarise, not blank.
        let s = summarise_task_result("plain text\nsecond line");
        assert_eq!(s, "plain text (2 lines)");
    }

    #[test]
    fn result_description_with_task_literal_not_missplit() {
        // A description containing an inline "<task " must NOT create a spurious block —
        // only line-leading "<task " (block boundaries) split.
        let out = "<task id=\"worker#1\" model=\"m\" state=\"completed\">\n<summary>fix <task foo> bug</summary>\n<task_result>\nx\ny\n</task_result>\n</task>";
        let s = summarise_task_result(out);
        assert_eq!(s, "worker \u{b7} m \u{b7} \u{2713} done (2 lines)");
    }

    #[test]
    fn result_task_literal_in_body_not_missplit() {
        // A worker's result body containing a LINE-LEADING "<task " must not create a
        // phantom block (the scanner resumes only after the real "</task>").
        let out = "<task id=\"worker#1\" model=\"m\" state=\"completed\">\n<summary>d</summary>\n<task_result>\n<task id=\"999\" x=\"y\">\nstuff\n</task_result>\n</task>";
        let s = summarise_task_result(out);
        let lines: Vec<&str> = s.lines().collect();
        assert_eq!(lines.len(), 1, "body <task must not split: {s}");
        assert_eq!(s, "worker \u{b7} m \u{b7} \u{2713} done (2 lines)");
    }

    #[test]
    fn result_model_name_with_gt_does_not_panic() {
        // Absurd model name containing '>' / '</task>' must degrade gracefully, not panic
        // (workspace is panic=abort, so a reverse slice would kill the process).
        let out = "<task id=\"worker#1\" model=\"weird</task>x\" state=\"completed\">\n<summary>d</summary>\n<task_result>\nx\n</task_result>\n</task>";
        let s = summarise_task_result(out); // must not panic
        assert!(!s.is_empty());
    }

    #[test]
    fn result_malformed_blocks_fall_back_not_blank() {
        // `<task ` present but no closing `>` on any block ⇒ generic summarise, not "".
        let out = "<task id=\"worker#1\" model=\"x\"  (truncated, no gt)";
        let s = summarise_task_result(out);
        assert!(!s.is_empty(), "must not be blank");
        assert!(
            s.contains("truncated"),
            "should fall back to raw summary: {s}"
        );
    }
}

